SELECT 'moj-all-verified-judgments-review-002-chunk-097' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"ac6e0912-fad9-5086-9c2a-c61e1bbca3ea","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة وحشيش مخدر بقصد التعاطي -تعاطي احلشيش املخدر -إدخال احلبوب احملظورة واحلشيش املخدر للسجن -إقامة حد املسكر -التعزير بالسجن واملنع من","document_number":"34121107","case_number":"34121107","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/14","year":"1434","subject":"مخدرات -حيازة حبوب محظورة وحشيش مخدر بقصد التعاطي -تعاطي احلشيش املخدر -إدخال احلبوب احملظورة واحلشيش املخدر للسجن -إقامة حد املسكر -التعزير بالسجن واملنع من","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 34121107 :‬تاريخه ‪1434/3/14 :‬هـ‬\n                        ‫رقم الدعوى ‪34121107 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34231547‬تاريخه‪1434/06/05:‬ه‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة حبــوب محظــورة وحشــيش مخــدر بقصــد التعاطــي‬\n      ‫‪ -‬تعاطــي احلشــيش املخــدر ‪ -‬إدخــال احلبــوب احملظــورة واحلشــيش‬\n      ‫املخــدر للســجن ‪ -‬إقامــة حــد املســكر ‪ -‬التعزيــر بالســجن واملنــع مــن‬\n                                                                        ‫الســفر‪.‬‬\n\n\n\n\n            ‫املواد ‪ 41‬و ‪ 56‬و ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n\n\n\n\n      ‫الئحــة الدعــوى ضــد املدعــى عليــه (مواطــن‪ ،‬ســجني) بحيــازة احلبــوب‬\n      ‫احملظــورة واحلشــيش املخــدر بقصــد التعاطــي‪ ،‬تعاطــي احلشــيش‬\n      ‫املخدر‪،‬إدخــال مــا بحوزتــه مــن احلبــوب احملظــورة واحلشــيش املخــدر‬\n      ‫للســجن‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه‬\n      ‫مبجازاتــه شــرع ًا لقــاء تعاطيــه احلشــيش املخــدر وبعقوبــة الســجن‬\n      ‫ومنعــه مــن الســفر خــارج البــاد بعــد تنفيــذ العقوبــة‪ ،‬مت ضبــط‬\n      ‫املدعــى عليــه حيــث انــه ســجني بعــد تفتيشــه وعثــر معــه علــى حبتــن‬\n      ‫محظورتــن وقطعتــن حشــيش مخــدر‪ ،‬إقــرار املدعــى عليــه بحيــازة‬\n      ‫احلبــوب احملظــورة واحلشــيش املخــدر بقصــد التعاطــي وتعاطيــه احلشــيش‬\n      ‫املخــدر‪ ،‬إنــكار املدعــى عليــه إدخــال مــا بحوزتــه مــن احلبــوب واحلشــيش‬\n\n‫‪21‬‬\n\f‫للســجن‪ ،‬ثبــوت إدانــة املدعــى عليــه باحليــازة للحبــوب احملظــورة‬\n‫واحلشــيش املخــدر بقصــد التعاطــي وتعاطــي احلشــيش املخــدر‪ ،‬عــدم‬\n‫ثبــوت إدانــة املدعــى عليــه بإدخــال مــا بحوزتــه مــن احلبــوب واحلشــيش‬\n‫للســجن‪ ،‬إقامــة حــد املســكر علــى املدعــى عليــه‪ ،‬تعزيــر املدعــى عليــه‬\n‫بالســجن واملنــع مــن الســفر‪،‬االكتفاء بعقوبــة تعاطــي احلبــوب احملظــورة‬\n          ‫بحــد املســكر‪،‬تصديق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وبعــد يف هــذا اليــوم األحــد املوافــق ‪1434/3/22‬هـ ـ الســاعة‬\n‫الثامنــة والنصــف صباح ـ ًا لــدي أنــا‪ ...... /‬القاضــي باحملكمــة‬\n‫اجلزئيــة بالطائــف وبنــاء ًا علــى املعاملــة املقيــدة برقــم ‪ 34638435‬يف‬\n‫‪1434/3/14‬ه ـ واحملالــة إلينــا برقــم ‪ 34121107‬يف ‪1434/3/14‬هـ ـ‬\n‫افتتحــت اجللســة وفيهــا حضــر املدعــى العــام ‪ ......‬بالتعميــد رقــم ‪2367‬‬\n‫فـ ــي ‪1433/3/12‬هـ ـ وادعــى علـ ــى احلاضــر باملجلــس الشــرعي ‪...... /‬‬\n‫ســجل مدنــي رقــم (‪ ).......‬ففــي ‪1434/1/16‬ه ـ مت تفتيــش الســجني‬\n‫املدعــى عليــه مــن قبــل رجــال الضبــط يف الســجن العــام بالطائف وضبط‬\n‫يف قبضــة يــده اليســرى (‪ )2‬حبتــان عليهــا عالمــة عقــار الكبتاجــون‬\n‫وقطعتــان بنيتــان اللــون وزنهمــا مجتمعتــن (‪ )4.2‬جــرام وقــد اثبــت‬\n‫التقريــر الكيميائــي الشــرعي رقــم (‪ )1482‬أن احلبتــان حتتويــان مــادة‬\n‫اإلمفيتامــن احملظــورة وأن القطعتــن حشــيش مخــدر وهــي مــن املــواد‬\n‫املدرجــة بجــداول املخــدرات و املرفقــة بالتعميــم اإلحلاقــي رقــم (‪)74831‬‬\n‫وتاريــخ ‪1431/7/9‬ه ـ وانتهــى التحقيــق إلــى اتهامــه بحيــازة (‪ )2‬حبتــن‬\n‫مــن حبــوب اإلمفيتامــن احملظــورة وقطعتــن مــن احلشــيش املخــدر‬\n\n                                                                                ‫‪22‬‬\n\f     ‫وزنهمــا مجتمعتــن (‪ )4.2‬أربعــة جرامــات واثنــن مــن العشــرة مــن اجلــرام‬\n     ‫بقصــد التعاطــي وتعاطيــه للحشــيش املخــدر واحلبــوب احملظــورة وإدخاله‬\n     ‫للمــواد احملظــورة املضبوطــة داخــل الســجن وبالبحــث عــن ســوابقه لــم‬\n     ‫يعثــر لــه علــى ســوابق مســجلة لــذا اطلــب إثبــات مــا اســند إليــه واحلكــم‬\n     ‫عليــه بالتالــي ‪/1:‬مجازاتــه شــرع ًا لقــاء تعاطيــه احلشــيش املخــدر ‪/2‬جنــه‬\n     ‫اســتناد ًا علــى الفقــرة األولــى مــن املــادة الواحــدة واالربعــن وعلــى املــادة‬\n     ‫(‪ )29‬مــن نظــام الســجن التوقيــف مــع مراعــات الفقــرة (‪ )2‬مــن املــادة‬\n     ‫(‪ )62‬مــن نظــام مكافحــة املخــدرات ‪ /3‬منعــه مــن الســفر خــارج البــاد‬\n     ‫بعــد تنفيــذ العقوبــة اســتناد ًا علــى الفقــرة االولــى مــن املــادة السادســة و‬\n     ‫اخلمســن هــذه دعــواي‪ .‬وبعــرض ذلــك علــى املدعــى عليــه أجــاب بقولــه‪:‬‬\n     ‫مــا ذكــره املدعــي العــام يف دعــواه مــن اتهامــي بحيــازة حبتــن مــن حبوب‬\n     ‫اإلمفيتامــن احملظــورة وقطعتــي حشــيش مخــدر بقصــد التعاطــي وأننــي‬\n     ‫تعاطيــت احلشــيش املخــدر واحلبــوب احملظــورة فكلــه صحيــح وامــا مــا‬\n     ‫ذكــره مــن قيامــي بإدخــال هــذه املضبوطــات إلــى الســجن فغيــر صحيــح‬\n     ‫والصحيــح أننــي ســجني يف قضيــة أخــرى وقــد وجــدت هــذه املضبوطــات‬\n     ‫ملقــاة علــى األرض أثنــاء الطابــور داخــل الســجن فعرفــت انهــا مخــدرات‬\n     ‫فقمــت بالتقاطهــا وأخذهــا فتــم القبــض علــي وهــي بحوزتــي هكــذا‬\n     ‫أجــاب‪ .‬فســألت املدعــي العــام البينــه علــى إدخــال املدعــي عليــه املــواد‬\n     ‫احملظــورة للســجن فأجــاب بقولــه ‪ :‬ليــس لــدي ســوى أوراق ملعاملــة‬\n     ‫هكــذا أجــاب‪ .‬فبعــد ســماعي للدعــوى وإجابــة املدعــى عليــه وهــو‬\n     ‫بكامــل أهليتــه املعتبــره شــرعا بصحــة مــا جــاء فيهــا مــا عــدا إدخــال‬\n     ‫املــواد احملظــورة للســجن ‪ ،‬وبعــد االطــاع علــى أوراق املعاملــة مبــا فيهــا‬\n     ‫محضــر التفتيــش والضبــط ‪ ،‬والتقريــر الكيميائــي الشــرعي املتضمــن‬\n\n\n‫‪23‬‬\n\f‫إيجابيــة العينــات املضبوطــة ملادتــي احلشــيش املخــدر واإلمفيتامــن‬\n‫احملظورتــن وألن املدعــي العــام ليــس لديــه بينــه علــى إدخــال املدعــى‬\n‫عليــه املــواد احملظــورة يف الســجن ســوى أوراق املعاملــة وألنــه ليــس فيهــا‬\n‫مــا يــدل علــى ذلــك ‪ ،‬وألن مــا دفــع بــه املدعــى عليه أمر محتمــل ؛ لتكرر‬\n‫حيــازة املخــدرات داخــل الســجن يف قضايــا أخــرى ‪ ،‬وألن األصــل بــراءة‬\n‫الذمــة ‪ ،‬وبنــاء علــى املــواد احلاديــة واألربعــن والسادســة واخلمســن‬\n‫والســتني مــن نظــام مكافحــة املخــدرات ولعــدم وجــود ســوابق للمدعــى‬\n‫عليــه وألنــه موقــوف يف قضيــة أخــرى بنــاء علــى الدعــوى وإقــراره ومــا‬\n‫ورد يف أوراق املعاملــة ‪ ،‬لهــذا كلــه فقــد صــدر مــا يلــي ‪ :‬أوال‪ :‬ثبــت‬\n‫لــدي تعاطــي املدعــى عليــه للحشــيش املخــدر وحكــم عليــه لقــاء ذلــك‬\n‫بجلــده ثمانــن جلــده حــدا علنــا ‪ .‬ثانيــا ‪ :‬ثبــت لــدي تعاطيــه للحبــوب‬\n‫احملظــورة واكتفيــت بعقوبتــه علــى ذلــك باحلــد املشــار إليــه يف (أوال)‪.‬‬\n‫ثالثــا‪ :‬ثبــت لــدي إدانتــه بحيــازة احلشــيش املخــدر واحلبــوب احملظــورة‬\n‫املضبوطــة بقصــد التعاطــي وحكمــت عليــه لقــاء ذلــك بســجنه أربعــة‬\n‫أشــهر مــن تاريــخ انتهــاء محكوميتــه للقضيــة املوقــوف بهــا حاليــا ومنعــه‬\n‫مــن الســفر خــارج اململكــة ملــدة ســنتني بعــد انتهــاء محكوميتــه‪ .‬رابعــا‪:‬‬\n‫لــم يثبــت لــدي إدانتــه بإدخــال املــواد احملظــورة للســجن وحكمــت‬\n‫بــرد دعــوى املدعــي العــام يف ذلــك وبعــرض ذلــك علــى املدعــي قــرر‬\n‫القناعــة وأمــا املدعــي العــام فقــرر االعتــراض بالئحــة فجــرى إفهامــه‬\n‫بتعليمــات االســتئناف ‪ ،‬وصلــى اهلل وســلم علــى نينــا محمــد ‪ .‬حــرر يف‬\n                                                            ‫‪1434/03/22‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األثنــن املوافــق ‪1434/6/19‬ه ـ‬\n‫افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف وبرفقهــا‬\n\n\n                                                                                    ‫‪24‬‬\n\f     ‫قــرار الدائــرة اجلزائيــة األولــى رقــم (‪ )34231547‬يف ‪1434/6/5‬ه ـ‬\n     ‫املتضمــن املصادقــة علــى احلكــم ‪ ،‬وللمعلوميــة جــرى حتريــر ذلــك ‪،‬‬\n            ‫وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر يف ‪1434/6/19‬هــ‪.‬‬\n\n\n\n\n‫‪25‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":21,"source_page_end":25,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"31f9ec086cff1b68169b8b5de6d4e4469b1de9f286dd9caabe8fd80dd3d2063d","normalized_text_hash":"bf3179eaa6041e4135c194ac766a851eb553e1d340e54c34468d6fcdae13f289","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p21-34121107"},{"id":"c2ad61bf-8c82-5f79-b5d1-b921e771d38c","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة قطع من احلشيش -الشروع يف بيع احلشيش - تعاطي احلشيش -إثبات اإلدانة بشهادة أعضاء الفرقة القابضة -إقامة حد املسكر -التعزير بالسجن واجللد واملنع من السفر واملصادرة وإسقاط شريحة اجلوال.","document_number":"34283677","case_number":"34124390","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/30","year":"1434","subject":"مخدرات -حيازة قطع من احلشيش -الشروع يف بيع احلشيش - تعاطي احلشيش -إثبات اإلدانة بشهادة أعضاء الفرقة القابضة -إقامة حد املسكر -التعزير بالسجن واجللد واملنع من السفر واملصادرة وإسقاط شريحة اجلوال.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34283677:‬تاريخه ‪1434/07/30:‬هـ‬\n                   ‫رقم الدعوى ‪34124390:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34299630‬تاريخه‪1434/08/17 :‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة قطــع مــن احلشــيش ‪ -‬الشــروع يف بيــع احلشــيش ‪-‬‬\n‫تعاطــي احلشــيش ‪ -‬إثبــات اإلدانــة بشــهادة أعضــاء الفرقــة القابضــة‬\n‫‪ -‬إقامــة حــد املســكر ‪ -‬التعزيــر بالســجن واجللــد واملنــع مــن الســفر‬\n                                 ‫واملصــادرة وإســقاط شــريحة اجلــوال‪.‬‬\n\n\n\n\n                                           ‫‪ -1‬قاعدة املرء مؤاخذ بإقراره ‪.‬‬\n‫‪ -2‬مــا نــص عليــه أهــل العلــم مــن إقامــة حــد املســكر علــى متنــاول‬\n                                     ‫احلشــيش (فتــح البــاري‪.)415/10‬‬\n‫‪ -3‬الفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                    ‫العقليــة‪.‬‬\n‫‪ -4‬الفقــرة (‪ )1‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                    ‫العقليــة‪.‬‬\n‫‪ -5‬الفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                    ‫العقليــة‪.‬‬\n‫‪ -6‬الفقــرة (‪ )1‬مــن املــادة (‪ )62‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                    ‫العقليــة‪.‬‬\n           ‫‪ -7‬املادة (‪ )59‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n                                                                                 ‫‪26‬‬\n\f     ‫توجيــه االتهــام للمدعــى عليــه بحيــازة قطــع مــن احلشــيش املخــدر‬\n     ‫بقصــد االجتــار‪ ،‬الشــروع يف بيــع قطعتــن مــن احلشــيش‪ ،‬تعاطــي‬\n     ‫احلشــيش‪ ،‬حيــث ورد بــاغ مــن أحــد املصــادر الســرية عــن قيــام املدعــى‬\n     ‫عليــه بترويــج احلشــيش املخــدر ويســتخدم هاتفــه اجلــوال‪ ،‬مت متكــن‬\n     ‫املصــدر مــن االتصــال علــى املدعــى عليــه وطلــب منــه قطعــة حشــيش‬\n     ‫فوافــق املــروج (املدعــى عليــه)‪ ،‬كانــت املكاملــة علــى مســمع مــن‬\n     ‫الفرقــة القابضــة‪ ،‬ثــم تفتيــش املصــدر وتفتيــش ســيارته ومت تزويــده‬\n     ‫باملبلــغ املرقــم‪ ،‬اجتــه املصــدر ملنــزل املدعــى عليــه فخــرج مــن منزلــه‬\n     ‫وكان حــذر ًا وعنــد اقتــراب الفرقــة القابضــة قــام برمــي شــيء حتــت‬\n     ‫ســيارته عندهــا مت القبــض عليــه‪ ،‬طلــب املدعــي العــام إثبــات مــا أســند‬\n     ‫للمدعــى عليــه احلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة و املنــع‬\n     ‫مــن الســفر ومصــادرة الهاتــف اجلــوال وإســقاط شــريحته‪ ،‬أقــر املدعــى‬\n     ‫عليــه مبــا نســب إليــه وذكــر بــأن قصــده مــن احليــازة االســتعمال‪،‬‬\n     ‫أنكــر الشــروع يف البيــع‪ ،‬أحضــر املدعــي العــام شــهوده أعضــاء الفرقــة‬\n     ‫القابضــة‪ ،‬جــرى االطــاع علــى صحيفــة ســوابق املدعــى عليــه والتقريــر‬\n     ‫الكيميائي‪،‬صــدر احلكــم بثبــوت إدانــة املدعــي عليــه بحيــازة قطعــة‬\n     ‫مــن احلشــيش املخــدر بقصــد الترويــج واالســتعمال‪ ،‬الشــروع يف بيــع‬\n     ‫قطعتــن مــن احلشــيش‪ ،‬اســتخدامه جلوالــه املذكــور يف ذلــك‪ ،‬تعاطــي‬\n     ‫احلشــيش املخــدر‪ ،‬احلكــم عليــه بالســجن واجللــد والغرامــة واملنــع مــن‬\n     ‫الســفر ومصــادرة هاتفــه اجلــوال وإســقاط شــريحته‪ ،‬جلده حد املســكر‬\n                     ‫ثمانــن جلــدة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n‫‪27‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق ‪1434/4/27‬ه ـ لــدي‬\n‫ـاء علــى املعاملــة احملالــة‬\n                           ‫أنــا ‪ ....‬القاضــي باحملكمــة اجلزائيــة بالدمــام وبنـ ً‬\n‫إلينــا مــن رئيــس احملكمــة برقــم (‪ )....‬وتاريــخ ‪1434/3/16‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا حضــر ‪....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫(‪ )....‬وقــدم املدعــي العــام ‪ .....‬الئحــة اإلدعــاء املتضمنــة بصفتــي مدعي ـ ًا‬\n‫عامـ ًا بدائــرة اإلدعــاء العــام لفــرع الهيئــة باملنطقــة الشــرقية أدعــي علــى‬\n‫املذكــور أعــاه باالطــاع علــى محضــر االنتقــال و القبــض والتفتيــش‬\n‫املعــد مــن قبــل رجــال الضبــط اجلنائــي بشــعبة مكافحــة املخــدرات‬\n‫بالدمــام تبــن إنــه يف يــوم األحــد املوافــق ‪1434/2/17‬ه ـ ورد بــاغ مــن‬\n‫أحــد املصــادر الســرية عــن شــخص يدعــى (‪ )....‬يقــوم بترويــج احلشــيش‬\n‫املخــدر يســكن حــي ‪ ....‬ويســتخدم هاتفــه اجلــوال رقــم (‪ )....‬فتــم متكــن‬\n‫املصــدر مــن االتصــال عليــه وطلــب منــه حشــيش مخــدر مببلــغ (‪)200‬‬\n‫مائتــان ريــال ووافقــه املــروج وطلــب منــه احلضــور إلــى املنــزل وكانــت‬\n‫املكاملــة علــى مســمع مــن الفرقــة القابضــة فتــم االنتقــال إلــى املوقــع‬\n‫برفقــة املصــدر بعــد تفتيشــه وتفتيــش ســيارته وتزويــده مببلــغ مرقــم‬\n‫واجتــه إلــى منــزل املــروج يف حــي ‪ .....‬وخــرج شــخص مــن املنــزل‬\n‫املقصــود وكان حــذرا وعنــد اقتــراب الفرقــة القابضــة قــام املــروج‬\n‫برمــي شــي حتــت ســيارته عندهــا مت القبــض عليــه واتضــح انــه املدعــى‬\n‫عليــه وبالبحــث عمــا قــام برميــه اتضــح انــه قطعتــن بنيــة اللــون بلــغ‬\n‫وزنهمــا (‪ )8,6‬ثمانيــة جرامــات وســتة أعشــار اجلــرام وبتفتيــش منزلــه‬\n‫عثــر علــى عــدد (‪ )31‬واحــد وثالثــون قطعــة بنيــة اللــون تــزن جميعهــا‬\n\n                                                                                        ‫‪28‬‬\n\f     ‫(‪ )140.9‬مائــة وأربعــون جــرام وتســعة أعشــار اجلــرام وأثبــت التقريــر‬\n     ‫الكيمــاوي الشــرعي رقــم (‪ )....‬وتاريخ‪1434/2/27‬ه ـ إيجابيــة عينــة‬\n     ‫املضبوطــات ملــادة احلشــيش املخــدر املدرجــة باجلــدول األول فئــة (أ) مــن‬\n     ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وباســتجواب املذكــور‬\n     ‫أقــر بصحــة واقعــة القبــض وان رقــم االتصــال (‪ )....‬يعــود لــه كمــا أقــر‬\n     ‫بحيازتــه احلشــيش املخــدر بقصــد االســتعمال وتعاطيــه لــه وأنكــر بيعــه‬\n     ‫للحشــيش املخــدر وقــد انتهــى التحقيــق إلــى اتهــام بحيازتــه لعــدد (‪)31‬‬\n     ‫إحــدى وثالثــون قطعــه بنيــة اللــون بلــغ وزنهــا (‪ )140,9‬مائــة وأربعــون‬\n     ‫جرامـ ًا وتســعة أعشــار اجلــرام بقصــد االجتــار والشــروع يف بيــع قطعتــن‬\n     ‫منهــا تزنــا (‪ )8,6‬ثمانيــة جرامــات وســتة أعشــار اجلــرام وتعاطيــه‬\n     ‫للحشــيش املخــدر وذلــك وفقــا للفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n     ‫‪ -1‬اعترافــه بصحــة واقعــة القبــض وان رقــم االتصــال الــذي مت التنســيق‬\n     ‫عليــه لعمليــة البيــع يعــود لــه واملدونــة مبحضــر اســتجوابه املرفــق علــى‬\n     ‫اللفــات رقــم (‪-2 )12‬محضــر القبــض والتفتيــش املنــوه عنــه واملــدون على‬\n     ‫الصفحــة رقــم (‪ )12‬املرفــق علــى اللفــة رقــم (‪ -3)1‬التقريــر الكيمــاوي‬\n     ‫الشــرعي املنــوه عنــه املرفــق علــى اللفــة رقــم (‪ -4)13‬مكاملــة املصــدر‬\n     ‫مــع املــروج واالتفــاق علــى شــراء احلشــيش مخــدر علــى مســمع مــن اجلهــة‬\n     ‫القابضــة مــع وجــود كميــة مجــزأة يف منــزل املــروج قرينــة علــى شــروعه‬\n     ‫يف بيــع احلشــيش املخــدر وحيــث إن مــا أقــدم عليــه املذكــور ‪ -‬وهــو‬\n     ‫بكامــل أهليتــه املعتبــرة شــرعا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n     ‫ونظامـ ًا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه مبــا يلــي‪ -1 :‬بعقوبــة‬\n     ‫الســجن واجللــد والغرامــة الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪)38‬‬\n\n\n‫‪29‬‬\n\f‫مــن النظــام مــع إعمــال مقتضــى الفقــرة رقــم (‪ )1‬مــن املــادة (‪ )62‬مــن‬\n‫النظــام مــع إعمــال املــادة (‪ )59‬مــن النظــام‪ -2‬منعــه مــن الســفر إعمــاال‬\n‫ملقتضــى الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )56‬مــن النظــام‪ -3‬مصــادرة‬\n‫الهاتــف اجلــوال العائــد للمذكــور يحمــل الرقــم () الســتخدامه يف بيــع‬\n‫احلشــيش املخــدر وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )53‬مــن النظــام‬\n‫مــع احلكــم بإســقاط شــريحة الهاتــف النقــال وعــدم صرفهــا لنفــس‬\n‫املدعــى عليــه وفقــا لتعميــم ســمو وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ‬\n‫‪1429/2/10-9‬ه ـ وبــاهلل التوفيــق وبســؤال املدعــى عليــه أجــاب بقولــه‬\n‫مــا ذكــره املدعــي العــام مــن حيــازة واحــد وثالثــن قطعــة مــن احلشــيش‬\n‫املخــدر بلــغ وزنهــا مائــة و أربعــن جرامـ ًا وتســعة مــن العشــرة مــن اجلــرام‬\n‫فهــذا صحيــح وكان ذلــك بقصــد التعاطــي واالســتعمال وليــس بقصــد‬\n‫االجتــار ومــا ذكــره مــن تعاطــي احلشــيش املخــدر وأن رقــم اجلــوال (‪)....‬‬\n‫عائــد لــي فهــذا صحيــح أيضـ ًا ومــا ذكــره مــن الشــروع يف بيــع قطعتــن‬\n‫تــزن ثمانيــة جرامــات وســتة مــن العشــرة مــن اجلــرام وأننــي رميتهــا عنــد‬\n‫القبــض علــي فهــذا غيــر صحيــح هــذه إجابتــي وبعــد تدويــن مــا ســبق‬\n‫رفعــت اجللســة لطلــب البينــة مــن املدعــي العــام ويف يــوم األربعــاء املوافــق‬\n‫‪1434/5/29‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــى عليــه املــدون‬\n‫هويتــه ســابق ًا وقــد جــرت الكتابــة لرئيــس فــرع هيئــة التحقيــق واالدعــاء‬\n‫العــام بالشــرقية لطلــب البينــة املثبتــة لصحــة التهمــة املنســوبة للمدعــى‬\n‫عليــه وذلــك باخلطــاب رقــم (‪ )....‬وتاريــخ ‪1434/4/27‬ه ـ إال أنــه لــم‬\n‫يحضــر أحــد وعليــه رفعــت اجللســة لطلــب البينــة مــرة أخــرى مــن املدعــي‬\n‫العــام ويف يــوم االثنــن املوافــق ‪1434/7/3‬ه ـ افتتحــت اجللســة وفيهــا لــم‬\n‫يتــم إحضــار املدعــى عليــه املــدون هويتــه ســابق ًا ولــم حتضــر البينــة املثبتة‬\n\n\n                                                                                         ‫‪30‬‬\n\f     ‫لصحــة التهمــة املنســوبة للمدعــى عليــه لــذا رفعــت اجللســة للتأكيــد على‬\n     ‫املدعــي العــام بإحضــار البينــة ويف يــوم األحــد املوافــق ‪1434/7/16‬ه ـ‬\n     ‫افتتحــت اجللســة وفيهــا حضــر املدعــى عليــه املــدون هويتــه ســابق ًا‬\n     ‫وحضــر ألداء الشــهادة ســعودي مبوجــب بطاقــة الهويــة الوطنيــة رقــم‬\n     ‫(‪ )....‬و‪ ....‬ســعودي مبوجــب بطاقــة الهويــة الوطنيــة رقــم (‪ )....‬وبســؤالهما‬\n     ‫عمــا لديهمــا مــن شــهادة شــهد األول قائــا إننــي أعمــل يف مكافحــة‬\n     ‫املخــدرات بالدمــام وأشــهد بــاهلل العظيــم بــأن أحــد املصــادر أبلغنــا عــن‬\n     ‫قيــام املدعــى عليــه احلاضــر معنــا بترويــج احلشــيش املخــدر فتــم متكــن‬\n     ‫املصــدر مــن االتصــال علــى املدعــى عليــه علــى جوالــه رقــم (‪ )....‬وكانــت‬\n     ‫املكاملــة علــى وضعيــة مكبــر الصــوت فطلــب منه حشــيش مخدر مببلغ‬\n     ‫مائتــي ريــال فوافــق املدعــى عليــه وطلــب مــن املصــدر احلضــور ملنزلــه يف‬\n     ‫ا وانتشــرنا يف‬  ‫حــي ‪ ....‬بالدمــام فانتقلنــا ومعنــا املصــدر وكان راج ـ ً‬\n     ‫املوقــع وكنــت أنــا قريبــا مــن بــاب منــزل املدعــى عليــه وملــا وصــل املصــدر‬\n     ‫خــرج املدعــى عليــه وشــاهدته بنفســي وكان يحمــل معــه بطانيــة وأخــذ‬\n     ‫يتلفــت بشــكل حــذر فلمــا شــاهدنا قــام برمــي قطعتــن كانتــا معــه‬\n     ‫والتــي اتفــق مــع املصــدر علــى بيعهــا لــه واتضــح أنهــا مــن احلشــيش املخــدر‬\n     ‫كمــا قــام برمــي جــوال كان معــه علــى األرض فتــم القبــض عليــه ثــم‬\n     ‫دخلنــا املنــزل ومعنــا الســجانة فضبطنــا فيــه عــدد واحــد وثالثــن قطعــة‬\n     ‫مــن احلشــيش املخــدر كانــت معــدة للترويــج حيــث مت لــف كل قطعــة‬\n     ‫علــى شــكل أصبــع معــد للترويــج هــذا مــا أشــهد بــه واهلل علــى مــا أقــول‬\n     ‫شــهيد كمــا شــهد الثانــي بقولــه إننــي أحــد أعضاء مكافحــة املخدرات‬\n     ‫بالدمــام وأشــهد بــاهلل العظيــم بــأن أحــد املصــادر أخبرنــا بقيــام املدعــى‬\n     ‫عليــه بترويــج احلشــيش املخــدر فتــم متكــن املصــدر مــن االتصــال علــى‬\n\n\n‫‪31‬‬\n\f‫املدعــى عليــه علــى جوالــه رقــم () وطلــب منــه حشــيش مببلــغ مائتــي ريــال‬\n‫فقــال املدعــى عليــه نعــم عنــدي احلشــيش وطلــب مــن املصــدر أن يأتــي‬\n‫ملنزلــه يف حــي ‪ .....‬هــذا مــا أشــهد بــه واهلل علــى مــا أقــول شــهيد وبعــرض‬\n‫الشــاهدين وشــهادتهم علــى املدعــى عليــه قــرر بقولــه أمــا الشــاهدين فــا‬\n‫أعــرف فيهــم أي مطعــن وأمــا شــهادتهم فغيــر صحيحــة حيــث إن املصــدر‬\n‫اتصــل علــي ولــم يطلــب منــي حشــيش بــل ســألني هــل بقــي عنــدك شــيء‬\n‫أي مــن احلشــيش وذلــك أننــي أنــا أشــتري منــه فقلــت لــه باقــي عنــدي وأنــا‬\n‫ال أحتــاج ثــم مت إنهــاء املكاملــة ومــا ذكــره الشــاهد األول مــن أننــي قمت‬\n‫برمــي قطعتــن ورمــي جوالــي عنــد القبــض علــي فهــذا غيــر صحيــح وأمــا‬\n‫مــا مت ضبطــه يف منزلــي فهــذا صحيــح وهــو عائــد لــي بقصــد االســتعمال‬\n‫الشــخصي هكــذا قــرر كمــا حضــر لتزكيــة الشــاهدين كل مــن ‪....‬‬\n‫ســعودي مبوجــب بطاقــة هويــة رقــم (‪ )....‬و‪ ....‬ســعودي مبوجــب بطاقــة‬\n‫هويــة رقــم (‪ )....‬وبســؤالهما عمــا لديهمــا شــهد كل واحــد منهما مبفرده‬\n‫قائــا إننــي أعــرف الشــاهدين معرفــة تامــة وأشــهد بأنهمــا عدلــن ثقتــن‬\n‫هكــذا شــهدا وبعــد تدويــن مــا ســبق رفعــت اجللســة لطلــب مزيــد بينة من‬\n‫املدعــي العــام ويف يــوم األحــد املوافــق ‪1434/7/30‬ه ـ افتتحــت اجللســة‬\n‫وفيهــا حضــر املدعــى عليــه ‪ ........‬املــدون هويتــه ســابق ًا وقــرر املدعــي‬\n‫العــام عــدم وجــود مزيــد بينــة وبعــد تدويــن مــا ســبق جــرى االطــاع علــى‬\n‫التقريــر الكيمــاوي الشــرعي رقــم (‪ )........‬املتضمــن إيجابيــة عينــات‬\n               ‫القطــع املضبوطــة يف هــذه القضيــة ملــادة احلشــيش املخــدر‪.‬‬\n‫كمــا جــرى االطــاع علــى ســوابق املدعــى عليــه املرفقــة بالئحــة االدعــاء‬\n‫واملتضمنة وجود ســابقة واحدة مســجلة عليه عبارة عن حيازة مخدرات‬\n‫وبعرضهــا عليــه أقــر بصحتهــا فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابة‬\n\n\n                                                                                       ‫‪32‬‬\n\f     ‫وحيــث أقــر املدعــى عليــه بتعاطــي احلشــيش املخــدر كمــا أقــر بحيــازة‬\n     ‫واحــد وثالثــن قطعــة مــن احلشــيش بقصد االســتعمال كما أقــر بعائدية‬\n     ‫اجلــوال ذي الرقــم (‪ )........‬لــه واملــرء مؤاخــذ بإقــراره وبنــاء علــى شــهادة‬\n     ‫الشاهدين املعدلني التعديل الشرعي وحيث تضمنت شهادة الشاهدين‬\n     ‫ســماع مكاملــة املصــدر للمدعــى عليــه علــى جوالــه املذكــور و هو يطلب‬\n     ‫منــه حشــيش مخــدر مببلــغ مائتــي ريــال و موافقــة املدعــى عليــه على ذلك‬\n     ‫و طلــب منــه احلضــور ملنزلــه يف حــي ‪ ....‬كمــا تضمنــت شــهادة الشــاهد‬\n     ‫األول قيــام املدعــى عليــه باخلــروج مــن منزلــه عندمــا وصــل لــه املصــدر‬\n     ‫وأنــه عندمــا شــاهد الفرقــة القابضــة قــام برمــي قطعتــن مــن احلشــيش‬\n     ‫كمــا تضمنــت شــهادته أن قطــع احلشــيش الواحــد وثالثــن املضبوطة يف‬\n     ‫منــزل املدعــى عليــه ملفــوف كل منهــا علــى شــكل أصبــع معــد للترويــج‬\n     ‫وبنــاء علــى التقريــر الكيمــاوي الشــرعي املشــار إليــه أعــاه و لوجــود‬\n     ‫ســابقة مســجلة علــى املدعــى عليــه عبــارة عــن حيــازة مخــدرات أقــر‬\n     ‫بصحتهــا واســتناد ًا للفقــرة األولــى مــن املــادة الثامنــة والثالثــن و الفقــرة‬\n     ‫األولــى مــن املــادة الثالثــة واخلمســن والفقــرة األولــى مــن املــادة السادســة‬\n     ‫واخلمســن واملــادة التاســعة واخلمســن والفقــرة األولــى مــن املــادة الثانيــة‬\n     ‫والســتني مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وبنــاء علــى‬\n     ‫مــا نــص عليــه أهــل العلــم مــن إقامــة حــد املســكر علــى متنــاول احلشــيش‬\n     ‫(فتــح البــاري ‪ )10/45‬لــذا فقــد ثبــت لــدي إدانــة املدعــى عليــه مبــا يلــي‪:‬‬\n     ‫حيــازة واحــد وثالثــن قطعــة بلــغ وزنهــا مائــة وأربعــن جرامـ ًا وتســعة مــن‬\n     ‫العشــرة مــن اجلــرام مــن احلشــيش املخــدر بقصــد الترويــج واالســتعمال‬\n     ‫والشــروع يف بيــع قطعتــن مــن احلشــيش واســتخدامه جلوالــه املذكــور يف‬\n     ‫الئحــة الدعــوى يف ذلــك وتعاطــي احلشــيش املخــدر وحكمــت عليــه لقــاء‬\n\n\n‫‪33‬‬\n\f‫ذلــك مبــا يلــي ‪ -1 :‬ســجنه خمــس ســنوات اعتبــار ًا مــن تاريــخ إيقافــه علــى‬\n‫ذمــة هــذه القضيــة وجلــده مائتــن وخمســن جلــدة مفرقــة علــى خمــس‬\n‫دفعــات متســاوية وبــن كل دفعــة و األخــرى مــدة ال تقــل عــن عشــرة‬\n‫أيــام وإلزامــه بدفــع غرامــة ماليــة قدرهــا خمســة آالف ريــال ‪ -2‬منعــه‬\n‫مــن الســفر خــارج اململكــة مــدة خمــس ســنوات تبــدأ بعــد االنتهــاء مــن‬\n‫تنفيــذ عقوبــة الســجن احملكــوم بهــا ‪ -3‬مصــادرة الهاتــف اجلــوال العائــد‬\n‫للمدعــى عليــه املذكــور يف الدعــوى وإســقاط شــريحته وعــدم صرفهــا‬\n‫لــه مــرة أخــرى ‪ -4‬جلــده حــد املســكر ثمانــن جلــدة وبعــرض احلكــم‬\n‫علــى املدعــى عليــه قــرر عــدم القناعــة وطلــب رفــع احلكــم إلــى محكمــة‬\n‫االســتئناف فأجيــب لطلبــه ومت تســليمه نســخة مــن احلكــم وأفهــم بتقدمي‬\n‫اعتراضــه خــال مــدة ثالثــن يومــا وأنــه إذا انتهــت هــذه املــدة ولــم يتقــدم‬\n‫باعتراضــه ســقط حقــه يف االعتــراض وســوف ســيتم رفــع احلكــم إلــى‬\n‫محكمــة االســتئناف بــدون الئحــة اعتراضيــة وقــرر املدعــى العــام عــدم‬\n‫االعتــراض وبــاهلل التوفيــق وصلــى اهلل علــى نيبنــا محمــد وبــه حــرر يف‬\n                                                                    ‫‪1434/7/30‬هـ‪.‬‬\n‫ويف يــوم االثنــن املوافــق ‪1434/9/14‬ه ـ افتتحــت اجللســة الســاعة‬\n‫العاشــرة وخمــس وأربعــن دقيقــة وقــد عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف برقــم (‪ )........‬وتاريــخ ‪1434/9/7‬ه ـ املتعلقــة بدعــوى املدعــي‬\n‫العــام ضــد‪ ........‬وبرفقهــا القــرار الصــادر مــن الدائــرة اجلزائيــة الثانيــة‬\n‫برقــم (‪ )........‬وتاريــخ ‪1434/8/17‬ه ـ املتضمــن املصادقــة علــى احلكــم‬\n‫لــذا جــرى إحلــاق ذلــك حتــى ال يخفــى وبــاهلل التوفيــق وصلــى اهلل علــى‬\n                                     ‫نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n\n\n                                                                                         ‫‪34‬‬\n\f     ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n     ‫املقيــدة لــدى احملكمــة برقــم‪ ........‬وتاريــخ ‪1434/8/10‬ه ـ الــواردة مــن‬\n     ‫فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام املكلــف برقــم‪........‬‬\n     ‫وتاريــخ ‪1434/8/6‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n     ‫باحملكمــة الشــيخ‪ ........‬املســجل برقــم‪ ........‬وتاريــخ ‪1434/7/30‬ه ـ‬\n     ‫اخلــاص بدعــوى‪ ........‬املدعــي العــام ضــد‪ ........‬يف قضيــة مخــدرات وقــد‬\n     ‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة‬\n     ‫القــرار وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا‬\n     ‫املصادقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                        ‫وصحبــه وســلم‪ .‬حــرر يف‪1434/8/14‬هــ‪.‬‬\n\n\n\n\n‫‪35‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":26,"source_page_end":35,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"67976b29fa5f7a920bb886a1e323e649b3e288afd63567867642546c0a748e4c","normalized_text_hash":"b6554f79cc020f78dbbfdc96818ec63e31010b46a385391e0fe60ccd73af8b21","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p26-34283677"},{"id":"21de836a-fdfd-5e0b-b70a-b5f49b1db1fe","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة احلبوب التي حتتوي على مادة اإلمفيتامن املنبه احملظورة بقصد التعاطي والترويج -حيازة احلشيش بقصد التعاطي -تعاطي احلشيش املخدر -توجيه الشبهة بالترويج لكثرة كمية احلبوب -التعزير بالسجن واجللد واملنع من السفر.","document_number":"34170615","case_number":"34130755","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/24","year":"1434","subject":"مخدرات -حيازة احلبوب التي حتتوي على مادة اإلمفيتامن املنبه احملظورة بقصد التعاطي والترويج -حيازة احلشيش بقصد التعاطي -تعاطي احلشيش املخدر -توجيه الشبهة بالترويج لكثرة كمية احلبوب -التعزير بالسجن واجللد واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34170615:‬تاريخه ‪1434/03/24:‬هـ‬\n                    ‫رقم الدعوى ‪34130755:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34210261‬تاريخه‪1434/05/08:‬هـ‬\n\n\n ‫مخــدرات ‪ -‬حيــازة احلبــوب التــي حتتــوي علــى مــادة اإلمفيتامــن‬\n ‫املنبــه احملظــورة بقصــد التعاطــي والترويــج ‪ -‬حيــازة احلشــيش بقصــد‬\n ‫التعاطــي ‪ -‬تعاطــي احلشــيش املخــدر‪ -‬توجيــه الشــبهة بالترويــج لكثــرة‬\n       ‫كميــة احلبــوب ‪ -‬التعزيــر بالســجن واجللــد واملنــع مــن الســفر‪.‬‬\n\n\n\n\n          ‫املادتان ‪ 41‬و ‪ 56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n ‫الئحــة الدعــوى العامــة ضــد املدعــى عليــه بحيــازة عــدد (‪ )170‬مائــة‬\n ‫وســبعني حبــة مــن حبــوب اإلمفيتامــن احملظــورة بقصــد التعاطــي‬\n ‫والترويــج وحيــازة احلشــيش املخــدر بقصــد التعاطــي وتعاطــي احلشــيش‬\n ‫املخدر‪،‬وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه‬\n ‫بالســجن واجللــد والغرامــة ومنعــه مــن الســفر ومجازاتــه شــرع ًا‬\n ‫لتعاطيــه احلشــيش املخــدر ومراعــاة الفقــرة األولــى مــن املــادة (‪)62‬‬\n ‫مــن نظــام مكافحــة املخــدرات بخصــوص تعاطيــه احلبــوب احملظــورة‬\n ‫وحيازتــه لنصــف جــرام مــن احلشــيش املخــدر بقصــد التعاطــي‪ ،‬إقــرار‬\n ‫أن قصــده الترويــج‬\n                   ‫املدعــى عليــه باحليــازة للحبــوب للتعاطــي وإنــكاره َّ‬\n ‫وإقــراره بتعاطــي احلشــيش وحيازتــه لقصــد التعاطــي وتعاطيــه للحبــوب‬\n\n                                                                                ‫‪36‬‬\n\f     ‫احملظــورة وعــدم وجــود بينــة للمدعــي العــام علــى الترويــج‪ ،‬ثبــوت إدانــة‬\n     ‫املدعــى عليــه باحليــازة للحبــوب احملظــورة واحلشــيش لغــرض االســتعمال‬\n     ‫واســتعماله للحبــوب احملظــورة‪ ،‬توجيــه الشــبهة للمدعــى عليــه بالترويــج‬\n     ‫لكثــرة الكميــة‪ ،‬تعزيــر املدعــى عليــه بالســجن واجللــد واملنــع مــن‬\n     ‫الســفر وإقامــة حــد املســكر علــى املدعــى عليــه‪ ،‬تصديــق احلكــم مــن‬\n                                      ‫محكمــة االســتئناف مبكــة املكرمــة‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وبعــد يف هــذا اليــوم الثالثــاء املوافــق ‪1434/3/24‬هـ ـ الســاعة‬\n     ‫التاســعة صباحـ ًا لــدي أنــا ‪ ...........‬القاضــي باحملكمــة اجلزئيــة بالطائــف‬\n     ‫وبناء ًا على املعاملة املقيدة رقم ‪ 34691985‬يف ‪1434/3/18‬هـ واحملالة‬\n     ‫إلينا برقم ‪ 34130755‬يف ‪1434/3/18‬هـ افتتحت اجللســة وفيها حضر‬\n     ‫املدعــى العــام‪ ...........‬بالتعميــد رقــم ‪ ...........‬يف ‪1433/10/18‬هـ ـ وادعــى‬\n     ‫علــى احلاضــر باملجلــس الشــرعي‪ ...........‬ســعودي اجلنســية مبوجــب‬\n     ‫ال لقد انتهى التحقيق إلى توجيه االتهام‬   ‫الســجل املدني رقم ‪ ...........‬قائ ً‬\n     ‫للمدعــى عليــه بحيــازة مائــة وســبعني حبــة مــن احلبــوب التــي حتتــوي علــى‬\n     ‫مــادة اإلمفيتامــن املنبهــة احملظــورة بقصــد التعاطــي والترويــج وحيــازة‬\n     ‫قطعــة حشــيش مخــدر تــزن نصــف اجلــرام بقصــد التعاطــي وتعاطيهمــا‬\n     ‫لــذا أطلــب إثبــات م ــا أســند إليــه واحلكــم عليــه بالتالــي ‪ -1 :‬السج ــن‬\n     ‫واجل ـل ــد والغ ــرامة وفقـ ــا للـفـق ــرة األول ــى م ــن املـ ــادة الثامن ــة والثـالثـيـ ـ ــن‪.‬‬\n     ‫‪ -2‬منعــه مــن الســفر خــارج اململكــة بعــد تنفيــذ العقوبــة وفق ـ ًا للفقــرة‬\n     ‫األولــى مــن املــادة السادســة واخلمســن ‪ -3 .‬مجازاتــه شــرع ًا لتعاطيــه‬\n     ‫احلشــيش املخــدر ‪ .‬ومراعــاة الفقــرة األولــى مــن املــادة الثانيــة والســتني‬\n\n‫‪37‬‬\n\f‫بخصــوص تعاطيــه للحبــوب املنبهــة احملظــورة وحيازتــه لنصــف جــرام‬\n‫مــن احلشــيش املخــدر بقصــد التعاطــي هــذه دعــواي ‪ .‬وبعــرض ذلــك علــى‬\n‫املدعــى عليــه أجــاب بقولــه ‪ :‬مــا ذكــره املدعــي العــام يف دعــواه مــن‬\n‫اتهامــي بحيــازة (‪ )170‬مائــة وســبعني حبــة مــن احلبــوب احملظــورة وقطعــة‬\n‫حشــيش مخــدر بقصــد التعاطــي وأننــي تعاطيــت احلشــيش واحلبــوب‬\n‫ســابق ًا فكلــه صحيــح وأمــا مــا ذكــره مــن أن قصــدي مــن حيــازة‬\n‫احلبــوب الترويــج أيضـ ًا فغيــر صحيــح ‪ ،‬هكــذا أجــاب فســألت املدعــي‬\n‫العــام البينــة علــى أن قصــد املدعــى عليــه مــن هــذه احليــازة الترويــج‬\n‫فأجــاب بقولــه ‪ :‬بينتــي علــى ذلــك أن الكميــة كبيــرة وليــس لــدي‬\n‫ســوى ذلــك هكــذا أجــاب فبعــد ســماعي للدعــوى وإجابــة املدعــى عليــه‬\n‫بصحــة مــا جــاء فيهــا مــن حيــازة احلشــيش واحلبــوب احملظــورة بقصــد‬\n‫التعاطــي وتعاطيــه لهــا ‪ ،‬نافي ـ ًا أن يكــون قصــده مــن حيــازة احلبــوب‬\n‫الترويــج ايض ـ ًا ‪ ،‬وبعــد االطــاع علــى أوراق املعاملــة مبــا فيهــا التقريــر‬\n‫الكيميائــي الشــرعي املتضمــن إيجابيــة العينــات املضبوطــة ملادتــي‬\n‫احلشــيش واالمفيتامــن احملظورتــن وألن بينــة املدعــي العــام فيمــا يتعلــق‬\n‫بقصــد الترويــج غيــر موصلــة وألن كميــة احلبــوب املضبوطــة مــع املدعــى‬\n‫عليــه كبيــرة ممــا يثيــر التهمــة ضــده بأنهــا للترويــج أيضــا ‪ ،‬وبنــاء علــى‬\n‫املادتــن احلاديــة واألربعــن والسادســة واخلمســن مــن نظــام مكافحــة‬\n‫املخــدرات ولعــدم وجــود ســوابق للمدعــى عليــه لهــذا كلــه فقــد صــدر‬\n‫منــي مــا يلــي ‪ :‬أو ًال ‪ :‬ثبــت لــدي إدانــة املدعــى عليــه بتعاطــي احلشــيش‬\n‫املخــدر وحكمــت عليــه لقــاء ذلــك بجلــده ثمانــن جلــده حــد ًا علنـ ًا ‪.‬ثانيـ ًا‬\n‫‪ :‬ثبــت لــدي إدانتــه بتعاطــي احلبــوب احملظــورة واكتفيــت بعقوبتــه علــى‬\n‫ذلك باجللد املشــار إليه يف (أوالً) ‪ .‬ثالث ًا ‪ :‬ثبت لدي إدانته بحيازة (‪)170‬‬\n\n\n                                                                                        ‫‪38‬‬\n\f     ‫مائــة وســبعني حبــة مــن احلبــوب احملظــورة وقطعــة حشــيش مخــدر لقصــد‬\n     ‫التعاطــي وتتوجــه التهمــة ضــده بــأن قصــده مــن حيــازة احلبــوب الترويــج‬\n     ‫أيضـ ًا وحكمــت عليــه لقــاء ذلــك بســجنه ســنة كاملــة مــن تاريــخ إيقافــه‬\n     ‫وجلــده مائــة وخمســن جلــدة مفرقــة علــى ثــاث دفعــات متســاوية يف‬\n     ‫العــدد بــن كل دفعــة وأخــرى مــدة ال تقــل عــن أســبوع كمــا يفصــل‬\n     ‫بينهــا وبــن اجللــد املشــار إليــه يف (أوالً) مبــدة مماثلــة ومنعــه مــن الســفر‬\n     ‫خــارج اململكــة ملــدة ســنتني بعــد انتهــاء محكوميتــه وأخــذ التعهــد عليــه‬\n     ‫بعــدم العــودة ملثــل ذلــك ‪ .‬رابعـ ًا ‪ :‬صرفــت النظــر عــن طلــب املدعــي العــام‬\n     ‫تطبيــق املــادة الثامنــة والثالثــن مــن نظــام مكافحــة املخــدرات ؛ لعــدم‬\n     ‫ثبــوت إدانــة املدعــى عليــه باحليــازة لقصــد الترويــج ‪ ،‬وبعــرض ذلــك علــى‬\n     ‫املدعــى عليــه قــرر القناعــة وأمــا املدعــي العــام فقــرر االعتــراض بالئحــة‬\n     ‫فجــرى إفهامــه بتعليمــات االســتئناف وصلــى اهلل علــى نبينــا محمــد حــرر‬\n                                                                    ‫يف ‪1434/3/24‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم االربعــاء املوافــق ‪1434/5/29‬ه ـ‬\n     ‫افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف وبرفقهــا‬\n     ‫قــرار الدائــرة اجلزائيــة اخلامســة رقــم (‪ )34210261‬يف ‪1434/5/8‬ه ـ‬\n     ‫املتضمــن املصادقــة علــى احلكــم ‪ ،‬وللمعلوميــة جــرى حتريــر ذلــك ‪،‬‬\n                 ‫وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر يف ‪1434/5/29‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ -:‬فقــد‬\n     ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة االســتئناف‬\n     ‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n     ‫رئيــس احملكمــة اجلزائيــة بالطائــف برقــم (‪ )34691985‬وتاريــخ‬\n     ‫‪1434/3/28‬ه ـ املرفــق بهــا القــرار الصــادر م ــن فضيلــة الشــيخ ‪.........../‬‬\n\n\n‫‪39‬‬\n\f‫القاضــي باحملكمــة اجلزائيــة بالطائــف برقــم (‪ )34170615‬وتـ ـ ـ ـ ــاريخ‬\n‫‪1434/3/24‬ه ـ الـمتضم ــن دعــوى املدعــي العــام ضــد ‪ ........... /‬ســعودي‬\n‫اجلنســية املتهــم يف مخــدرات ‪ ،‬احملكــوم فيــه مبــا دون بباطــن القــرار ‪،‬‬\n‫وبدراســة القــرار وصــورة ضبطــه والئحتــه االعتراضيــة قررنــا املوافقــة‬\n‫علــى احلكــم ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آل ـ ـ ــه‬\n                                                                 ‫وصحبــه وســلم ‪...‬‬\n\n\n\n\n                                                                                      ‫‪40‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":36,"source_page_end":40,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"99294c44d068e278b2d090a9f59f13da22f044ddbf881b1a36e52a4cb9a9f680","normalized_text_hash":"23a2fd058a373cc16672e56b2caa93f63b816d19c670306bed2198906504a89b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p36-34170615"},{"id":"e3735e06-aaac-52f3-ba1e-53906df59f7a","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة قطعة دون الوزن من احلشيش املخدر -حيازة سيجارة مخلوطة باحلشيش املخدر بقصد التعاطي -تعاطي احلشيش املخدر -حيازة مفتاح حتتوي غسالته على احلشيش املخدر -إقرار املدعى عليه-عدم وجود سوابق على املدعى عليه -إقامة حد املسكر -النزول عن احلد األدنى بعقوبة السجن - التعزير بالسجن واملنع من السفر.","document_number":"34180358","case_number":"34141080","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/7","year":"1434","subject":"مخدرات -حيازة قطعة دون الوزن من احلشيش املخدر -حيازة سيجارة مخلوطة باحلشيش املخدر بقصد التعاطي -تعاطي احلشيش املخدر -حيازة مفتاح حتتوي غسالته على احلشيش املخدر -إقرار املدعى عليه-عدم وجود سوابق على املدعى عليه -إقامة حد املسكر -النزول عن احلد األدنى بعقوبة السجن - التعزير بالسجن واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34180358:‬تاريخه ‪1434/4/7:‬هـ‬\n                      ‫رقم الدعوى ‪34141080:‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 34228335‬تاريخه‪1434/06/03:‬هـ‬\n\n\n     ‫مخــدرات ‪ -‬حيــازة قطعــة دون الــوزن مــن احلشــيش املخــدر‪ -‬حيــازة‬\n     ‫ســيجارة مخلوطــة باحلشــيش املخــدر بقصــد التعاطــي ‪ -‬تعاطــي‬\n     ‫احلشــيش املخــدر‪ -‬حيــازة مفتــاح حتتــوي غســالته علــى احلشــيش‬\n     ‫املخــدر‪ -‬إقــرار املدعــى عليه‪-‬عــدم وجــود ســوابق علــى املدعــى عليــه‬\n     ‫‪ -‬إقامــة حــد املســكر ‪ -‬النــزول عــن احلــد األدنــى بعقوبــة الســجن ‪-‬‬\n                                     ‫التعزيــر بالســجن واملنــع مــن الســفر‪.‬‬\n\n\n\n\n              ‫‪ -1‬املادة (‪ ) 41‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n              ‫‪ -2‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n              ‫‪ -3‬املادة (‪ ) 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n     ‫دعــوى املدعــى العــام ضــد املدعــى عليــه مواطــن بحيــازة قطعــة دون‬\n     ‫الــوزن مــن احلشــيش املخــدر‪ ،‬حيــازة ســيجارة مخلوطــة باحلشــيش املخــدر‬\n     ‫بقصــد التعاطــي‪ ،‬تعاطــي احلشــيش املخــدر‪ ،‬حيــازة مفتــاح حتتــوي‬\n     ‫غســالته علــى احلشــيش املخــدر‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند‬\n     ‫إليــه واحلكــم عليــه بعقوبــة الســجن واملنــع مــن الســفر‪ ،‬مت القبــض علــى‬\n     ‫املدعــى عليــه بعــد اســتيقاف املدعــى عليــه وتفتيشــه وعثــر معــه علــى‬\n\n‫‪41‬‬\n\f‫مــادة احلشــيش املخــدر‪ ،‬إقــرار املدعــى عليــه‪ ،‬عــدم وجــود ســوابق علــى‬\n‫املدعــى عليــه‪ ،‬إقامــة حــد املســكر‪ ،‬النــزول عــن احلــد األدنــى بعقوبــة‬\n‫الســجن‪ ،‬تعزيــر املدعــى عليــه بالســجن واملنــع مــن الســفر‪ ،‬تصديــق‬\n                                         ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة‬\n‫بينبــع وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بينبع‪/‬املســاعد برقــم ‪ 34141080‬وتاريــخ ‪ 1434/03/25‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 34709905‬وتاريــخ ‪ 1434/03/22‬ه ـ ففــي‬\n‫يــوم الســبت املوافــق‪ 1434/04/06‬ه ـ افتتحــت اجللســة الســاعة ‪: 30‬‬\n‫‪ 09‬وفيهــا حضــر املدعــي العــام بينبــع ‪..........‬املكلــف مبوجــب خطــاب‬\n‫ا بصفتــي مدعيــا‬   ‫رقــم (‪ )..........‬وتاريــخ ‪1433/6/24‬ه ـ وادعــى قائ ـ ً‬\n‫عامـ ًا بدائــر اإلدعــاء العــام لدائــرة التحقيــق مبحافظــة ينبــع أدعــي علــى‬\n‫‪..........‬ســعودي اجلنســية ســجل رقــم (‪ )..........‬والبالــغ مــن العمــر (‪)37‬‬\n‫عام ـ ًا حيــث أنــه بتاريــخ ‪1434/2/10‬ه ـ مت اســتيقاف ســيارة مــن قبــل‬\n‫مكافحــة املخــدرات مــن نــوع ‪ ....‬بقيــادة املتهــم املذكــور وبتفتيشــه‬\n‫شــخصي ًا عثــر علــى مفتــاح بــه آثــار حــرق يشــتبه بأنــه اســتخدمه يف‬\n‫حــرق احلشــيش املخــدر وبتفتيــش الســيارة عثــر بجــوار القيــر قطعــة دون‬\n‫الــوزن يشــتبه أن تكــون حشيش ـ ًا مخــدر ًا ووجــد داخــل الديكــور مــن‬\n‫أمــام الســائق بكــت دخــان عثــر بداخلــه علــى ســيجاره ملفوفــة لــف‬\n‫يــد بلــغ وزنهــا (‪ )1.4‬جرام ـ ًا وأربعــة أعشــار اجلــرام يشــتبه أن تكــون‬\n‫مخلوطــة باحلشــيش املخــدر ‪ .‬وقــد أثبــت التقريــر الكيميائــي الشــرعي‬\n\n                                                                                     ‫‪42‬‬\n\f     ‫رقــم (‪1434 )..........‬ه ـ إيجابيــة غســالة املفتــاح وإيجابيــة مســتخلص‬\n     ‫الســيجارة والقطعــة املرســلة للقنــب ‪-‬احلشــيش املخــدر‪ -‬وهــو مــن‬\n     ‫املــواد اخلاضعــة للرقابــة واملنــوه عنــه يف اجلــدول األول فئــة (أ) مــن نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وباســتجوابه اعتــرف بحيازتــه‬\n     ‫قطعــة دون الــوزن مــن احلشــيش املخــدر وســيجارة بلــغ وزنهــا (‪ )1.4‬جــرام‬\n     ‫وأربعــة أعشــار اجلــرام مخلوطــة باحلشــيش بقصــد التعاطــي وبحيازتــه‬\n     ‫مفتــاح يســتخدمه يف حــرق احلشــيش املخــدر واعتــرف بتعاطيــه احلشــيش‬\n     ‫املخدر ‪ .‬وببحث حالته اجلنائية تبني عدم وجود أي ســابقة مســجلة عليه‬\n     ‫‪.‬وقــد انتهــى التحقيــق بتوجــه االتهــام لــه بحيــازة قطعــة دون الــوزن مــن‬\n     ‫احلشــيش املخــدر وســيجارة مخلوطــة باحلشــيش املخــدر بلــغ وزنهــا (‪)1.4‬‬\n     ‫جــرام وأربعــة أعشــار اجلــرام بقصــد التعاطــي وتعاطيــه لنوعــه وحيــازة‬\n     ‫مفتــاح حتتــوي غســالته علــى احلشــيش املخــدر واملجــرم علــى ذلــك وفقـ ًا‬\n     ‫للمــادة الثالثــة الفقــرة الثانيــة مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬مــا جــاء يف اعترافــه علــى‬\n     ‫ص (‪ )1-2‬مــن دفتــر التحقيــق لفــة (‪ -2 .)13‬مــا ورد مبحضــر القبــض‬\n     ‫املرفــق لفــه (‪ -3 .)1‬مــا ورد بالتقريــر الكيميائــي الشــرعي واملرفــق‬\n     ‫لفــة (‪ .)29‬وحيــث أن مــا أقــدم عليــه املتهــم فعــل محــرم شــرع ًا ومجــرم‬\n     ‫ومعاقــب عليــه نظام ـ ًا وفق ـ ًا للمــادة الثالثــة الفقــرة الثانيــة مــن نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n     ‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ‪ ،‬أطلــب إثبــات مــا أســند إليــه واحلكــم‬\n     ‫عليــه بالعقوبــات التاليــة ‪ -1 :‬الســجن وفق ـ ًا للمــادة (‪ )41‬الفقــرة (‪)1‬‬\n     ‫مــن النظــام املشــار إليــه ‪ -2 .‬منعــه مــن الســفر إلــى خــارج البــاد بعــد‬\n     ‫انتهــاء محكوميتــه وفقـ ًا للفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن النظــام املشــار‬\n\n\n‫‪43‬‬\n\f‫إليــه ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي‬\n‫العــام يف دعــواه صحيــح جملــة وتفصيــل فقــد مت القبــض علــي يف نقطــة‬\n‫التفتيــش وعثــر بحوزتــي علــى قطعــة مــن احلشــيش املخــدر وســيجارة‬\n‫مــن احلشــيش املخــدر القصــد مــن حيازتهــا التعاطــي واالســتعمال فأنــا‬\n‫أتعاطــى احلشــيش املخــدر يف الســابق ومــا حصــل منــي هــو خطــأ ولــن‬\n‫أعــود إليــه أبــد ًا ولــدي أطفــال يدرســون يف املــدارس ووالدتــي مريضــه‬\n‫وبحاجــه ملــن يخدمهــا ويعطيهــا العــاج وليــس لهــا بعــد اهلل إال أنــا‬\n‫وأطلــب مــن فضيلتكــم التخفيــف هكــذا أجــاب ‪ .‬ثــم جــرى االطــاع‬\n‫علــى أوراق املعاملــة وعلــى اعتــراف املدعــى عليــه وكذلــك علــى التقريــر‬\n‫الكيميائــي الشــرعي املرفــق ص (‪ )29‬وبنــاء علــى مــا تقــدم مــن الدعوى‬\n                      ‫واإلجابــة وإلقــرار املدعــى عليــه بدعــوى املدعــي العــام‬\n‫فقــد ثبــت لــدي دعــوى املدعــى العــام ضــد املدعــى عليــه ‪..........‬بحيــازة‬\n‫قطعــة مــن احلشــيش املخــدر وســيجارة مخلوطــة باحلشــيش املخــدر‬\n‫بقصــد االســتعمال وتعاطيــه الســابق للحشــيش املخــدر وبنــاء علــى املــادة‬\n‫(‪ )41‬مــن نظــام املخــدرات واملؤثــرات العقليــة واملــادة (‪ )56‬مــن نفــس‬\n‫النظــام وكذلــك علــى املــادة (‪ )60‬مــن نفــس النظــام بشــأن النــزول عــن‬\n‫احلــد األدنــى مــن العقوبــة املقــررة يف املــادة (‪ )41‬مــن النظــام لدواعــي‬\n‫معتبــرة تقدرهــا احملكمــة حيــث أن املدعــى عليــه ليــس لــه ســوابق وقــد‬\n‫قــرر التوبــة والرجــوع ولألعــذار التــي قدمهــا املدعــى عليــه ونظــر ًا لقلــة‬\n‫الكميــة التــي حــازه فقــد قــررت جلــده احلــد ثمانــون جلــدة دفعــة واحــده‬\n‫لقــاء تعاطيــه احلشــيش املخــدر وحبســه ملــدة ثالثــة أشــهر حتســب منهــا‬\n‫أي فتــرة أوقــف علــى ذمــة هــذه القضيــة ومنعــه مــن الســفر ملــدة ســنتني‬\n‫تبــدأ مــن تاريــخ انتهــاء محكوميتــه وبعرضــه علــى املدعــى عليــه قــرر‬\n\n\n                                                                                      ‫‪44‬‬\n\f     ‫رضــاه وقناعتــه باحلكــم وأمــا املدعــي العــام فلــم يقنــع بــه وطلــب متييــزه‬\n     ‫بــدون الئحــة اعتــراض وأجيــب لطلبــه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/06‬هـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق‪ 1434/07/15‬ه ـ‬\n     ‫افتتحــت اجللســة وفيهــا جــرى االطــاع علــى قــرار محكمــة االســتئناف‬\n     ‫رقــم ( ‪ ) 34228335‬وتاريــخ ‪ 1434/06/03‬واملتضمــن مــا نصــه (‬\n     ‫وبدراســة القــرار وصــورة ضبطــه تقــرر باألكثريــة املوافقــة علــى احلكم‬\n     ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n     ‫قاضــي اســتئناف ‪..........‬ختــم وتوقيــع قاضــي اســتئناف ‪ ..........‬ختــم‬\n     ‫وتوقيــع رئيــس الدائــرة ‪..........‬ختــم وتوقيــع ) انتهــى ‪ .‬وبــاهلل التوفيــق‬\n     ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                    ‫‪ 1434/07/15‬ه ـ‬\n\n\n\n\n‫‪45‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":41,"source_page_end":45,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c7f2faa99e0891486ba3d561af472591c78d9fb9237bb33125608e85c6133320","normalized_text_hash":"5c82f2a8bd80d91563f5cba46024bb64cf9f496e8849a5ae64ddabc9753643b5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p41-34180358"},{"id":"036a1d13-18dc-5cc7-9c23-bb17db1f4462","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -شروع يف إهداء حبوب محظورة وتعاطيها ومحاولة إدخالها إلى السجن -إقرار -إدانة -االكتفاء بالعقوبة األشد- تداخل العقوبات التعزيرية -تعزير بالسجن واجللد واملنع من السفر -رد دعوى.","document_number":"34192492","case_number":"34144482","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم بعد اإلجراء األخير","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/20","year":"1434","subject":"مخدرات -شروع يف إهداء حبوب محظورة وتعاطيها ومحاولة إدخالها إلى السجن -إقرار -إدانة -االكتفاء بالعقوبة األشد- تداخل العقوبات التعزيرية -تعزير بالسجن واجللد واملنع من السفر -رد دعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 34192492 :‬تاريخه ‪1434/4/20 :‬هـ‬\n                       ‫رقم الدعوى ‪34144482 :‬‬\n‫رقم قرار التصديق من محكمة االستئناف‪34309329 :‬‬\n                         ‫تاريخه‪1434/08/29 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬شــروع يف إهــداء حبــوب محظــورة وتعاطيهــا ومحاولــة‬\n      ‫إدخالهــا إلــى الســجن‪ -‬إقــرار‪ -‬إدانــة‪ -‬االكتفــاء بالعقوبــة األشــد‪-‬‬\n      ‫تداخــل العقوبــات التعزيريــة ‪ -‬تعزيــر بالســجن واجللــد واملنــع مــن‬\n                                                          ‫الســفر ‪ -‬رد دعــوى‪.‬‬\n\n\n\n\n       ‫‪ -1‬املادتان (‪ )41‬و(‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n                                ‫‪ -2‬املادة (‪ )29‬من نظام السجن والتوقيف‪.‬‬\n\n\n\n\n      ‫دعوى جزائية عامة ضد املدعى عليه تتضمن طلب إثبات إدانته بحيازة‬\n      ‫احلبــوب احملظــورة بقصــد التعاطــي واإلهــداء وتعاطيــه لهــا والشــروع يف‬\n      ‫إهداءهــا ومحاولــة إدخالهــا داخــل التوقيــف‪ ،‬واحلكــم عليــه بعقوبــة‬\n      ‫الســجن واجللــد والغرامــة واملصــادرة واملنــع مــن الســفر طبقــا لنظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة وبعقوبــة الســجن طبق ـ ًا لنظــام‬\n      ‫الســجن والتوقيــف‪ ،‬طلــب زيــارة أحــد املوقوفــن وكان بحوزتــه كيــس‬\n      ‫بــه عــدد مــن األغــراض وبتفتيشــها عثــر فيهــا علــى احلبــوب احملظــورة‬\n      ‫وبتفيــش ســيارته عثــر فيهــا علــى احلبــوب احملظــورة أيضاً‪ ،‬أثبــت التقرير‬\n      ‫الكيميائــي الشــرعي إيجابيــة العينــة املرســلة لإلمفيتامــن‪ ،‬أقــر أمــام‬\n\n                                                                                       ‫‪46‬‬\n\f     ‫احملكمــة مبــا أســنده إليــه املدعــي العــام‪ ،‬املدعــى عليــه تنطبــق بحقــه‬\n     ‫العقوبــات املنصــوص عليهــا يف نظــام مكافحــة املخــدر ونظــام الســجن‬\n     ‫والتوقيــف فيكتفــى بالعقوبــة األشــد‪ ،‬قضــت احملكمــة بإدانــة املدعــى‬\n     ‫عليــه بجميــع مــا نســب إليــه وقــررت جلــده خمس ـ ًا وســبعني جلــدة دفعــة‬\n     ‫واحــدة وســجنه ملــدة ثــاث ســنوات ومنعــه مــن الســفر خــارج اململكــة‬\n     ‫ملــدة ثــاث ســنوات كمــا قضــت بــرد باقــي طلبــات املدعــي العــام‪،‬‬\n     ‫عــارض املدعــى عليــه واملدعــي العــام علــى احلكــم‪ ،‬قــررت محكمــة‬\n                     ‫االســتئناف املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر‪.‬‬\n\n\n\n\n     ‫اجلزائيــة‬\n        ‫ّ‬         ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ................‬رئيــس احملكمــة‬\n     ‫بســكاكا وبنــاء علــى املعاملــة احملالــة لنــا برقــم ‪ 34144482‬وتاريــخ‬\n     ‫‪1434/03/28‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34767072‬وتاريــخ‬\n     ‫‪1434/03/28‬ه ـ ففــي هــذا اليــوم الثالثــاء املوافــق ‪1434/04/09‬ه ـ‬\n     ‫افتتحــت اجللســة األولــى الســاعة ‪ 09 :00‬وفيهــا قــدم املدعــي العــام‬\n     ‫الئحــة دعــوى عامــة ضــد ‪ ........‬ســعودي بالســجل املدنــي رقــم ‪........‬‬\n     ‫قائــا فيهــا بتاريــخ ‪1434/02/18‬ه ـ ورد إلدارة مكافحــة املخــدرات‬\n     ‫محضــر الفرقــة املناوبــة بــإدارة تنفيــذ األحــكام احلقوقيــة املتضمــن‬\n     ‫حضــور املتهــم املذكــور إليهــم لزيــارة املوقــوف بــاإلدارة‪ /‬وكان بحوزته‬\n     ‫أغــراض داخــل كيــس عبــارة عــن زجاجتــي ‪ .......‬وعلبتــي ســجائر‬\n     ‫وورقــة شــحن ‪ .......‬وأربــع أكيــاس بطاطــس ‪ .......‬وبتفتيــش أكيــاس‬\n     ‫البطاطــس عثــر بداخــل أحدهــا علــى عــدد خمــس حبــات صغيــرة دائريــة‬\n     ‫الشــكل لونهــا بيــج يشــتبه أن تكــون مــن احلبــوب احملظــورة فأفــاد أن‬\n\n‫‪47‬‬\n\f‫ســيارته مــن نــوع ‪ .....‬ســنة الصنــع ‪ .....‬يحمــل لوحــة رقــم (‪ ( )........‬جــرى‬\n‫ا للمصــادرة) علــى قيــد‬    ‫إصــدار أمــر بحجــز الســيارة لكونهــا مح ـ ً‬\n‫التشــغيل ويريــد إطفائهــا وعنــد الذهــاب إلــى الســيارة إلطفــاء احملــرك‬\n‫عثــر بداخــل الســيارة يف درج أكــواب العصيــر علــى عــدد أربــع حبــات‬\n‫إحداهــا مكســورة إلــى نصفــن فتــم القبــض علــى املتهــم (( التصــرف‬\n‫باملتهــم موقــوف اســتناد ًا للقــرار الــوزاري ‪ )) 1900‬وباســتجواب املتهــم‬\n‫اعتــرف مبــا جــاء يف محضــر القبــض والتفتيــش وأن قصــده مــن‬\n‫إدخــال احلبــوب احملظــورة إلــى داخــل التوقيــف أثنــاء الزيــارة ألجــل أن‬\n‫يســتعملها هــو وصديقــه وقــد أثبــت التقريــر الكيميائــي الصــادر مــن‬\n‫مركــز مراقبــة الســموم بتبــوك برقــم ( ‪559‬م ‪ /‬م س ت) وتاريــخ‬\n‫‪1434/03/07‬ه ـ إيجابيــة العينتــن مــن املضبــوط ملــادة اإلمفيتامــن‬\n‫املنبهــة للجهــاز العصبــي واملــدرج باجلــدول الثانــي فئــة (ب) مــن تعميــم‬\n‫صاحــب الســمو امللكــي النائــب الثانــي لرئيــس مجلــس الــوزراء وزيــر‬\n‫الداخليــة رقــم‪ 74831‬وتاريــخ ‪1431/07/09‬هـ ـ وانتهــى التحقيــق إلــى‬\n‫توجيــه االتهــام لــ‪ ...../‬بالشــروع يف إهــداء عــدد (‪ )5‬خمــس حبــات مــن‬\n‫حبــوب اإلمفيتامــن املنبهــة للجهــاز العصبــي املجــرم مبوجــب الفقــرة‬\n‫الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات ومحاولــة‬\n‫إدخالهــا إلــى داخــل التوقيــف ألحــد املوقوفــن واملجــرم مبوجــب الفقــرة‬\n‫(‪ )1‬مــن املــادة (‪ )29‬مــن نظــام الســجن والتوقيــف وحيــازة عــدد (‪ )4‬أربــع‬\n‫حبــات مــن حبــوب اإلمفيتامــن املنبهــة للجهــاز العصبــي بقصــد التعاطــي‬\n‫وتعاطيــه لــذات النــوع يف الســابق واملجــرم مبوجــب الفقــرة الثانيــة مــن‬\n‫املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وذلــك‬\n‫لألدلــة والقرائــن التاليــة‪ -1 :‬مــا جــاء يف اســتجواب املتهــم املــدون علــى‬\n\n\n                                                                                       ‫‪48‬‬\n\f     ‫اللفــات رقــم ( ‪ )10،9،8‬وعلــى الصفحــة رقــم (‪ )18‬مــن ملــف إجــراءات‬\n     ‫ضبــط االســتدالل لفــة رقــم (‪ -2)4‬مــا جــاء يف محضــر القبــض لفــة رقــم‬\n     ‫(‪ -3 )2‬مــا جــاء بالتقريــر الكيميائــي الشــرعي لفــة رقــم (‪ .)20‬وحيــث‬\n     ‫إن مــا أقــدم عليــه املتهــم وهــو بكامــل أهليتــه املعتبــرة شــرعا فعــل محرم‬\n     ‫ومعاقــب عليــه شــرعا ممــا يتعــن معــه إحالته للمحكمة اجلزئية اســتنادا‬\n     ‫للمادتــن (‪ )128،126‬مــن نظــام اإلجــراءات اجلزائيــة فإننــي أطلــب‬\n     ‫إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه باآلتــي‪ ]1 :‬ـ عقوبــة الســجن‬\n     ‫واجللــد والغرامــة بحدهــا األعلــى وفق ـ ًا للفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن‬\n     ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ]2 .‬ـ منعــه مــن الســفر إلــى‬\n     ‫خــارج اململكــة العربيــة الســعودية اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪)56‬‬\n     ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ]3‬ـ مصــادرة الســيارة‬\n     ‫مــن نــوع ‪ .....‬ســنة الصنــع ‪ .....‬يحمــل لوحــة رقــم ( ) ؛ اســتنادا للمادة (‪)53‬‬\n     ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ -]4‬عقوبــة الســجن‬\n     ‫الــواردة يف الفقــرة (‪ )1‬مــن املــادة (‪ )29‬مــن نظــام الســجن والتوقيــف هــذه‬\n     ‫دعــواي وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب بقولــه ما‬\n     ‫ذكــره املدعــي العــام كلــه صحيــح فقــد رغبــت بزيارة صديــق لي يدعى‬\n     ‫‪ .....‬داخــل توقيــف احلقــوق املدنيــة واشــتريت لــه بعــض األغــراض وكان‬\n     ‫يوجــد عنــدي بعــض احلبــوب احملظــورة فوضعــت خمــس حبــات داخــل‬\n     ‫كيــس البطاطــس وبقــي أربــع حبــات بالســيارة فتــم القبــض علــي مــن‬\n     ‫قبــل رجــال األمــن عندمــا قامــوا بتفتيــش األغــراض وقصــدي مــن احليــازة‬\n     ‫هــو التعاطــي وقــد تعاطيــت احلبــوب احملظــورة يف الســابق وقصــدي‬\n     ‫مــن إدخــال احلبــوب أن اتعاطاهــا مــع داخــل التوقيــف علمــا أن ‪........‬‬\n     ‫لــم يطلــب منــي ذلــك هكــذا أجــاب ولــذا جــرى رفــع اجللســة لدراســتها‬\n\n\n‫‪49‬‬\n\f‫وتأملهــا إلــى يــوم الســبت ‪1434/04/13‬ه ـ الســاعة العاشــرة وعليــه‬\n‫جــرى التوقيــع وأقفلــت اجللســة يف متــام الســاعة العاشــرة والنصــف‪ .‬حــرر‬\n‫يف ‪1434/04/09‬ه ـ ويف هــذا اليــوم الســبت املوافق‪1434/04/20‬ه ـ‬\n‫افتتحــت اجللســة الثالثــة يف متــام الســاعة ‪ 08:00‬وفيهــا حضــر املدعــى‬\n‫عليــه هــذا وقــد جــرى االطــاع علــى أوراق املعاملــة فوجــدت مــن بــن‬\n‫طياتهــا التقريــر الكيميائــي الشــرعي رقــم ‪ 559‬م ‪ /‬م س ت املــدون‬\n‫علــى اللفــة العشــرين وباالطــاع عليــه وجدتــه كمــا ذكــر املدعــي‬\n‫العــام يف دعــواه لــذا وبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة وحيــث‬\n‫صــادق املدعــى عليــه علــى دعــوى املدعــي العــام ومؤاخــذة للمدعــى عليــه‬\n‫بإقــراره وإلــى مــا يــدل عليــه التقريــر الكيميائــي الشــرعي املشــار إليــه‬\n‫آنفــا وحيــث إن فعــل املدعــى عليــه يعــد اســتخفافا بالــدور اإلصالحيــة‬\n‫يف محاولــة إدخالــه احلبــوب احملظــورة إلــى مــن بداخلهــا ولوجــود‬\n‫ســابقة علــى املدعــى عليــه بحيــازة واســتعمال املخــدرات ممــا يــدل علــى‬\n‫عــدم ارتداعــه بالعقوبــة الســابقة وحيــث إن مــن مواطــن التشــديد يف‬\n‫املخــدرات واملؤثــرات العقليــة إذا ارتكــب اجلانــي جرميتــه أو جــزءا منهــا‬\n‫يف املؤسســات اإلصالحيــة وحيــث إن املدعــى عليــه ينطبق بحقه نظامان‬\n‫هــو نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ونظــام الســجن‬\n‫والتوقيــف وحيــث نــص النظامــان أنــه إذا كانــت اجلرميــة معاقــب عليهــا‬\n‫مبوجــب نظامــن فتطبــق العقوبــة األشــد مــن هذيــن النظامــن وحيــث‬\n‫إن املدعــى عليــه تنطبــق بحقــه املادتــان احلاديــة واألربعــون والسادســة‬\n‫واخلمســون مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واملــادة‬\n‫التاســعة والعشــرون مــن نظــام الســجن والتوقيــف وحيــث إن العقوبــات‬\n‫التعزيريــة تتداخــل لــذا فقــد ثبــت لــدي إدانــة املدعــى عليــه بالشــروع يف‬\n\n\n                                                                                    ‫‪50‬‬\n\f     ‫إهــداء خمــس حبــات مــن احلبــوب احملظــورة ومحاولــة إدخالهــا إلــى داخــل‬\n     ‫التوقيــف وحيــازة أربــع حبــات مــن احلبــوب احملظــورة وجميعهــا بقصــد‬\n     ‫التعاطــي وتعاطيــه للحبــوب احملظــورة وحيــث إن العقوبــة األشــد هــي‬\n     ‫يف نظــام الســجن والتوقيــف يف مثــل هــذه القضيــة لــذا أوال‪ :‬فقــد قــررت‬\n     ‫تعزيــره وذلــك بســجنه ثــاث ســنوات مــن تاريــخ إيقافــه بنــاء علــى املــادة‬\n     ‫التاســعة والعشــرين مــن نظــام الســجن والتوقيــف ثانيــا‪ :‬مينــع املدعى عليه‬\n     ‫مــن الســفر خــارج اململكــة ملــدة ثــاث ســنوات بعــد انتهــاء محكوميتــه‬\n     ‫ثالثــا‪ :‬يجلــد املدعــى عليــه خمســا وســبعني جلــدة دفعــة واحــدة لقــاء‬\n     ‫تعاطيــه للحبــوب احملظــورة رابعــا‪ :‬حكمــت بــرد طلــب املدعــي العــام‬\n     ‫بتطبيــق املــادة الثامنــة والثالثــن يف فقرتهــا األولــى مــن نظــام مكافحــة‬\n     ‫املخــدرات واملؤثــرات العقليــة لعــدم انطباقهــا بهــذه القضيــة خامســا‪:‬‬\n     ‫صرفــت النظــر عــن طلــب املدعــي العــام مبصــادرة الســيارة مــن نــوع ‪.....‬‬\n     ‫لعــدم انطبــاق نظــام مكافحــة املخــدرات عليهــا يف املصــادرة و بجميــع‬\n     ‫مــا ذكــر قضيــت وبعــرض ذلــك علــى املدعــى عليــه واملدعــي العــام قــررا‬\n     ‫عــدم القناعــة وطلبــا االســتئناف فأفهمتهمــا أنــه ســوف يســلم لــكل‬\n     ‫واحــد منهمــا نســخة مــن احلكــم لالعتــراض عليــه وذلــك يــوم االثنــن‬\n     ‫القــادم املوافــق ‪1434/04/22‬ه ـ وأن لــكل واحــد منهمــا مــدة نظاميــة‬\n     ‫وهــي ثالثــون يومــا مــن ذلــك التاريــخ يقــدم كل واحــد منهمــا الئحتــه‬\n     ‫االعتراضيــة ففهمــا ذلــك وعليــه جــرى التوقيــع وأقفلــت اجللســة يف متــام‬\n     ‫الســاعة الثامنــة والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n     ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/04/20‬ه ـ احلمــد هلل‬\n     ‫اجلزائيــة بســكاكا ويف هــذا‬  ‫ّ‬       ‫وحــده وبعــد فلــدي أنــا رئيــس احملكمــة‬\n     ‫اليــوم االثنــن املوافــق‪ 1434/05/27‬ه ـ افتتحــت اجللســة الســابعة يف متــام‬\n\n\n‫‪51‬‬\n\f‫الســاعة احلاديــة عشــرة هــذا وقــد انتهــت املــدة النظاميــة للمدعــي العــام‬\n‫ولــم يقــدم الئحتــه االعتراضيــة لــذا فقــد ســقط حقــه يف االعتــراض‬\n‫وألمــرت برفــع كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق‬\n‫احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وســلم‪ .‬حــرر يف ‪ 1434/05/27‬ه ـ احلمــد هلل وحــده وبعــد فلــدي‬\n‫اجلزائيــة بســكاكا ويف هــذا اليــوم األحــد املوافــق‬\n                                                   ‫ّ‬      ‫أنــا رئيــس احملكمــة‬\n‫‪1434/07/23‬ه ـ افتتحــت اجللســة الثامنــة يف متــام الســاعة ‪ 00:11‬هــذا‬\n‫وقــد عــادت املعاملــة مــن محكمــة االســتئناف مبنطقــة اجلــوف وبرفقهــا‬\n‫القــرار رقــم ‪ 34241793‬وتاريــخ ‪1434/06/14‬ه ـ واملتضمــن بعــد‬\n‫املقدمــة وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫املعاملــة لوحــظ باألكثريــة أن مــا حكــم بــه فضيلتــه مــن ســجن كثيــر‬\n‫جــدا نظــرا ملــا أبــداه املدعــى عليــه يف الئحتــه مــن وجود اضطراب نفســي‬\n‫لديــه كمــا أن الكميــة قليلــة وال فائــدة مــن طــول فتــرة ســجنه‪ .‬فعلــى‬\n‫فضيلتــه مالحظــة مــا ذكــر وإجــراء موجبــه انتهــى‪ .‬وجوابــا علــى مــا‬\n‫ذكــره أصحــاب الفضيلــة أقــول إنــه ال يخفــى على شــريف علــم أصحاب‬\n‫الفضيلــة مــا تعانيــه هــذه املنطقــة مــن انتشــار املخــدرات بجميــع أنواعهــا‬\n‫لكونهــا منطقــة حدوديــة وال أدل علــى ذلــك مــا يــرد إلــى محكمــة‬\n‫االســتئناف مــن كثــرة قضايــا تهريــب املخــدرات مــن مدينــة القريــات‬\n‫وغيرهــا وقــد ســببت هــذه املخــدرات أمراضــا مزمنــة علــى مســتعمليها‬\n‫كالعنــف العدوانــي والشــك والهلوســة وانفصــام الشــخصية ومــا يعانيــه‬\n‫املدعــى عليــه مــن قبيــل هــذه األمــراض وحيــث إن القاعــدة الشــرعية يف‬\n‫العقــاب أنــه إذا انتشــرت معصيــة وتســاهل النــاس بهــا وجــب التشــديد‬\n‫يف العقوبــة مــن أجــل الــردع والزجــر كمــا أن مــن أســباب تشــديد‬\n\n\n                                                                                     ‫‪52‬‬\n\f     ‫العقوبــة إدخــال املخــدرات إلــى أماكــن التوقيــف ودور التعليــم وحيــث‬\n     ‫وردت التعليمــات بتشــديد العقوبــة علــى مروجــي ومســتعملي املخــدرات‬\n     ‫حســما ملــادة الفســاد ومحاربــة لهــذا الــداء العضــال الــذي فتــك يف عقــول‬\n     ‫شــبابنا لــذا لــم يظهــر لــي ســوى مــا حكمــت بــه وأمــرت برفــع كامــل‬\n     ‫أوراق املعاملــة ألصحــاب الفضيلــة التخــاذ مــا يــرون وعليــه جــرى التوقيــع‬\n     ‫وأقفلــت اجللســة يف متــام الســاعة احلاديــة عشــرة والربــع وبــاهلل التوفيــق‪،‬‬\n     ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                                    ‫‪1434/07/23‬ه ـ‬\n     ‫احلمــد اهلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضاة الدائــرة األولى لتمييز‬\n     ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة اجلــوف علــى املعاملــة‬\n     ‫الــواردة مــن فضيلتــة رئيــس احملكمــة اجلزائيــة بســكاكا الشــيخ‪...../‬‬\n     ‫برقــم ‪ 341557671‬وتاريــخ ‪1434/07/23‬ه ـ املرفــق بهــا القرار الصادر‬\n     ‫مــن فضيلتــه املســجل برقــم ‪ 34192492‬وتاريخ ‪1434/04/20‬هـ اخلاص‬\n     ‫بدعــوى املدعــي العــام ضــد‪ ..../‬يف قضيــة مخــدرات وقــد تضمــن القــرار‬\n     ‫حكــم علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة‬\n     ‫ضبطــه بنــاء علــى قرارنــا رقــم ‪ 34241793‬يف ‪1434/06/14‬ه ـ قررنــا‬\n     ‫املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل‬\n                                    ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪53‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":46,"source_page_end":53,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"deb0588551aafe77111c3d8d4e62eb7c9f637747b25a013caea6fb1ee6dc36ca","normalized_text_hash":"c5123e2e8c491840ec484b47197a233952fa91318ec04a0d6d21f0d89e48f5fe","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p46-34192492"},{"id":"d2df59f5-d64f-518b-9ec6-2e9d6387872d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة أفيون بقصد التعاطي -تعاطي الهيروين -حيازة مخدرات قبل صدور نظام مكافحة املخدرات -عدم قبول الشهادة املكتوبة -تعزير بالقرائن للتهمة القوية -التعزير باجللد.","document_number":"34184868","case_number":"34148702","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/01","year":"1434","subject":"مخدرات -حيازة أفيون بقصد التعاطي -تعاطي الهيروين -حيازة مخدرات قبل صدور نظام مكافحة املخدرات -عدم قبول الشهادة املكتوبة -تعزير بالقرائن للتهمة القوية -التعزير باجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34184868:‬تاريخه ‪1434/04/01:‬هـ‬\n                    ‫رقم الدعوى‪34148702 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 34791605‬تاريخه‪1434/6/26:‬هـ‬\n\n\n  ‫مخــدرات‪ -‬حيــازة أفيــون بقصــد التعاطــي‪ -‬تعاطــي الهيرويــن‪ -‬حيــازة‬\n  ‫مخــدرات قبــل صــدور نظــام مكافحــة املخــدرات‪ -‬عــدم قبــول الشــهادة‬\n           ‫املكتوبــة‪ -‬تعزيــر بالقرائــن للتهمــة القويــة‪ -‬التعزيــر باجللــد‪.‬‬\n\n\n\n\n  ‫‪ -1‬جــاء يف كشــاف القنــاع (‪« :)337/4‬وال يجــوز للقاضــي احلكــم‬\n                                       ‫برؤيــة خــط الشــاهد‪ ..‬إلــخ»‪.‬‬\n                           ‫‪ -2‬املادة (‪ )120‬من نظام املرافعات الشرعية‪.‬‬\n                         ‫‪ -3‬املادة (‪ )169‬من نظام االجراءات اجلزائية‪.‬‬\n\n\n\n\n  ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيــازة األفيــون املخــدر‬\n  ‫وتعاطــي الهيرويــن‪ ،‬واحلكــم عليــه بحــد املســكر وإفهامــه بــأن عقوبتــه‬\n  ‫علــى احليــازة عائــدة لولــي األمــر (الواقعــة قبــل صــدور نظــام مكافحــة‬\n  ‫املخــدرات واملؤثــرات العقليــة)‪ ،‬قبــض علــى املدعــى عليــه أثــر قيامــه‬\n  ‫بإخــراج شــيء مــن جيبــه ورميــه علــى األرض وبتفتيــش املوقــع الــذي‬\n  ‫كان فيــه عثــر علــى قطعــة يشــتبه أن تكــون مــن األفيــون‪ ،‬أثبــت‬\n  ‫التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة ملــادة األفيــون‬\n  ‫املخــدر واعتــرف املدعــى عليــه أمــام جهــة التحقيــق بتعاطــي الهيرويــن‪،‬‬\n\n                                                                                       ‫‪54‬‬\n\f     ‫أنكــر أمــام احملكمــة مــا أســنده إليــه املدعــي العــام ورجــع عــن إقــراره‬\n     ‫بتعاطــي الهيرويــن‪ -‬طلبــت احملكمــة مــن املدعــي العــام تقــدمي بيناتــه‬\n     ‫وقــررت ســماع شــهادة شــهود محضــر القبــض فعجــز املدعــي العــام عــن‬\n     ‫إحضارهــم‪ ،‬مــن املقــرر شــرع ًا ونظام ـ ًا أن الشــهادة تــؤدى مشــافهة يف‬\n     ‫مجلــس احلكــم‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بــرد طلــب‬\n     ‫املدعــي العــام إدانــة املدعــى عليــه بحيــازة األفيــون املخــدر بقصــد‬\n     ‫التعاطــي ووجهــت لــه التهمــة بتعاطــي الهيرويــن وقــررت جلــده ســبعني‬\n     ‫جلــدة دفعــة واحــدة‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام‬\n                 ‫عليــه‪ ،‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة اجلزائيــة بتبــوك‬\n     ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة‬\n     ‫بتبوك‪/‬املكلــف برقــم ‪ 34148702‬وتاريــخ ‪ 1434/04/01‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 34791605‬وتاريــخ ‪ 1434/04/01‬ه ـ ففــي يــوم‬\n     ‫األربعــاء املوافــق‪ 1434/04/10‬ه ـ حضــر املدعي العام ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم ‪ .................‬واملعمــد مــن مرجعــه مبوجــب‬\n     ‫اخلطــاب رقــم ‪........‬يف ‪1433/9/5‬ه ـ وادعــى ضــد احلاضــر معــه ســعودي‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .................‬والــذي يبلــغ مــن العمــر‬\n     ‫(‪ )43‬عامــا قائــا يف تقريــر دعــواه إنــه بتاريــخ ‪1425/12/28‬ه ـ شــوهد‬\n     ‫املدعــى عليــه يقــف يف أحــد الزوايــا و معــه املدعــو (لــم يوجــه لــه االتهــام‬\n     ‫وأطلــق صراحــه اســتنادا للمــادة ‪ 124‬مــن نظــام اإلجــراءات اجلزائيــة‬\n     ‫وعنــد اقتــراب فرقــة يف إدارة مكافحــة املخــدرات مــن املذكــور قــام‬\n\n‫‪55‬‬\n\f‫بإخــراج شــيء مــن جيبــه ورميــه علــى األرض وبالقبــض عليــه وتفتيشــه لم‬\n‫يعثــر معــه علــى شــيء ممنــوع وبتفتيــش املوقــع الــذي كانــا فيــه عثــر علــى‬\n‫قطعة ســوداء اللون يشــتبه أن تكون أفيون بلغ وزنها تســعمائة مليجرام‬\n‫فجــرى اصطحــاب املذكوريــن إلــى مقــر اإلدارة وقــد أثبــت التقريــر‬\n‫الكيميائــي الشــرعي املرفــق رقــم (‪ )........‬لعــام ‪1426‬ه ـ إيجابيــة مــا مت‬\n‫ضبطــه لألفيــون املخــدر وبالبحــث عــن ســوابقه عثــر لــه علــى ســابقة‬\n‫مخــدرات وقــد أســفر التحقيــق معــه عــن اتهامــه بحيــازة قطعــة أفيــون‬\n‫بلــغ وزنهــا تســعمائة مليجــرام بقصــد التعاطــي وتعاطيــه للهرويــن املخــدر‬\n‫مــن قبــل وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه‬\n‫شــرعا ونظامــا لــذا أطلــب أوال‪ :‬إثبــات مــا أســند إليــه ثانيــا‪ :‬احلكــم عليــه‬\n‫بحــد املســكر لقــاء تعاطيــه لــه ثالثــا‪ :‬إفهامــه بــأن عقابــه علــى حيازتــه‬\n‫لتســعمائة ملليجــرام مــن األفيــون املخــدر بقصــد التعاطــي عائــد لولــي‬\n‫األمــر هكــذا ادعــى وبســؤال املدعــى عليــه عــن الدعــوى أجــاب بقولــه‬\n‫مــا جــاء يف دعــوى املدعــي العــام غيــر صحيــح فلــم اتعاطــى الهرويــن ولــم‬\n‫يكــن بحوزتــي أي قطعــة مــن األفيــون أثنــاء القبــض علــي والســابقة‬\n‫املنســوبة إلــي يف الدعــوى صحيحــة وهــي قدميــة هكــذا أجــاب وبطلــب‬\n‫البينــة مــن املدعــي العــام قــال بينتــي مــا جــاء يف الئحــة الدعــوى وأوراق‬\n‫املعاملــة وبالرجــوع ألوراق املعاملــة وجــدت علــى الصفحــة رقــم (‪ )11‬لفــه‬\n‫رقــم(‪ )8‬إقــرارا مؤرخــا بتاريــخ ‪1426/1/3‬ه ـ منســوب للمدعــى عليــه‬\n‫وفيــه أقــر وأعتــرف بأننــي تعاطيــت الهرويــن املخــدر منــذ شــهرين تقريبــا‬\n‫أ‪.‬ه ـ وعليــه توقيــع بالبصمــة منســوب للمدعــى عليــه وبعرضــه عليه أجاب‬\n‫بقولــه صحيــح أننــي قمــت بالتبصيــم علــى هــذا اإلقــرار لكــن مضمونــه‬\n‫غيــر صحيــح فأنــا لــم أذكــر للمحقــق بأننــي اســتعملت الهرويــن هكــذا‬\n\n\n                                                                                        ‫‪56‬‬\n\f     ‫أجــاب وبالرجــوع حملضــر القبــض املــدون علــى الصفحــة األولى مــن اللفة‬\n     ‫رقــم(‪ )6‬جــاء فيــه مــا نصــه إنــه بتاريــخ ‪1425/12/28‬ه ـ وأثنــاء قيامنــا‬\n     ‫مبســح حــي ‪ ........‬بتبــوك شــوهد أحــد األشــخاص املعروفــن لدينــا يف‬\n     ‫مجــال ترويــج املخــدرات وخصوصــا الهرويــن املخــدر يقــف يف أحــد‬\n     ‫الزوايــا و معــه شــخص آخــر وعنــد اقتــراب الدوريــة الرســمية منهمــا قــام‬\n     ‫الشــخص املعــروف والــذي يدعــى بإخــراج شــيء مــن جيبــه ورميــه علــى‬\n     ‫األرض وبالقبــض عليهمــا اتضــح أن الشــخص املعــروف لدينــا يدعــى‬\n     ‫‪ ........‬وهــو مــن مدمنــي ومروجــي املخــدرات وخصوصــا الهرويــن املخــدر‬\n     ‫وبتفتيشــه لــم يعثــر معــه علــى شــيء محظــور أو ممنــوع واتضــح أن األخــر‬\n     ‫يدعــى وبتفتيشــه لــم يعثــر معــه علــى شــيء ممنــوع أو محظــور وبتفتيــش‬\n     ‫املوقــع الــذي كانــا فيــه عثــر علــى قطعــه ســوداء اللــون يشــتبه أن تكــون‬\n     ‫أفيــون بلــغ وزنهــا تســعمائة مليجــرام كمــا عثــر علــى مفاتيــح ســيارة ‪.....‬‬\n     ‫عائــده للمدعــو ‪........‬كمــا أتضــح أن للمدعــو ســيارة مــن نــوع ‪ ....‬رقــم‬\n     ‫اللوحــة (‪ )...‬تقــف علــى اجلانــب اآلخــر مــن الرصيــف وقــد جــرى تفتيشــها‬\n     ‫ولــم يعثــر بهــا علــى ممنوعــات هــذا أ‪.‬ه ـ وحتــت هــذا احملضــر توقيــع‬\n     ‫منســوب ألعضــاء الفرقــة وبعرضــه علــى املدعــى عليــه أجــاب بقولــه مــا‬\n     ‫جــاء يف هــذا احملضــر مــن أننــي رميــت قطعــة األفيــون فغيــر صحيــح وال‬\n     ‫أعلــم عــن هــذه القطعــة شــيئا هكــذا أجــاب وبطلــب إحضــار أعضــاء‬\n     ‫الفرقــة مــن املدعــي العــام قــال ال أســتطيع إحضارهــم ألن القضيــة‬\n     ‫قدميــة وقــد تغيــرت أرقــام األعضــاء وأكتفــي مبــا ورد يف محضرهــم‬\n     ‫هكــذا قــرر كمــا وجــدت علــى اللفــة رقــم (‪ )14‬ســجل بيانــات للمدعــى‬\n     ‫عليــه يتضمــن وجــود ســابقة مخــدرات فنظــرا إلــى مــا دون مــن الدعــوى‬\n     ‫واإلجابــة املتضمنــة إنــكار املدعــى عليــه مــا نســب إليــه وملــا جــاء يف‬\n\n\n‫‪57‬‬\n\f‫إقــرار املدعــى عليــه حتقيقــا مــن أنــه يســتخدم الهرويــن يف الســابق‬\n‫ونظــرا لرجوعــه عــن اإلقــرار ونظــر ًا لعجــز املدعــى العــام عــن إحضــار‬\n‫بينتــه وألن الشــهادة ال بــد أن تــؤدى مشــافهة يف مجلــس احلكــم ملــا نــص‬\n‫عليــه الفقهــاء ومــن ذلــك قولهــم ( وال يجــوز للقاضــي احلكــم برؤيــة خــط‬\n‫الشــاهد احتياطـ ًا للحكــم ) انظــر كشــاف القنــاع (‪ )337/4‬وقــد نــص‬\n‫نظــام املرافعــات الشــرعية مــاده (‪ )120‬علــى أنــه ال يجــوز االســتعانة يف‬\n‫أداء الشــهادة مبذكــرات مكتوبــة بــل يجــب أن تــؤدى شــفوي ًا كمــا‬\n‫نــص نظــام اإلجــراءات اجلزائيــة علــى أن الشــهادة ال بــد أن تــؤدى يف‬\n‫مجلــس القضــاء كمــا يف املــادة (‪ )169‬ونظــر ًا ألن تخلــف الشــاهد عــن‬\n‫ا علــى تراجعــه عــن الشــهادة ومعلــوم أن الشــاهد يف‬        ‫احلضــور يعتبــر دليـ ً‬\n‫حقــوق اهلل تعالــى ال يلــزم باحلضــور وألن الشــاهد واحلالــة هــذه يعتبــر‬\n‫مجهــول وبنــاء علــى جميــع مــا تقــدم لــم يثبــت لــدي إدانــة املدعــى عليــه‬\n‫مبــا نســب إليــه وإمنــا تتوجــه لــه التهمــة بتعاطــي الهرويــن وقــررت بحقــه‬\n‫مــا يلــي أوال تعزيــر املدعــى عليــه بجلــده ســبعني جلــدة دفعــة واحــده ثانيــا‬\n‫رد طلــب املدعــي العــام إفهــام املدعــى عليــه بــأن عقابــه عــن احليــازة عائــد‬\n‫لولــي األمــر لعــدم ثبــوت مــا يدعيــه ومبــا ذكــر حكمــت فقــر احملكــوم‬\n‫عليــه قناعتــه بــه وطلــب املدعــي العــام متييــز احلكــم مكتفيــا بالئحــة‬\n‫الدعــوى عــن الالئحــة االعتراضيــة فأجبتــه لطلبــه وســيتم بعــث كامــل‬\n‫أوراق املعاملــة حلكمــة االســتئناف لتدقيــق احلكــم حســب املتبــع وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                             ‫يف ‪ 1434/04/10‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫مبنطقــة تبــوك بقــرار احملكمــة ومضمــون املصادقــة علــى احلكــم‬\n\n\n                                                                                         ‫‪58‬‬\n\f     ‫وصلــى اهلل علــى نبينــا محمــد والــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪59‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":54,"source_page_end":59,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ea4e3d70e1d00f86093fefed7e40738ab615d6d7a0b17d00fd4f8cfa54fd4949","normalized_text_hash":"f0247a5c4b4916503eb21d3bd4ec5e578800abb45a13180d3a1c39444d053fe5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p54-34184868"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"ac6e0912-fad9-5086-9c2a-c61e1bbca3ea","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة حبوب محظورة وحشيش مخدر بقصد التعاطي -تعاطي احلشيش املخدر -إدخال احلبوب احملظورة واحلشيش املخدر للسجن -إقامة حد املسكر -التعزير بالسجن واملنع من","document_number":"34121107","case_number":"34121107","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/14","year":"1434","subject":"مخدرات -حيازة حبوب محظورة وحشيش مخدر بقصد التعاطي -تعاطي احلشيش املخدر -إدخال احلبوب احملظورة واحلشيش املخدر للسجن -إقامة حد املسكر -التعزير بالسجن واملنع من","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 34121107 :‬تاريخه ‪1434/3/14 :‬هـ‬\n                        ‫رقم الدعوى ‪34121107 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34231547‬تاريخه‪1434/06/05:‬ه‬\n\n\n      ‫مخــدرات ‪ -‬حيــازة حبــوب محظــورة وحشــيش مخــدر بقصــد التعاطــي‬\n      ‫‪ -‬تعاطــي احلشــيش املخــدر ‪ -‬إدخــال احلبــوب احملظــورة واحلشــيش‬\n      ‫املخــدر للســجن ‪ -‬إقامــة حــد املســكر ‪ -‬التعزيــر بالســجن واملنــع مــن‬\n                                                                        ‫الســفر‪.‬‬\n\n\n\n\n            ‫املواد ‪ 41‬و ‪ 56‬و ‪ 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‬\n\n\n\n\n      ‫الئحــة الدعــوى ضــد املدعــى عليــه (مواطــن‪ ،‬ســجني) بحيــازة احلبــوب‬\n      ‫احملظــورة واحلشــيش املخــدر بقصــد التعاطــي‪ ،‬تعاطــي احلشــيش‬\n      ‫املخدر‪،‬إدخــال مــا بحوزتــه مــن احلبــوب احملظــورة واحلشــيش املخــدر‬\n      ‫للســجن‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه‬\n      ‫مبجازاتــه شــرع ًا لقــاء تعاطيــه احلشــيش املخــدر وبعقوبــة الســجن‬\n      ‫ومنعــه مــن الســفر خــارج البــاد بعــد تنفيــذ العقوبــة‪ ،‬مت ضبــط‬\n      ‫املدعــى عليــه حيــث انــه ســجني بعــد تفتيشــه وعثــر معــه علــى حبتــن‬\n      ‫محظورتــن وقطعتــن حشــيش مخــدر‪ ،‬إقــرار املدعــى عليــه بحيــازة‬\n      ‫احلبــوب احملظــورة واحلشــيش املخــدر بقصــد التعاطــي وتعاطيــه احلشــيش‬\n      ‫املخــدر‪ ،‬إنــكار املدعــى عليــه إدخــال مــا بحوزتــه مــن احلبــوب واحلشــيش‬\n\n‫‪21‬‬\n\f‫للســجن‪ ،‬ثبــوت إدانــة املدعــى عليــه باحليــازة للحبــوب احملظــورة‬\n‫واحلشــيش املخــدر بقصــد التعاطــي وتعاطــي احلشــيش املخــدر‪ ،‬عــدم‬\n‫ثبــوت إدانــة املدعــى عليــه بإدخــال مــا بحوزتــه مــن احلبــوب واحلشــيش‬\n‫للســجن‪ ،‬إقامــة حــد املســكر علــى املدعــى عليــه‪ ،‬تعزيــر املدعــى عليــه‬\n‫بالســجن واملنــع مــن الســفر‪،‬االكتفاء بعقوبــة تعاطــي احلبــوب احملظــورة‬\n          ‫بحــد املســكر‪،‬تصديق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وبعــد يف هــذا اليــوم األحــد املوافــق ‪1434/3/22‬هـ ـ الســاعة‬\n‫الثامنــة والنصــف صباح ـ ًا لــدي أنــا‪ ...... /‬القاضــي باحملكمــة‬\n‫اجلزئيــة بالطائــف وبنــاء ًا علــى املعاملــة املقيــدة برقــم ‪ 34638435‬يف‬\n‫‪1434/3/14‬ه ـ واحملالــة إلينــا برقــم ‪ 34121107‬يف ‪1434/3/14‬هـ ـ‬\n‫افتتحــت اجللســة وفيهــا حضــر املدعــى العــام ‪ ......‬بالتعميــد رقــم ‪2367‬‬\n‫فـ ــي ‪1433/3/12‬هـ ـ وادعــى علـ ــى احلاضــر باملجلــس الشــرعي ‪...... /‬‬\n‫ســجل مدنــي رقــم (‪ ).......‬ففــي ‪1434/1/16‬ه ـ مت تفتيــش الســجني‬\n‫املدعــى عليــه مــن قبــل رجــال الضبــط يف الســجن العــام بالطائف وضبط‬\n‫يف قبضــة يــده اليســرى (‪ )2‬حبتــان عليهــا عالمــة عقــار الكبتاجــون‬\n‫وقطعتــان بنيتــان اللــون وزنهمــا مجتمعتــن (‪ )4.2‬جــرام وقــد اثبــت‬\n‫التقريــر الكيميائــي الشــرعي رقــم (‪ )1482‬أن احلبتــان حتتويــان مــادة‬\n‫اإلمفيتامــن احملظــورة وأن القطعتــن حشــيش مخــدر وهــي مــن املــواد‬\n‫املدرجــة بجــداول املخــدرات و املرفقــة بالتعميــم اإلحلاقــي رقــم (‪)74831‬‬\n‫وتاريــخ ‪1431/7/9‬ه ـ وانتهــى التحقيــق إلــى اتهامــه بحيــازة (‪ )2‬حبتــن‬\n‫مــن حبــوب اإلمفيتامــن احملظــورة وقطعتــن مــن احلشــيش املخــدر‬\n\n                                                                                ‫‪22‬‬\n\f     ‫وزنهمــا مجتمعتــن (‪ )4.2‬أربعــة جرامــات واثنــن مــن العشــرة مــن اجلــرام‬\n     ‫بقصــد التعاطــي وتعاطيــه للحشــيش املخــدر واحلبــوب احملظــورة وإدخاله‬\n     ‫للمــواد احملظــورة املضبوطــة داخــل الســجن وبالبحــث عــن ســوابقه لــم‬\n     ‫يعثــر لــه علــى ســوابق مســجلة لــذا اطلــب إثبــات مــا اســند إليــه واحلكــم‬\n     ‫عليــه بالتالــي ‪/1:‬مجازاتــه شــرع ًا لقــاء تعاطيــه احلشــيش املخــدر ‪/2‬جنــه‬\n     ‫اســتناد ًا علــى الفقــرة األولــى مــن املــادة الواحــدة واالربعــن وعلــى املــادة‬\n     ‫(‪ )29‬مــن نظــام الســجن التوقيــف مــع مراعــات الفقــرة (‪ )2‬مــن املــادة‬\n     ‫(‪ )62‬مــن نظــام مكافحــة املخــدرات ‪ /3‬منعــه مــن الســفر خــارج البــاد‬\n     ‫بعــد تنفيــذ العقوبــة اســتناد ًا علــى الفقــرة االولــى مــن املــادة السادســة و‬\n     ‫اخلمســن هــذه دعــواي‪ .‬وبعــرض ذلــك علــى املدعــى عليــه أجــاب بقولــه‪:‬‬\n     ‫مــا ذكــره املدعــي العــام يف دعــواه مــن اتهامــي بحيــازة حبتــن مــن حبوب‬\n     ‫اإلمفيتامــن احملظــورة وقطعتــي حشــيش مخــدر بقصــد التعاطــي وأننــي‬\n     ‫تعاطيــت احلشــيش املخــدر واحلبــوب احملظــورة فكلــه صحيــح وامــا مــا‬\n     ‫ذكــره مــن قيامــي بإدخــال هــذه املضبوطــات إلــى الســجن فغيــر صحيــح‬\n     ‫والصحيــح أننــي ســجني يف قضيــة أخــرى وقــد وجــدت هــذه املضبوطــات‬\n     ‫ملقــاة علــى األرض أثنــاء الطابــور داخــل الســجن فعرفــت انهــا مخــدرات‬\n     ‫فقمــت بالتقاطهــا وأخذهــا فتــم القبــض علــي وهــي بحوزتــي هكــذا‬\n     ‫أجــاب‪ .‬فســألت املدعــي العــام البينــه علــى إدخــال املدعــي عليــه املــواد‬\n     ‫احملظــورة للســجن فأجــاب بقولــه ‪ :‬ليــس لــدي ســوى أوراق ملعاملــة‬\n     ‫هكــذا أجــاب‪ .‬فبعــد ســماعي للدعــوى وإجابــة املدعــى عليــه وهــو‬\n     ‫بكامــل أهليتــه املعتبــره شــرعا بصحــة مــا جــاء فيهــا مــا عــدا إدخــال‬\n     ‫املــواد احملظــورة للســجن ‪ ،‬وبعــد االطــاع علــى أوراق املعاملــة مبــا فيهــا‬\n     ‫محضــر التفتيــش والضبــط ‪ ،‬والتقريــر الكيميائــي الشــرعي املتضمــن‬\n\n\n‫‪23‬‬\n\f‫إيجابيــة العينــات املضبوطــة ملادتــي احلشــيش املخــدر واإلمفيتامــن‬\n‫احملظورتــن وألن املدعــي العــام ليــس لديــه بينــه علــى إدخــال املدعــى‬\n‫عليــه املــواد احملظــورة يف الســجن ســوى أوراق املعاملــة وألنــه ليــس فيهــا‬\n‫مــا يــدل علــى ذلــك ‪ ،‬وألن مــا دفــع بــه املدعــى عليه أمر محتمــل ؛ لتكرر‬\n‫حيــازة املخــدرات داخــل الســجن يف قضايــا أخــرى ‪ ،‬وألن األصــل بــراءة‬\n‫الذمــة ‪ ،‬وبنــاء علــى املــواد احلاديــة واألربعــن والسادســة واخلمســن‬\n‫والســتني مــن نظــام مكافحــة املخــدرات ولعــدم وجــود ســوابق للمدعــى‬\n‫عليــه وألنــه موقــوف يف قضيــة أخــرى بنــاء علــى الدعــوى وإقــراره ومــا‬\n‫ورد يف أوراق املعاملــة ‪ ،‬لهــذا كلــه فقــد صــدر مــا يلــي ‪ :‬أوال‪ :‬ثبــت‬\n‫لــدي تعاطــي املدعــى عليــه للحشــيش املخــدر وحكــم عليــه لقــاء ذلــك‬\n‫بجلــده ثمانــن جلــده حــدا علنــا ‪ .‬ثانيــا ‪ :‬ثبــت لــدي تعاطيــه للحبــوب‬\n‫احملظــورة واكتفيــت بعقوبتــه علــى ذلــك باحلــد املشــار إليــه يف (أوال)‪.‬‬\n‫ثالثــا‪ :‬ثبــت لــدي إدانتــه بحيــازة احلشــيش املخــدر واحلبــوب احملظــورة‬\n‫املضبوطــة بقصــد التعاطــي وحكمــت عليــه لقــاء ذلــك بســجنه أربعــة‬\n‫أشــهر مــن تاريــخ انتهــاء محكوميتــه للقضيــة املوقــوف بهــا حاليــا ومنعــه‬\n‫مــن الســفر خــارج اململكــة ملــدة ســنتني بعــد انتهــاء محكوميتــه‪ .‬رابعــا‪:‬‬\n‫لــم يثبــت لــدي إدانتــه بإدخــال املــواد احملظــورة للســجن وحكمــت‬\n‫بــرد دعــوى املدعــي العــام يف ذلــك وبعــرض ذلــك علــى املدعــي قــرر‬\n‫القناعــة وأمــا املدعــي العــام فقــرر االعتــراض بالئحــة فجــرى إفهامــه‬\n‫بتعليمــات االســتئناف ‪ ،‬وصلــى اهلل وســلم علــى نينــا محمــد ‪ .‬حــرر يف‬\n                                                            ‫‪1434/03/22‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم األثنــن املوافــق ‪1434/6/19‬ه ـ‬\n‫افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف وبرفقهــا‬\n\n\n                                                                                    ‫‪24‬‬\n\f     ‫قــرار الدائــرة اجلزائيــة األولــى رقــم (‪ )34231547‬يف ‪1434/6/5‬ه ـ‬\n     ‫املتضمــن املصادقــة علــى احلكــم ‪ ،‬وللمعلوميــة جــرى حتريــر ذلــك ‪،‬‬\n            ‫وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر يف ‪1434/6/19‬هــ‪.‬‬\n\n\n\n\n‫‪25‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":21,"source_page_end":25,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"31f9ec086cff1b68169b8b5de6d4e4469b1de9f286dd9caabe8fd80dd3d2063d","normalized_text_hash":"bf3179eaa6041e4135c194ac766a851eb553e1d340e54c34468d6fcdae13f289","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p21-34121107"},{"id":"c2ad61bf-8c82-5f79-b5d1-b921e771d38c","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة قطع من احلشيش -الشروع يف بيع احلشيش - تعاطي احلشيش -إثبات اإلدانة بشهادة أعضاء الفرقة القابضة -إقامة حد املسكر -التعزير بالسجن واجللد واملنع من السفر واملصادرة وإسقاط شريحة اجلوال.","document_number":"34283677","case_number":"34124390","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/07/30","year":"1434","subject":"مخدرات -حيازة قطع من احلشيش -الشروع يف بيع احلشيش - تعاطي احلشيش -إثبات اإلدانة بشهادة أعضاء الفرقة القابضة -إقامة حد املسكر -التعزير بالسجن واجللد واملنع من السفر واملصادرة وإسقاط شريحة اجلوال.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34283677:‬تاريخه ‪1434/07/30:‬هـ‬\n                   ‫رقم الدعوى ‪34124390:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n          ‫‪ 34299630‬تاريخه‪1434/08/17 :‬هـ‬\n\n\n‫مخــدرات‪ -‬حيــازة قطــع مــن احلشــيش ‪ -‬الشــروع يف بيــع احلشــيش ‪-‬‬\n‫تعاطــي احلشــيش ‪ -‬إثبــات اإلدانــة بشــهادة أعضــاء الفرقــة القابضــة‬\n‫‪ -‬إقامــة حــد املســكر ‪ -‬التعزيــر بالســجن واجللــد واملنــع مــن الســفر‬\n                                 ‫واملصــادرة وإســقاط شــريحة اجلــوال‪.‬‬\n\n\n\n\n                                           ‫‪ -1‬قاعدة املرء مؤاخذ بإقراره ‪.‬‬\n‫‪ -2‬مــا نــص عليــه أهــل العلــم مــن إقامــة حــد املســكر علــى متنــاول‬\n                                     ‫احلشــيش (فتــح البــاري‪.)415/10‬‬\n‫‪ -3‬الفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                    ‫العقليــة‪.‬‬\n‫‪ -4‬الفقــرة (‪ )1‬مــن املــادة (‪ )53‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                    ‫العقليــة‪.‬‬\n‫‪ -5‬الفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                    ‫العقليــة‪.‬‬\n‫‪ -6‬الفقــرة (‪ )1‬مــن املــادة (‪ )62‬مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n                                                                    ‫العقليــة‪.‬‬\n           ‫‪ -7‬املادة (‪ )59‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n                                                                                 ‫‪26‬‬\n\f     ‫توجيــه االتهــام للمدعــى عليــه بحيــازة قطــع مــن احلشــيش املخــدر‬\n     ‫بقصــد االجتــار‪ ،‬الشــروع يف بيــع قطعتــن مــن احلشــيش‪ ،‬تعاطــي‬\n     ‫احلشــيش‪ ،‬حيــث ورد بــاغ مــن أحــد املصــادر الســرية عــن قيــام املدعــى‬\n     ‫عليــه بترويــج احلشــيش املخــدر ويســتخدم هاتفــه اجلــوال‪ ،‬مت متكــن‬\n     ‫املصــدر مــن االتصــال علــى املدعــى عليــه وطلــب منــه قطعــة حشــيش‬\n     ‫فوافــق املــروج (املدعــى عليــه)‪ ،‬كانــت املكاملــة علــى مســمع مــن‬\n     ‫الفرقــة القابضــة‪ ،‬ثــم تفتيــش املصــدر وتفتيــش ســيارته ومت تزويــده‬\n     ‫باملبلــغ املرقــم‪ ،‬اجتــه املصــدر ملنــزل املدعــى عليــه فخــرج مــن منزلــه‬\n     ‫وكان حــذر ًا وعنــد اقتــراب الفرقــة القابضــة قــام برمــي شــيء حتــت‬\n     ‫ســيارته عندهــا مت القبــض عليــه‪ ،‬طلــب املدعــي العــام إثبــات مــا أســند‬\n     ‫للمدعــى عليــه احلكــم عليــه بعقوبــة الســجن واجللــد والغرامــة و املنــع‬\n     ‫مــن الســفر ومصــادرة الهاتــف اجلــوال وإســقاط شــريحته‪ ،‬أقــر املدعــى‬\n     ‫عليــه مبــا نســب إليــه وذكــر بــأن قصــده مــن احليــازة االســتعمال‪،‬‬\n     ‫أنكــر الشــروع يف البيــع‪ ،‬أحضــر املدعــي العــام شــهوده أعضــاء الفرقــة‬\n     ‫القابضــة‪ ،‬جــرى االطــاع علــى صحيفــة ســوابق املدعــى عليــه والتقريــر‬\n     ‫الكيميائي‪،‬صــدر احلكــم بثبــوت إدانــة املدعــي عليــه بحيــازة قطعــة‬\n     ‫مــن احلشــيش املخــدر بقصــد الترويــج واالســتعمال‪ ،‬الشــروع يف بيــع‬\n     ‫قطعتــن مــن احلشــيش‪ ،‬اســتخدامه جلوالــه املذكــور يف ذلــك‪ ،‬تعاطــي‬\n     ‫احلشــيش املخــدر‪ ،‬احلكــم عليــه بالســجن واجللــد والغرامــة واملنــع مــن‬\n     ‫الســفر ومصــادرة هاتفــه اجلــوال وإســقاط شــريحته‪ ،‬جلده حد املســكر‬\n                     ‫ثمانــن جلــدة‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n‫‪27‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق ‪1434/4/27‬ه ـ لــدي‬\n‫ـاء علــى املعاملــة احملالــة‬\n                           ‫أنــا ‪ ....‬القاضــي باحملكمــة اجلزائيــة بالدمــام وبنـ ً‬\n‫إلينــا مــن رئيــس احملكمــة برقــم (‪ )....‬وتاريــخ ‪1434/3/16‬ه ـ افتتحــت‬\n‫اجللســة وفيهــا حضــر ‪....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫(‪ )....‬وقــدم املدعــي العــام ‪ .....‬الئحــة اإلدعــاء املتضمنــة بصفتــي مدعي ـ ًا‬\n‫عامـ ًا بدائــرة اإلدعــاء العــام لفــرع الهيئــة باملنطقــة الشــرقية أدعــي علــى‬\n‫املذكــور أعــاه باالطــاع علــى محضــر االنتقــال و القبــض والتفتيــش‬\n‫املعــد مــن قبــل رجــال الضبــط اجلنائــي بشــعبة مكافحــة املخــدرات‬\n‫بالدمــام تبــن إنــه يف يــوم األحــد املوافــق ‪1434/2/17‬ه ـ ورد بــاغ مــن‬\n‫أحــد املصــادر الســرية عــن شــخص يدعــى (‪ )....‬يقــوم بترويــج احلشــيش‬\n‫املخــدر يســكن حــي ‪ ....‬ويســتخدم هاتفــه اجلــوال رقــم (‪ )....‬فتــم متكــن‬\n‫املصــدر مــن االتصــال عليــه وطلــب منــه حشــيش مخــدر مببلــغ (‪)200‬‬\n‫مائتــان ريــال ووافقــه املــروج وطلــب منــه احلضــور إلــى املنــزل وكانــت‬\n‫املكاملــة علــى مســمع مــن الفرقــة القابضــة فتــم االنتقــال إلــى املوقــع‬\n‫برفقــة املصــدر بعــد تفتيشــه وتفتيــش ســيارته وتزويــده مببلــغ مرقــم‬\n‫واجتــه إلــى منــزل املــروج يف حــي ‪ .....‬وخــرج شــخص مــن املنــزل‬\n‫املقصــود وكان حــذرا وعنــد اقتــراب الفرقــة القابضــة قــام املــروج‬\n‫برمــي شــي حتــت ســيارته عندهــا مت القبــض عليــه واتضــح انــه املدعــى‬\n‫عليــه وبالبحــث عمــا قــام برميــه اتضــح انــه قطعتــن بنيــة اللــون بلــغ‬\n‫وزنهمــا (‪ )8,6‬ثمانيــة جرامــات وســتة أعشــار اجلــرام وبتفتيــش منزلــه‬\n‫عثــر علــى عــدد (‪ )31‬واحــد وثالثــون قطعــة بنيــة اللــون تــزن جميعهــا‬\n\n                                                                                        ‫‪28‬‬\n\f     ‫(‪ )140.9‬مائــة وأربعــون جــرام وتســعة أعشــار اجلــرام وأثبــت التقريــر‬\n     ‫الكيمــاوي الشــرعي رقــم (‪ )....‬وتاريخ‪1434/2/27‬ه ـ إيجابيــة عينــة‬\n     ‫املضبوطــات ملــادة احلشــيش املخــدر املدرجــة باجلــدول األول فئــة (أ) مــن‬\n     ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وباســتجواب املذكــور‬\n     ‫أقــر بصحــة واقعــة القبــض وان رقــم االتصــال (‪ )....‬يعــود لــه كمــا أقــر‬\n     ‫بحيازتــه احلشــيش املخــدر بقصــد االســتعمال وتعاطيــه لــه وأنكــر بيعــه‬\n     ‫للحشــيش املخــدر وقــد انتهــى التحقيــق إلــى اتهــام بحيازتــه لعــدد (‪)31‬‬\n     ‫إحــدى وثالثــون قطعــه بنيــة اللــون بلــغ وزنهــا (‪ )140,9‬مائــة وأربعــون‬\n     ‫جرامـ ًا وتســعة أعشــار اجلــرام بقصــد االجتــار والشــروع يف بيــع قطعتــن‬\n     ‫منهــا تزنــا (‪ )8,6‬ثمانيــة جرامــات وســتة أعشــار اجلــرام وتعاطيــه‬\n     ‫للحشــيش املخــدر وذلــك وفقــا للفقــرة الثانيــة مــن املــادة الثالثــة مــن نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة وذلــك لألدلــة والقرائــن التاليــة ‪:‬‬\n     ‫‪ -1‬اعترافــه بصحــة واقعــة القبــض وان رقــم االتصــال الــذي مت التنســيق‬\n     ‫عليــه لعمليــة البيــع يعــود لــه واملدونــة مبحضــر اســتجوابه املرفــق علــى‬\n     ‫اللفــات رقــم (‪-2 )12‬محضــر القبــض والتفتيــش املنــوه عنــه واملــدون على‬\n     ‫الصفحــة رقــم (‪ )12‬املرفــق علــى اللفــة رقــم (‪ -3)1‬التقريــر الكيمــاوي‬\n     ‫الشــرعي املنــوه عنــه املرفــق علــى اللفــة رقــم (‪ -4)13‬مكاملــة املصــدر‬\n     ‫مــع املــروج واالتفــاق علــى شــراء احلشــيش مخــدر علــى مســمع مــن اجلهــة‬\n     ‫القابضــة مــع وجــود كميــة مجــزأة يف منــزل املــروج قرينــة علــى شــروعه‬\n     ‫يف بيــع احلشــيش املخــدر وحيــث إن مــا أقــدم عليــه املذكــور ‪ -‬وهــو‬\n     ‫بكامــل أهليتــه املعتبــرة شــرعا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n     ‫ونظامـ ًا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه مبــا يلــي‪ -1 :‬بعقوبــة‬\n     ‫الســجن واجللــد والغرامــة الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪)38‬‬\n\n\n‫‪29‬‬\n\f‫مــن النظــام مــع إعمــال مقتضــى الفقــرة رقــم (‪ )1‬مــن املــادة (‪ )62‬مــن‬\n‫النظــام مــع إعمــال املــادة (‪ )59‬مــن النظــام‪ -2‬منعــه مــن الســفر إعمــاال‬\n‫ملقتضــى الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )56‬مــن النظــام‪ -3‬مصــادرة‬\n‫الهاتــف اجلــوال العائــد للمذكــور يحمــل الرقــم () الســتخدامه يف بيــع‬\n‫احلشــيش املخــدر وفقــا للفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )53‬مــن النظــام‬\n‫مــع احلكــم بإســقاط شــريحة الهاتــف النقــال وعــدم صرفهــا لنفــس‬\n‫املدعــى عليــه وفقــا لتعميــم ســمو وزيــر الداخليــة رقــم (‪ )9798‬وتاريــخ‬\n‫‪1429/2/10-9‬ه ـ وبــاهلل التوفيــق وبســؤال املدعــى عليــه أجــاب بقولــه‬\n‫مــا ذكــره املدعــي العــام مــن حيــازة واحــد وثالثــن قطعــة مــن احلشــيش‬\n‫املخــدر بلــغ وزنهــا مائــة و أربعــن جرامـ ًا وتســعة مــن العشــرة مــن اجلــرام‬\n‫فهــذا صحيــح وكان ذلــك بقصــد التعاطــي واالســتعمال وليــس بقصــد‬\n‫االجتــار ومــا ذكــره مــن تعاطــي احلشــيش املخــدر وأن رقــم اجلــوال (‪)....‬‬\n‫عائــد لــي فهــذا صحيــح أيضـ ًا ومــا ذكــره مــن الشــروع يف بيــع قطعتــن‬\n‫تــزن ثمانيــة جرامــات وســتة مــن العشــرة مــن اجلــرام وأننــي رميتهــا عنــد‬\n‫القبــض علــي فهــذا غيــر صحيــح هــذه إجابتــي وبعــد تدويــن مــا ســبق‬\n‫رفعــت اجللســة لطلــب البينــة مــن املدعــي العــام ويف يــوم األربعــاء املوافــق‬\n‫‪1434/5/29‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــى عليــه املــدون‬\n‫هويتــه ســابق ًا وقــد جــرت الكتابــة لرئيــس فــرع هيئــة التحقيــق واالدعــاء‬\n‫العــام بالشــرقية لطلــب البينــة املثبتــة لصحــة التهمــة املنســوبة للمدعــى‬\n‫عليــه وذلــك باخلطــاب رقــم (‪ )....‬وتاريــخ ‪1434/4/27‬ه ـ إال أنــه لــم‬\n‫يحضــر أحــد وعليــه رفعــت اجللســة لطلــب البينــة مــرة أخــرى مــن املدعــي‬\n‫العــام ويف يــوم االثنــن املوافــق ‪1434/7/3‬ه ـ افتتحــت اجللســة وفيهــا لــم‬\n‫يتــم إحضــار املدعــى عليــه املــدون هويتــه ســابق ًا ولــم حتضــر البينــة املثبتة‬\n\n\n                                                                                         ‫‪30‬‬\n\f     ‫لصحــة التهمــة املنســوبة للمدعــى عليــه لــذا رفعــت اجللســة للتأكيــد على‬\n     ‫املدعــي العــام بإحضــار البينــة ويف يــوم األحــد املوافــق ‪1434/7/16‬ه ـ‬\n     ‫افتتحــت اجللســة وفيهــا حضــر املدعــى عليــه املــدون هويتــه ســابق ًا‬\n     ‫وحضــر ألداء الشــهادة ســعودي مبوجــب بطاقــة الهويــة الوطنيــة رقــم‬\n     ‫(‪ )....‬و‪ ....‬ســعودي مبوجــب بطاقــة الهويــة الوطنيــة رقــم (‪ )....‬وبســؤالهما‬\n     ‫عمــا لديهمــا مــن شــهادة شــهد األول قائــا إننــي أعمــل يف مكافحــة‬\n     ‫املخــدرات بالدمــام وأشــهد بــاهلل العظيــم بــأن أحــد املصــادر أبلغنــا عــن‬\n     ‫قيــام املدعــى عليــه احلاضــر معنــا بترويــج احلشــيش املخــدر فتــم متكــن‬\n     ‫املصــدر مــن االتصــال علــى املدعــى عليــه علــى جوالــه رقــم (‪ )....‬وكانــت‬\n     ‫املكاملــة علــى وضعيــة مكبــر الصــوت فطلــب منه حشــيش مخدر مببلغ‬\n     ‫مائتــي ريــال فوافــق املدعــى عليــه وطلــب مــن املصــدر احلضــور ملنزلــه يف‬\n     ‫ا وانتشــرنا يف‬  ‫حــي ‪ ....‬بالدمــام فانتقلنــا ومعنــا املصــدر وكان راج ـ ً‬\n     ‫املوقــع وكنــت أنــا قريبــا مــن بــاب منــزل املدعــى عليــه وملــا وصــل املصــدر‬\n     ‫خــرج املدعــى عليــه وشــاهدته بنفســي وكان يحمــل معــه بطانيــة وأخــذ‬\n     ‫يتلفــت بشــكل حــذر فلمــا شــاهدنا قــام برمــي قطعتــن كانتــا معــه‬\n     ‫والتــي اتفــق مــع املصــدر علــى بيعهــا لــه واتضــح أنهــا مــن احلشــيش املخــدر‬\n     ‫كمــا قــام برمــي جــوال كان معــه علــى األرض فتــم القبــض عليــه ثــم‬\n     ‫دخلنــا املنــزل ومعنــا الســجانة فضبطنــا فيــه عــدد واحــد وثالثــن قطعــة‬\n     ‫مــن احلشــيش املخــدر كانــت معــدة للترويــج حيــث مت لــف كل قطعــة‬\n     ‫علــى شــكل أصبــع معــد للترويــج هــذا مــا أشــهد بــه واهلل علــى مــا أقــول‬\n     ‫شــهيد كمــا شــهد الثانــي بقولــه إننــي أحــد أعضاء مكافحــة املخدرات‬\n     ‫بالدمــام وأشــهد بــاهلل العظيــم بــأن أحــد املصــادر أخبرنــا بقيــام املدعــى‬\n     ‫عليــه بترويــج احلشــيش املخــدر فتــم متكــن املصــدر مــن االتصــال علــى‬\n\n\n‫‪31‬‬\n\f‫املدعــى عليــه علــى جوالــه رقــم () وطلــب منــه حشــيش مببلــغ مائتــي ريــال‬\n‫فقــال املدعــى عليــه نعــم عنــدي احلشــيش وطلــب مــن املصــدر أن يأتــي‬\n‫ملنزلــه يف حــي ‪ .....‬هــذا مــا أشــهد بــه واهلل علــى مــا أقــول شــهيد وبعــرض‬\n‫الشــاهدين وشــهادتهم علــى املدعــى عليــه قــرر بقولــه أمــا الشــاهدين فــا‬\n‫أعــرف فيهــم أي مطعــن وأمــا شــهادتهم فغيــر صحيحــة حيــث إن املصــدر‬\n‫اتصــل علــي ولــم يطلــب منــي حشــيش بــل ســألني هــل بقــي عنــدك شــيء‬\n‫أي مــن احلشــيش وذلــك أننــي أنــا أشــتري منــه فقلــت لــه باقــي عنــدي وأنــا‬\n‫ال أحتــاج ثــم مت إنهــاء املكاملــة ومــا ذكــره الشــاهد األول مــن أننــي قمت‬\n‫برمــي قطعتــن ورمــي جوالــي عنــد القبــض علــي فهــذا غيــر صحيــح وأمــا‬\n‫مــا مت ضبطــه يف منزلــي فهــذا صحيــح وهــو عائــد لــي بقصــد االســتعمال‬\n‫الشــخصي هكــذا قــرر كمــا حضــر لتزكيــة الشــاهدين كل مــن ‪....‬‬\n‫ســعودي مبوجــب بطاقــة هويــة رقــم (‪ )....‬و‪ ....‬ســعودي مبوجــب بطاقــة‬\n‫هويــة رقــم (‪ )....‬وبســؤالهما عمــا لديهمــا شــهد كل واحــد منهما مبفرده‬\n‫قائــا إننــي أعــرف الشــاهدين معرفــة تامــة وأشــهد بأنهمــا عدلــن ثقتــن‬\n‫هكــذا شــهدا وبعــد تدويــن مــا ســبق رفعــت اجللســة لطلــب مزيــد بينة من‬\n‫املدعــي العــام ويف يــوم األحــد املوافــق ‪1434/7/30‬ه ـ افتتحــت اجللســة‬\n‫وفيهــا حضــر املدعــى عليــه ‪ ........‬املــدون هويتــه ســابق ًا وقــرر املدعــي‬\n‫العــام عــدم وجــود مزيــد بينــة وبعــد تدويــن مــا ســبق جــرى االطــاع علــى‬\n‫التقريــر الكيمــاوي الشــرعي رقــم (‪ )........‬املتضمــن إيجابيــة عينــات‬\n               ‫القطــع املضبوطــة يف هــذه القضيــة ملــادة احلشــيش املخــدر‪.‬‬\n‫كمــا جــرى االطــاع علــى ســوابق املدعــى عليــه املرفقــة بالئحــة االدعــاء‬\n‫واملتضمنة وجود ســابقة واحدة مســجلة عليه عبارة عن حيازة مخدرات‬\n‫وبعرضهــا عليــه أقــر بصحتهــا فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابة‬\n\n\n                                                                                       ‫‪32‬‬\n\f     ‫وحيــث أقــر املدعــى عليــه بتعاطــي احلشــيش املخــدر كمــا أقــر بحيــازة‬\n     ‫واحــد وثالثــن قطعــة مــن احلشــيش بقصد االســتعمال كما أقــر بعائدية‬\n     ‫اجلــوال ذي الرقــم (‪ )........‬لــه واملــرء مؤاخــذ بإقــراره وبنــاء علــى شــهادة‬\n     ‫الشاهدين املعدلني التعديل الشرعي وحيث تضمنت شهادة الشاهدين‬\n     ‫ســماع مكاملــة املصــدر للمدعــى عليــه علــى جوالــه املذكــور و هو يطلب‬\n     ‫منــه حشــيش مخــدر مببلــغ مائتــي ريــال و موافقــة املدعــى عليــه على ذلك‬\n     ‫و طلــب منــه احلضــور ملنزلــه يف حــي ‪ ....‬كمــا تضمنــت شــهادة الشــاهد‬\n     ‫األول قيــام املدعــى عليــه باخلــروج مــن منزلــه عندمــا وصــل لــه املصــدر‬\n     ‫وأنــه عندمــا شــاهد الفرقــة القابضــة قــام برمــي قطعتــن مــن احلشــيش‬\n     ‫كمــا تضمنــت شــهادته أن قطــع احلشــيش الواحــد وثالثــن املضبوطة يف‬\n     ‫منــزل املدعــى عليــه ملفــوف كل منهــا علــى شــكل أصبــع معــد للترويــج‬\n     ‫وبنــاء علــى التقريــر الكيمــاوي الشــرعي املشــار إليــه أعــاه و لوجــود‬\n     ‫ســابقة مســجلة علــى املدعــى عليــه عبــارة عــن حيــازة مخــدرات أقــر‬\n     ‫بصحتهــا واســتناد ًا للفقــرة األولــى مــن املــادة الثامنــة والثالثــن و الفقــرة‬\n     ‫األولــى مــن املــادة الثالثــة واخلمســن والفقــرة األولــى مــن املــادة السادســة‬\n     ‫واخلمســن واملــادة التاســعة واخلمســن والفقــرة األولــى مــن املــادة الثانيــة‬\n     ‫والســتني مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة وبنــاء علــى‬\n     ‫مــا نــص عليــه أهــل العلــم مــن إقامــة حــد املســكر علــى متنــاول احلشــيش‬\n     ‫(فتــح البــاري ‪ )10/45‬لــذا فقــد ثبــت لــدي إدانــة املدعــى عليــه مبــا يلــي‪:‬‬\n     ‫حيــازة واحــد وثالثــن قطعــة بلــغ وزنهــا مائــة وأربعــن جرامـ ًا وتســعة مــن‬\n     ‫العشــرة مــن اجلــرام مــن احلشــيش املخــدر بقصــد الترويــج واالســتعمال‬\n     ‫والشــروع يف بيــع قطعتــن مــن احلشــيش واســتخدامه جلوالــه املذكــور يف‬\n     ‫الئحــة الدعــوى يف ذلــك وتعاطــي احلشــيش املخــدر وحكمــت عليــه لقــاء‬\n\n\n‫‪33‬‬\n\f‫ذلــك مبــا يلــي ‪ -1 :‬ســجنه خمــس ســنوات اعتبــار ًا مــن تاريــخ إيقافــه علــى‬\n‫ذمــة هــذه القضيــة وجلــده مائتــن وخمســن جلــدة مفرقــة علــى خمــس‬\n‫دفعــات متســاوية وبــن كل دفعــة و األخــرى مــدة ال تقــل عــن عشــرة‬\n‫أيــام وإلزامــه بدفــع غرامــة ماليــة قدرهــا خمســة آالف ريــال ‪ -2‬منعــه‬\n‫مــن الســفر خــارج اململكــة مــدة خمــس ســنوات تبــدأ بعــد االنتهــاء مــن‬\n‫تنفيــذ عقوبــة الســجن احملكــوم بهــا ‪ -3‬مصــادرة الهاتــف اجلــوال العائــد‬\n‫للمدعــى عليــه املذكــور يف الدعــوى وإســقاط شــريحته وعــدم صرفهــا‬\n‫لــه مــرة أخــرى ‪ -4‬جلــده حــد املســكر ثمانــن جلــدة وبعــرض احلكــم‬\n‫علــى املدعــى عليــه قــرر عــدم القناعــة وطلــب رفــع احلكــم إلــى محكمــة‬\n‫االســتئناف فأجيــب لطلبــه ومت تســليمه نســخة مــن احلكــم وأفهــم بتقدمي‬\n‫اعتراضــه خــال مــدة ثالثــن يومــا وأنــه إذا انتهــت هــذه املــدة ولــم يتقــدم‬\n‫باعتراضــه ســقط حقــه يف االعتــراض وســوف ســيتم رفــع احلكــم إلــى‬\n‫محكمــة االســتئناف بــدون الئحــة اعتراضيــة وقــرر املدعــى العــام عــدم‬\n‫االعتــراض وبــاهلل التوفيــق وصلــى اهلل علــى نيبنــا محمــد وبــه حــرر يف‬\n                                                                    ‫‪1434/7/30‬هـ‪.‬‬\n‫ويف يــوم االثنــن املوافــق ‪1434/9/14‬ه ـ افتتحــت اجللســة الســاعة‬\n‫العاشــرة وخمــس وأربعــن دقيقــة وقــد عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف برقــم (‪ )........‬وتاريــخ ‪1434/9/7‬ه ـ املتعلقــة بدعــوى املدعــي‬\n‫العــام ضــد‪ ........‬وبرفقهــا القــرار الصــادر مــن الدائــرة اجلزائيــة الثانيــة‬\n‫برقــم (‪ )........‬وتاريــخ ‪1434/8/17‬ه ـ املتضمــن املصادقــة علــى احلكــم‬\n‫لــذا جــرى إحلــاق ذلــك حتــى ال يخفــى وبــاهلل التوفيــق وصلــى اهلل علــى‬\n                                     ‫نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n\n\n                                                                                         ‫‪34‬‬\n\f     ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة‬\n     ‫املقيــدة لــدى احملكمــة برقــم‪ ........‬وتاريــخ ‪1434/8/10‬ه ـ الــواردة مــن‬\n     ‫فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام املكلــف برقــم‪........‬‬\n     ‫وتاريــخ ‪1434/8/6‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n     ‫باحملكمــة الشــيخ‪ ........‬املســجل برقــم‪ ........‬وتاريــخ ‪1434/7/30‬ه ـ‬\n     ‫اخلــاص بدعــوى‪ ........‬املدعــي العــام ضــد‪ ........‬يف قضيــة مخــدرات وقــد‬\n     ‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة‬\n     ‫القــرار وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا‬\n     ‫املصادقــة علــى احلكــم‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                        ‫وصحبــه وســلم‪ .‬حــرر يف‪1434/8/14‬هــ‪.‬‬\n\n\n\n\n‫‪35‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":26,"source_page_end":35,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"67976b29fa5f7a920bb886a1e323e649b3e288afd63567867642546c0a748e4c","normalized_text_hash":"b6554f79cc020f78dbbfdc96818ec63e31010b46a385391e0fe60ccd73af8b21","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p26-34283677"},{"id":"21de836a-fdfd-5e0b-b70a-b5f49b1db1fe","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة احلبوب التي حتتوي على مادة اإلمفيتامن املنبه احملظورة بقصد التعاطي والترويج -حيازة احلشيش بقصد التعاطي -تعاطي احلشيش املخدر -توجيه الشبهة بالترويج لكثرة كمية احلبوب -التعزير بالسجن واجللد واملنع من السفر.","document_number":"34170615","case_number":"34130755","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف مبكة املكرمة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/03/24","year":"1434","subject":"مخدرات -حيازة احلبوب التي حتتوي على مادة اإلمفيتامن املنبه احملظورة بقصد التعاطي والترويج -حيازة احلشيش بقصد التعاطي -تعاطي احلشيش املخدر -توجيه الشبهة بالترويج لكثرة كمية احلبوب -التعزير بالسجن واجللد واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34170615:‬تاريخه ‪1434/03/24:‬هـ‬\n                    ‫رقم الدعوى ‪34130755:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34210261‬تاريخه‪1434/05/08:‬هـ‬\n\n\n ‫مخــدرات ‪ -‬حيــازة احلبــوب التــي حتتــوي علــى مــادة اإلمفيتامــن‬\n ‫املنبــه احملظــورة بقصــد التعاطــي والترويــج ‪ -‬حيــازة احلشــيش بقصــد‬\n ‫التعاطــي ‪ -‬تعاطــي احلشــيش املخــدر‪ -‬توجيــه الشــبهة بالترويــج لكثــرة‬\n       ‫كميــة احلبــوب ‪ -‬التعزيــر بالســجن واجللــد واملنــع مــن الســفر‪.‬‬\n\n\n\n\n          ‫املادتان ‪ 41‬و ‪ 56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n ‫الئحــة الدعــوى العامــة ضــد املدعــى عليــه بحيــازة عــدد (‪ )170‬مائــة‬\n ‫وســبعني حبــة مــن حبــوب اإلمفيتامــن احملظــورة بقصــد التعاطــي‬\n ‫والترويــج وحيــازة احلشــيش املخــدر بقصــد التعاطــي وتعاطــي احلشــيش‬\n ‫املخدر‪،‬وطلــب املدعــي العــام إثبــات مــا أســند إليــه واحلكــم عليــه‬\n ‫بالســجن واجللــد والغرامــة ومنعــه مــن الســفر ومجازاتــه شــرع ًا‬\n ‫لتعاطيــه احلشــيش املخــدر ومراعــاة الفقــرة األولــى مــن املــادة (‪)62‬‬\n ‫مــن نظــام مكافحــة املخــدرات بخصــوص تعاطيــه احلبــوب احملظــورة‬\n ‫وحيازتــه لنصــف جــرام مــن احلشــيش املخــدر بقصــد التعاطــي‪ ،‬إقــرار‬\n ‫أن قصــده الترويــج‬\n                   ‫املدعــى عليــه باحليــازة للحبــوب للتعاطــي وإنــكاره َّ‬\n ‫وإقــراره بتعاطــي احلشــيش وحيازتــه لقصــد التعاطــي وتعاطيــه للحبــوب‬\n\n                                                                                ‫‪36‬‬\n\f     ‫احملظــورة وعــدم وجــود بينــة للمدعــي العــام علــى الترويــج‪ ،‬ثبــوت إدانــة‬\n     ‫املدعــى عليــه باحليــازة للحبــوب احملظــورة واحلشــيش لغــرض االســتعمال‬\n     ‫واســتعماله للحبــوب احملظــورة‪ ،‬توجيــه الشــبهة للمدعــى عليــه بالترويــج‬\n     ‫لكثــرة الكميــة‪ ،‬تعزيــر املدعــى عليــه بالســجن واجللــد واملنــع مــن‬\n     ‫الســفر وإقامــة حــد املســكر علــى املدعــى عليــه‪ ،‬تصديــق احلكــم مــن‬\n                                      ‫محكمــة االســتئناف مبكــة املكرمــة‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وبعــد يف هــذا اليــوم الثالثــاء املوافــق ‪1434/3/24‬هـ ـ الســاعة‬\n     ‫التاســعة صباحـ ًا لــدي أنــا ‪ ...........‬القاضــي باحملكمــة اجلزئيــة بالطائــف‬\n     ‫وبناء ًا على املعاملة املقيدة رقم ‪ 34691985‬يف ‪1434/3/18‬هـ واحملالة‬\n     ‫إلينا برقم ‪ 34130755‬يف ‪1434/3/18‬هـ افتتحت اجللســة وفيها حضر‬\n     ‫املدعــى العــام‪ ...........‬بالتعميــد رقــم ‪ ...........‬يف ‪1433/10/18‬هـ ـ وادعــى‬\n     ‫علــى احلاضــر باملجلــس الشــرعي‪ ...........‬ســعودي اجلنســية مبوجــب‬\n     ‫ال لقد انتهى التحقيق إلى توجيه االتهام‬   ‫الســجل املدني رقم ‪ ...........‬قائ ً‬\n     ‫للمدعــى عليــه بحيــازة مائــة وســبعني حبــة مــن احلبــوب التــي حتتــوي علــى‬\n     ‫مــادة اإلمفيتامــن املنبهــة احملظــورة بقصــد التعاطــي والترويــج وحيــازة‬\n     ‫قطعــة حشــيش مخــدر تــزن نصــف اجلــرام بقصــد التعاطــي وتعاطيهمــا‬\n     ‫لــذا أطلــب إثبــات م ــا أســند إليــه واحلكــم عليــه بالتالــي ‪ -1 :‬السج ــن‬\n     ‫واجل ـل ــد والغ ــرامة وفقـ ــا للـفـق ــرة األول ــى م ــن املـ ــادة الثامن ــة والثـالثـيـ ـ ــن‪.‬‬\n     ‫‪ -2‬منعــه مــن الســفر خــارج اململكــة بعــد تنفيــذ العقوبــة وفق ـ ًا للفقــرة‬\n     ‫األولــى مــن املــادة السادســة واخلمســن ‪ -3 .‬مجازاتــه شــرع ًا لتعاطيــه‬\n     ‫احلشــيش املخــدر ‪ .‬ومراعــاة الفقــرة األولــى مــن املــادة الثانيــة والســتني‬\n\n‫‪37‬‬\n\f‫بخصــوص تعاطيــه للحبــوب املنبهــة احملظــورة وحيازتــه لنصــف جــرام‬\n‫مــن احلشــيش املخــدر بقصــد التعاطــي هــذه دعــواي ‪ .‬وبعــرض ذلــك علــى‬\n‫املدعــى عليــه أجــاب بقولــه ‪ :‬مــا ذكــره املدعــي العــام يف دعــواه مــن‬\n‫اتهامــي بحيــازة (‪ )170‬مائــة وســبعني حبــة مــن احلبــوب احملظــورة وقطعــة‬\n‫حشــيش مخــدر بقصــد التعاطــي وأننــي تعاطيــت احلشــيش واحلبــوب‬\n‫ســابق ًا فكلــه صحيــح وأمــا مــا ذكــره مــن أن قصــدي مــن حيــازة‬\n‫احلبــوب الترويــج أيضـ ًا فغيــر صحيــح ‪ ،‬هكــذا أجــاب فســألت املدعــي‬\n‫العــام البينــة علــى أن قصــد املدعــى عليــه مــن هــذه احليــازة الترويــج‬\n‫فأجــاب بقولــه ‪ :‬بينتــي علــى ذلــك أن الكميــة كبيــرة وليــس لــدي‬\n‫ســوى ذلــك هكــذا أجــاب فبعــد ســماعي للدعــوى وإجابــة املدعــى عليــه‬\n‫بصحــة مــا جــاء فيهــا مــن حيــازة احلشــيش واحلبــوب احملظــورة بقصــد‬\n‫التعاطــي وتعاطيــه لهــا ‪ ،‬نافي ـ ًا أن يكــون قصــده مــن حيــازة احلبــوب‬\n‫الترويــج ايض ـ ًا ‪ ،‬وبعــد االطــاع علــى أوراق املعاملــة مبــا فيهــا التقريــر‬\n‫الكيميائــي الشــرعي املتضمــن إيجابيــة العينــات املضبوطــة ملادتــي‬\n‫احلشــيش واالمفيتامــن احملظورتــن وألن بينــة املدعــي العــام فيمــا يتعلــق‬\n‫بقصــد الترويــج غيــر موصلــة وألن كميــة احلبــوب املضبوطــة مــع املدعــى‬\n‫عليــه كبيــرة ممــا يثيــر التهمــة ضــده بأنهــا للترويــج أيضــا ‪ ،‬وبنــاء علــى‬\n‫املادتــن احلاديــة واألربعــن والسادســة واخلمســن مــن نظــام مكافحــة‬\n‫املخــدرات ولعــدم وجــود ســوابق للمدعــى عليــه لهــذا كلــه فقــد صــدر‬\n‫منــي مــا يلــي ‪ :‬أو ًال ‪ :‬ثبــت لــدي إدانــة املدعــى عليــه بتعاطــي احلشــيش‬\n‫املخــدر وحكمــت عليــه لقــاء ذلــك بجلــده ثمانــن جلــده حــد ًا علنـ ًا ‪.‬ثانيـ ًا‬\n‫‪ :‬ثبــت لــدي إدانتــه بتعاطــي احلبــوب احملظــورة واكتفيــت بعقوبتــه علــى‬\n‫ذلك باجللد املشــار إليه يف (أوالً) ‪ .‬ثالث ًا ‪ :‬ثبت لدي إدانته بحيازة (‪)170‬‬\n\n\n                                                                                        ‫‪38‬‬\n\f     ‫مائــة وســبعني حبــة مــن احلبــوب احملظــورة وقطعــة حشــيش مخــدر لقصــد‬\n     ‫التعاطــي وتتوجــه التهمــة ضــده بــأن قصــده مــن حيــازة احلبــوب الترويــج‬\n     ‫أيضـ ًا وحكمــت عليــه لقــاء ذلــك بســجنه ســنة كاملــة مــن تاريــخ إيقافــه‬\n     ‫وجلــده مائــة وخمســن جلــدة مفرقــة علــى ثــاث دفعــات متســاوية يف‬\n     ‫العــدد بــن كل دفعــة وأخــرى مــدة ال تقــل عــن أســبوع كمــا يفصــل‬\n     ‫بينهــا وبــن اجللــد املشــار إليــه يف (أوالً) مبــدة مماثلــة ومنعــه مــن الســفر‬\n     ‫خــارج اململكــة ملــدة ســنتني بعــد انتهــاء محكوميتــه وأخــذ التعهــد عليــه‬\n     ‫بعــدم العــودة ملثــل ذلــك ‪ .‬رابعـ ًا ‪ :‬صرفــت النظــر عــن طلــب املدعــي العــام‬\n     ‫تطبيــق املــادة الثامنــة والثالثــن مــن نظــام مكافحــة املخــدرات ؛ لعــدم‬\n     ‫ثبــوت إدانــة املدعــى عليــه باحليــازة لقصــد الترويــج ‪ ،‬وبعــرض ذلــك علــى‬\n     ‫املدعــى عليــه قــرر القناعــة وأمــا املدعــي العــام فقــرر االعتــراض بالئحــة‬\n     ‫فجــرى إفهامــه بتعليمــات االســتئناف وصلــى اهلل علــى نبينــا محمــد حــرر‬\n                                                                    ‫يف ‪1434/3/24‬ه ـ ‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم االربعــاء املوافــق ‪1434/5/29‬ه ـ‬\n     ‫افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف وبرفقهــا‬\n     ‫قــرار الدائــرة اجلزائيــة اخلامســة رقــم (‪ )34210261‬يف ‪1434/5/8‬ه ـ‬\n     ‫املتضمــن املصادقــة علــى احلكــم ‪ ،‬وللمعلوميــة جــرى حتريــر ذلــك ‪،‬‬\n                 ‫وصلــى اهلل وســلم علــى نبينــا محمــد‪ .‬حــرر يف ‪1434/5/29‬هــ‪.‬‬\n     ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ -:‬فقــد‬\n     ‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة االســتئناف‬\n     ‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n     ‫رئيــس احملكمــة اجلزائيــة بالطائــف برقــم (‪ )34691985‬وتاريــخ‬\n     ‫‪1434/3/28‬ه ـ املرفــق بهــا القــرار الصــادر م ــن فضيلــة الشــيخ ‪.........../‬‬\n\n\n‫‪39‬‬\n\f‫القاضــي باحملكمــة اجلزائيــة بالطائــف برقــم (‪ )34170615‬وتـ ـ ـ ـ ــاريخ‬\n‫‪1434/3/24‬ه ـ الـمتضم ــن دعــوى املدعــي العــام ضــد ‪ ........... /‬ســعودي‬\n‫اجلنســية املتهــم يف مخــدرات ‪ ،‬احملكــوم فيــه مبــا دون بباطــن القــرار ‪،‬‬\n‫وبدراســة القــرار وصــورة ضبطــه والئحتــه االعتراضيــة قررنــا املوافقــة‬\n‫علــى احلكــم ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آل ـ ـ ــه‬\n                                                                 ‫وصحبــه وســلم ‪...‬‬\n\n\n\n\n                                                                                      ‫‪40‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":36,"source_page_end":40,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"99294c44d068e278b2d090a9f59f13da22f044ddbf881b1a36e52a4cb9a9f680","normalized_text_hash":"23a2fd058a373cc16672e56b2caa93f63b816d19c670306bed2198906504a89b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p36-34170615"},{"id":"e3735e06-aaac-52f3-ba1e-53906df59f7a","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة قطعة دون الوزن من احلشيش املخدر -حيازة سيجارة مخلوطة باحلشيش املخدر بقصد التعاطي -تعاطي احلشيش املخدر -حيازة مفتاح حتتوي غسالته على احلشيش املخدر -إقرار املدعى عليه-عدم وجود سوابق على املدعى عليه -إقامة حد املسكر -النزول عن احلد األدنى بعقوبة السجن - التعزير بالسجن واملنع من السفر.","document_number":"34180358","case_number":"34141080","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/7","year":"1434","subject":"مخدرات -حيازة قطعة دون الوزن من احلشيش املخدر -حيازة سيجارة مخلوطة باحلشيش املخدر بقصد التعاطي -تعاطي احلشيش املخدر -حيازة مفتاح حتتوي غسالته على احلشيش املخدر -إقرار املدعى عليه-عدم وجود سوابق على املدعى عليه -إقامة حد املسكر -النزول عن احلد األدنى بعقوبة السجن - التعزير بالسجن واملنع من السفر.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34180358:‬تاريخه ‪1434/4/7:‬هـ‬\n                      ‫رقم الدعوى ‪34141080:‬‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 34228335‬تاريخه‪1434/06/03:‬هـ‬\n\n\n     ‫مخــدرات ‪ -‬حيــازة قطعــة دون الــوزن مــن احلشــيش املخــدر‪ -‬حيــازة‬\n     ‫ســيجارة مخلوطــة باحلشــيش املخــدر بقصــد التعاطــي ‪ -‬تعاطــي‬\n     ‫احلشــيش املخــدر‪ -‬حيــازة مفتــاح حتتــوي غســالته علــى احلشــيش‬\n     ‫املخــدر‪ -‬إقــرار املدعــى عليه‪-‬عــدم وجــود ســوابق علــى املدعــى عليــه‬\n     ‫‪ -‬إقامــة حــد املســكر ‪ -‬النــزول عــن احلــد األدنــى بعقوبــة الســجن ‪-‬‬\n                                     ‫التعزيــر بالســجن واملنــع مــن الســفر‪.‬‬\n\n\n\n\n              ‫‪ -1‬املادة (‪ ) 41‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n              ‫‪ -2‬املادة (‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n              ‫‪ -3‬املادة (‪ ) 60‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n\n\n\n\n     ‫دعــوى املدعــى العــام ضــد املدعــى عليــه مواطــن بحيــازة قطعــة دون‬\n     ‫الــوزن مــن احلشــيش املخــدر‪ ،‬حيــازة ســيجارة مخلوطــة باحلشــيش املخــدر‬\n     ‫بقصــد التعاطــي‪ ،‬تعاطــي احلشــيش املخــدر‪ ،‬حيــازة مفتــاح حتتــوي‬\n     ‫غســالته علــى احلشــيش املخــدر‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند‬\n     ‫إليــه واحلكــم عليــه بعقوبــة الســجن واملنــع مــن الســفر‪ ،‬مت القبــض علــى‬\n     ‫املدعــى عليــه بعــد اســتيقاف املدعــى عليــه وتفتيشــه وعثــر معــه علــى‬\n\n‫‪41‬‬\n\f‫مــادة احلشــيش املخــدر‪ ،‬إقــرار املدعــى عليــه‪ ،‬عــدم وجــود ســوابق علــى‬\n‫املدعــى عليــه‪ ،‬إقامــة حــد املســكر‪ ،‬النــزول عــن احلــد األدنــى بعقوبــة‬\n‫الســجن‪ ،‬تعزيــر املدعــى عليــه بالســجن واملنــع مــن الســفر‪ ،‬تصديــق‬\n                                         ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬القاضــي يف احملكمــة العامــة‬\n‫بينبــع وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بينبع‪/‬املســاعد برقــم ‪ 34141080‬وتاريــخ ‪ 1434/03/25‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 34709905‬وتاريــخ ‪ 1434/03/22‬ه ـ ففــي‬\n‫يــوم الســبت املوافــق‪ 1434/04/06‬ه ـ افتتحــت اجللســة الســاعة ‪: 30‬‬\n‫‪ 09‬وفيهــا حضــر املدعــي العــام بينبــع ‪..........‬املكلــف مبوجــب خطــاب‬\n‫ا بصفتــي مدعيــا‬   ‫رقــم (‪ )..........‬وتاريــخ ‪1433/6/24‬ه ـ وادعــى قائ ـ ً‬\n‫عامـ ًا بدائــر اإلدعــاء العــام لدائــرة التحقيــق مبحافظــة ينبــع أدعــي علــى‬\n‫‪..........‬ســعودي اجلنســية ســجل رقــم (‪ )..........‬والبالــغ مــن العمــر (‪)37‬‬\n‫عام ـ ًا حيــث أنــه بتاريــخ ‪1434/2/10‬ه ـ مت اســتيقاف ســيارة مــن قبــل‬\n‫مكافحــة املخــدرات مــن نــوع ‪ ....‬بقيــادة املتهــم املذكــور وبتفتيشــه‬\n‫شــخصي ًا عثــر علــى مفتــاح بــه آثــار حــرق يشــتبه بأنــه اســتخدمه يف‬\n‫حــرق احلشــيش املخــدر وبتفتيــش الســيارة عثــر بجــوار القيــر قطعــة دون‬\n‫الــوزن يشــتبه أن تكــون حشيش ـ ًا مخــدر ًا ووجــد داخــل الديكــور مــن‬\n‫أمــام الســائق بكــت دخــان عثــر بداخلــه علــى ســيجاره ملفوفــة لــف‬\n‫يــد بلــغ وزنهــا (‪ )1.4‬جرام ـ ًا وأربعــة أعشــار اجلــرام يشــتبه أن تكــون‬\n‫مخلوطــة باحلشــيش املخــدر ‪ .‬وقــد أثبــت التقريــر الكيميائــي الشــرعي‬\n\n                                                                                     ‫‪42‬‬\n\f     ‫رقــم (‪1434 )..........‬ه ـ إيجابيــة غســالة املفتــاح وإيجابيــة مســتخلص‬\n     ‫الســيجارة والقطعــة املرســلة للقنــب ‪-‬احلشــيش املخــدر‪ -‬وهــو مــن‬\n     ‫املــواد اخلاضعــة للرقابــة واملنــوه عنــه يف اجلــدول األول فئــة (أ) مــن نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وباســتجوابه اعتــرف بحيازتــه‬\n     ‫قطعــة دون الــوزن مــن احلشــيش املخــدر وســيجارة بلــغ وزنهــا (‪ )1.4‬جــرام‬\n     ‫وأربعــة أعشــار اجلــرام مخلوطــة باحلشــيش بقصــد التعاطــي وبحيازتــه‬\n     ‫مفتــاح يســتخدمه يف حــرق احلشــيش املخــدر واعتــرف بتعاطيــه احلشــيش‬\n     ‫املخدر ‪ .‬وببحث حالته اجلنائية تبني عدم وجود أي ســابقة مســجلة عليه‬\n     ‫‪.‬وقــد انتهــى التحقيــق بتوجــه االتهــام لــه بحيــازة قطعــة دون الــوزن مــن‬\n     ‫احلشــيش املخــدر وســيجارة مخلوطــة باحلشــيش املخــدر بلــغ وزنهــا (‪)1.4‬‬\n     ‫جــرام وأربعــة أعشــار اجلــرام بقصــد التعاطــي وتعاطيــه لنوعــه وحيــازة‬\n     ‫مفتــاح حتتــوي غســالته علــى احلشــيش املخــدر واملجــرم علــى ذلــك وفقـ ًا‬\n     ‫للمــادة الثالثــة الفقــرة الثانيــة مــن نظــام مكافحــة املخــدرات واملؤثــرات‬\n     ‫العقليــة وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬مــا جــاء يف اعترافــه علــى‬\n     ‫ص (‪ )1-2‬مــن دفتــر التحقيــق لفــة (‪ -2 .)13‬مــا ورد مبحضــر القبــض‬\n     ‫املرفــق لفــه (‪ -3 .)1‬مــا ورد بالتقريــر الكيميائــي الشــرعي واملرفــق‬\n     ‫لفــة (‪ .)29‬وحيــث أن مــا أقــدم عليــه املتهــم فعــل محــرم شــرع ًا ومجــرم‬\n     ‫ومعاقــب عليــه نظام ـ ًا وفق ـ ًا للمــادة الثالثــة الفقــرة الثانيــة مــن نظــام‬\n     ‫مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر باملرســوم امللكــي رقــم‬\n     ‫(م‪ )39/‬وتاريــخ ‪1426/7/8‬ه ـ ‪ ،‬أطلــب إثبــات مــا أســند إليــه واحلكــم‬\n     ‫عليــه بالعقوبــات التاليــة ‪ -1 :‬الســجن وفق ـ ًا للمــادة (‪ )41‬الفقــرة (‪)1‬‬\n     ‫مــن النظــام املشــار إليــه ‪ -2 .‬منعــه مــن الســفر إلــى خــارج البــاد بعــد‬\n     ‫انتهــاء محكوميتــه وفقـ ًا للفقــرة (‪ )1‬مــن املــادة (‪ )56‬مــن النظــام املشــار‬\n\n\n‫‪43‬‬\n\f‫إليــه ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه أجــاب بقولــه مــا ذكــره املدعــي‬\n‫العــام يف دعــواه صحيــح جملــة وتفصيــل فقــد مت القبــض علــي يف نقطــة‬\n‫التفتيــش وعثــر بحوزتــي علــى قطعــة مــن احلشــيش املخــدر وســيجارة‬\n‫مــن احلشــيش املخــدر القصــد مــن حيازتهــا التعاطــي واالســتعمال فأنــا‬\n‫أتعاطــى احلشــيش املخــدر يف الســابق ومــا حصــل منــي هــو خطــأ ولــن‬\n‫أعــود إليــه أبــد ًا ولــدي أطفــال يدرســون يف املــدارس ووالدتــي مريضــه‬\n‫وبحاجــه ملــن يخدمهــا ويعطيهــا العــاج وليــس لهــا بعــد اهلل إال أنــا‬\n‫وأطلــب مــن فضيلتكــم التخفيــف هكــذا أجــاب ‪ .‬ثــم جــرى االطــاع‬\n‫علــى أوراق املعاملــة وعلــى اعتــراف املدعــى عليــه وكذلــك علــى التقريــر‬\n‫الكيميائــي الشــرعي املرفــق ص (‪ )29‬وبنــاء علــى مــا تقــدم مــن الدعوى‬\n                      ‫واإلجابــة وإلقــرار املدعــى عليــه بدعــوى املدعــي العــام‬\n‫فقــد ثبــت لــدي دعــوى املدعــى العــام ضــد املدعــى عليــه ‪..........‬بحيــازة‬\n‫قطعــة مــن احلشــيش املخــدر وســيجارة مخلوطــة باحلشــيش املخــدر‬\n‫بقصــد االســتعمال وتعاطيــه الســابق للحشــيش املخــدر وبنــاء علــى املــادة‬\n‫(‪ )41‬مــن نظــام املخــدرات واملؤثــرات العقليــة واملــادة (‪ )56‬مــن نفــس‬\n‫النظــام وكذلــك علــى املــادة (‪ )60‬مــن نفــس النظــام بشــأن النــزول عــن‬\n‫احلــد األدنــى مــن العقوبــة املقــررة يف املــادة (‪ )41‬مــن النظــام لدواعــي‬\n‫معتبــرة تقدرهــا احملكمــة حيــث أن املدعــى عليــه ليــس لــه ســوابق وقــد‬\n‫قــرر التوبــة والرجــوع ولألعــذار التــي قدمهــا املدعــى عليــه ونظــر ًا لقلــة‬\n‫الكميــة التــي حــازه فقــد قــررت جلــده احلــد ثمانــون جلــدة دفعــة واحــده‬\n‫لقــاء تعاطيــه احلشــيش املخــدر وحبســه ملــدة ثالثــة أشــهر حتســب منهــا‬\n‫أي فتــرة أوقــف علــى ذمــة هــذه القضيــة ومنعــه مــن الســفر ملــدة ســنتني‬\n‫تبــدأ مــن تاريــخ انتهــاء محكوميتــه وبعرضــه علــى املدعــى عليــه قــرر‬\n\n\n                                                                                      ‫‪44‬‬\n\f     ‫رضــاه وقناعتــه باحلكــم وأمــا املدعــي العــام فلــم يقنــع بــه وطلــب متييــزه‬\n     ‫بــدون الئحــة اعتــراض وأجيــب لطلبــه ‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل‬\n     ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/04/06‬هـ‬\n     ‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق‪ 1434/07/15‬ه ـ‬\n     ‫افتتحــت اجللســة وفيهــا جــرى االطــاع علــى قــرار محكمــة االســتئناف‬\n     ‫رقــم ( ‪ ) 34228335‬وتاريــخ ‪ 1434/06/03‬واملتضمــن مــا نصــه (‬\n     ‫وبدراســة القــرار وصــورة ضبطــه تقــرر باألكثريــة املوافقــة علــى احلكم‬\n     ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n     ‫قاضــي اســتئناف ‪..........‬ختــم وتوقيــع قاضــي اســتئناف ‪ ..........‬ختــم‬\n     ‫وتوقيــع رئيــس الدائــرة ‪..........‬ختــم وتوقيــع ) انتهــى ‪ .‬وبــاهلل التوفيــق‬\n     ‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n                                                                    ‫‪ 1434/07/15‬ه ـ‬\n\n\n\n\n‫‪45‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":41,"source_page_end":45,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c7f2faa99e0891486ba3d561af472591c78d9fb9237bb33125608e85c6133320","normalized_text_hash":"5c82f2a8bd80d91563f5cba46024bb64cf9f496e8849a5ae64ddabc9753643b5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p41-34180358"},{"id":"036a1d13-18dc-5cc7-9c23-bb17db1f4462","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -شروع يف إهداء حبوب محظورة وتعاطيها ومحاولة إدخالها إلى السجن -إقرار -إدانة -االكتفاء بالعقوبة األشد- تداخل العقوبات التعزيرية -تعزير بالسجن واجللد واملنع من السفر -رد دعوى.","document_number":"34192492","case_number":"34144482","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم بعد اإلجراء األخير","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/20","year":"1434","subject":"مخدرات -شروع يف إهداء حبوب محظورة وتعاطيها ومحاولة إدخالها إلى السجن -إقرار -إدانة -االكتفاء بالعقوبة األشد- تداخل العقوبات التعزيرية -تعزير بالسجن واجللد واملنع من السفر -رد دعوى.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 34192492 :‬تاريخه ‪1434/4/20 :‬هـ‬\n                       ‫رقم الدعوى ‪34144482 :‬‬\n‫رقم قرار التصديق من محكمة االستئناف‪34309329 :‬‬\n                         ‫تاريخه‪1434/08/29 :‬هـ‬\n\n\n      ‫مخــدرات ‪ -‬شــروع يف إهــداء حبــوب محظــورة وتعاطيهــا ومحاولــة‬\n      ‫إدخالهــا إلــى الســجن‪ -‬إقــرار‪ -‬إدانــة‪ -‬االكتفــاء بالعقوبــة األشــد‪-‬‬\n      ‫تداخــل العقوبــات التعزيريــة ‪ -‬تعزيــر بالســجن واجللــد واملنــع مــن‬\n                                                          ‫الســفر ‪ -‬رد دعــوى‪.‬‬\n\n\n\n\n       ‫‪ -1‬املادتان (‪ )41‬و(‪ )56‬من نظام مكافحة املخدرات واملؤثرات العقلية‪.‬‬\n                                ‫‪ -2‬املادة (‪ )29‬من نظام السجن والتوقيف‪.‬‬\n\n\n\n\n      ‫دعوى جزائية عامة ضد املدعى عليه تتضمن طلب إثبات إدانته بحيازة‬\n      ‫احلبــوب احملظــورة بقصــد التعاطــي واإلهــداء وتعاطيــه لهــا والشــروع يف‬\n      ‫إهداءهــا ومحاولــة إدخالهــا داخــل التوقيــف‪ ،‬واحلكــم عليــه بعقوبــة‬\n      ‫الســجن واجللــد والغرامــة واملصــادرة واملنــع مــن الســفر طبقــا لنظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة وبعقوبــة الســجن طبق ـ ًا لنظــام‬\n      ‫الســجن والتوقيــف‪ ،‬طلــب زيــارة أحــد املوقوفــن وكان بحوزتــه كيــس‬\n      ‫بــه عــدد مــن األغــراض وبتفتيشــها عثــر فيهــا علــى احلبــوب احملظــورة‬\n      ‫وبتفيــش ســيارته عثــر فيهــا علــى احلبــوب احملظــورة أيضاً‪ ،‬أثبــت التقرير‬\n      ‫الكيميائــي الشــرعي إيجابيــة العينــة املرســلة لإلمفيتامــن‪ ،‬أقــر أمــام‬\n\n                                                                                       ‫‪46‬‬\n\f     ‫احملكمــة مبــا أســنده إليــه املدعــي العــام‪ ،‬املدعــى عليــه تنطبــق بحقــه‬\n     ‫العقوبــات املنصــوص عليهــا يف نظــام مكافحــة املخــدر ونظــام الســجن‬\n     ‫والتوقيــف فيكتفــى بالعقوبــة األشــد‪ ،‬قضــت احملكمــة بإدانــة املدعــى‬\n     ‫عليــه بجميــع مــا نســب إليــه وقــررت جلــده خمس ـ ًا وســبعني جلــدة دفعــة‬\n     ‫واحــدة وســجنه ملــدة ثــاث ســنوات ومنعــه مــن الســفر خــارج اململكــة‬\n     ‫ملــدة ثــاث ســنوات كمــا قضــت بــرد باقــي طلبــات املدعــي العــام‪،‬‬\n     ‫عــارض املدعــى عليــه واملدعــي العــام علــى احلكــم‪ ،‬قــررت محكمــة‬\n                     ‫االســتئناف املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر‪.‬‬\n\n\n\n\n     ‫اجلزائيــة‬\n        ‫ّ‬         ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ................‬رئيــس احملكمــة‬\n     ‫بســكاكا وبنــاء علــى املعاملــة احملالــة لنــا برقــم ‪ 34144482‬وتاريــخ‬\n     ‫‪1434/03/28‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34767072‬وتاريــخ‬\n     ‫‪1434/03/28‬ه ـ ففــي هــذا اليــوم الثالثــاء املوافــق ‪1434/04/09‬ه ـ‬\n     ‫افتتحــت اجللســة األولــى الســاعة ‪ 09 :00‬وفيهــا قــدم املدعــي العــام‬\n     ‫الئحــة دعــوى عامــة ضــد ‪ ........‬ســعودي بالســجل املدنــي رقــم ‪........‬‬\n     ‫قائــا فيهــا بتاريــخ ‪1434/02/18‬ه ـ ورد إلدارة مكافحــة املخــدرات‬\n     ‫محضــر الفرقــة املناوبــة بــإدارة تنفيــذ األحــكام احلقوقيــة املتضمــن‬\n     ‫حضــور املتهــم املذكــور إليهــم لزيــارة املوقــوف بــاإلدارة‪ /‬وكان بحوزته‬\n     ‫أغــراض داخــل كيــس عبــارة عــن زجاجتــي ‪ .......‬وعلبتــي ســجائر‬\n     ‫وورقــة شــحن ‪ .......‬وأربــع أكيــاس بطاطــس ‪ .......‬وبتفتيــش أكيــاس‬\n     ‫البطاطــس عثــر بداخــل أحدهــا علــى عــدد خمــس حبــات صغيــرة دائريــة‬\n     ‫الشــكل لونهــا بيــج يشــتبه أن تكــون مــن احلبــوب احملظــورة فأفــاد أن‬\n\n‫‪47‬‬\n\f‫ســيارته مــن نــوع ‪ .....‬ســنة الصنــع ‪ .....‬يحمــل لوحــة رقــم (‪ ( )........‬جــرى‬\n‫ا للمصــادرة) علــى قيــد‬    ‫إصــدار أمــر بحجــز الســيارة لكونهــا مح ـ ً‬\n‫التشــغيل ويريــد إطفائهــا وعنــد الذهــاب إلــى الســيارة إلطفــاء احملــرك‬\n‫عثــر بداخــل الســيارة يف درج أكــواب العصيــر علــى عــدد أربــع حبــات‬\n‫إحداهــا مكســورة إلــى نصفــن فتــم القبــض علــى املتهــم (( التصــرف‬\n‫باملتهــم موقــوف اســتناد ًا للقــرار الــوزاري ‪ )) 1900‬وباســتجواب املتهــم‬\n‫اعتــرف مبــا جــاء يف محضــر القبــض والتفتيــش وأن قصــده مــن‬\n‫إدخــال احلبــوب احملظــورة إلــى داخــل التوقيــف أثنــاء الزيــارة ألجــل أن‬\n‫يســتعملها هــو وصديقــه وقــد أثبــت التقريــر الكيميائــي الصــادر مــن‬\n‫مركــز مراقبــة الســموم بتبــوك برقــم ( ‪559‬م ‪ /‬م س ت) وتاريــخ‬\n‫‪1434/03/07‬ه ـ إيجابيــة العينتــن مــن املضبــوط ملــادة اإلمفيتامــن‬\n‫املنبهــة للجهــاز العصبــي واملــدرج باجلــدول الثانــي فئــة (ب) مــن تعميــم‬\n‫صاحــب الســمو امللكــي النائــب الثانــي لرئيــس مجلــس الــوزراء وزيــر‬\n‫الداخليــة رقــم‪ 74831‬وتاريــخ ‪1431/07/09‬هـ ـ وانتهــى التحقيــق إلــى‬\n‫توجيــه االتهــام لــ‪ ...../‬بالشــروع يف إهــداء عــدد (‪ )5‬خمــس حبــات مــن‬\n‫حبــوب اإلمفيتامــن املنبهــة للجهــاز العصبــي املجــرم مبوجــب الفقــرة‬\n‫الثانيــة مــن املــادة الثالثــة مــن نظــام مكافحــة املخــدرات ومحاولــة‬\n‫إدخالهــا إلــى داخــل التوقيــف ألحــد املوقوفــن واملجــرم مبوجــب الفقــرة‬\n‫(‪ )1‬مــن املــادة (‪ )29‬مــن نظــام الســجن والتوقيــف وحيــازة عــدد (‪ )4‬أربــع‬\n‫حبــات مــن حبــوب اإلمفيتامــن املنبهــة للجهــاز العصبــي بقصــد التعاطــي‬\n‫وتعاطيــه لــذات النــوع يف الســابق واملجــرم مبوجــب الفقــرة الثانيــة مــن‬\n‫املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ .‬وذلــك‬\n‫لألدلــة والقرائــن التاليــة‪ -1 :‬مــا جــاء يف اســتجواب املتهــم املــدون علــى‬\n\n\n                                                                                       ‫‪48‬‬\n\f     ‫اللفــات رقــم ( ‪ )10،9،8‬وعلــى الصفحــة رقــم (‪ )18‬مــن ملــف إجــراءات‬\n     ‫ضبــط االســتدالل لفــة رقــم (‪ -2)4‬مــا جــاء يف محضــر القبــض لفــة رقــم‬\n     ‫(‪ -3 )2‬مــا جــاء بالتقريــر الكيميائــي الشــرعي لفــة رقــم (‪ .)20‬وحيــث‬\n     ‫إن مــا أقــدم عليــه املتهــم وهــو بكامــل أهليتــه املعتبــرة شــرعا فعــل محرم‬\n     ‫ومعاقــب عليــه شــرعا ممــا يتعــن معــه إحالته للمحكمة اجلزئية اســتنادا‬\n     ‫للمادتــن (‪ )128،126‬مــن نظــام اإلجــراءات اجلزائيــة فإننــي أطلــب‬\n     ‫إثبــات إدانتــه مبــا أســند إليــه واحلكــم عليــه باآلتــي‪ ]1 :‬ـ عقوبــة الســجن‬\n     ‫واجللــد والغرامــة بحدهــا األعلــى وفق ـ ًا للفقــرة (‪ )1‬مــن املــادة (‪ )38‬مــن‬\n     ‫نظــام مكافحــة املخــدرات واملؤثــرات العقليــة‪ ]2 .‬ـ منعــه مــن الســفر إلــى‬\n     ‫خــارج اململكــة العربيــة الســعودية اســتناد ًا للفقــرة (‪ )1‬مــن املــادة (‪)56‬‬\n     ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ ]3‬ـ مصــادرة الســيارة‬\n     ‫مــن نــوع ‪ .....‬ســنة الصنــع ‪ .....‬يحمــل لوحــة رقــم ( ) ؛ اســتنادا للمادة (‪)53‬‬\n     ‫مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ‪ -]4‬عقوبــة الســجن‬\n     ‫الــواردة يف الفقــرة (‪ )1‬مــن املــادة (‪ )29‬مــن نظــام الســجن والتوقيــف هــذه‬\n     ‫دعــواي وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب بقولــه ما‬\n     ‫ذكــره املدعــي العــام كلــه صحيــح فقــد رغبــت بزيارة صديــق لي يدعى‬\n     ‫‪ .....‬داخــل توقيــف احلقــوق املدنيــة واشــتريت لــه بعــض األغــراض وكان‬\n     ‫يوجــد عنــدي بعــض احلبــوب احملظــورة فوضعــت خمــس حبــات داخــل‬\n     ‫كيــس البطاطــس وبقــي أربــع حبــات بالســيارة فتــم القبــض علــي مــن‬\n     ‫قبــل رجــال األمــن عندمــا قامــوا بتفتيــش األغــراض وقصــدي مــن احليــازة‬\n     ‫هــو التعاطــي وقــد تعاطيــت احلبــوب احملظــورة يف الســابق وقصــدي‬\n     ‫مــن إدخــال احلبــوب أن اتعاطاهــا مــع داخــل التوقيــف علمــا أن ‪........‬‬\n     ‫لــم يطلــب منــي ذلــك هكــذا أجــاب ولــذا جــرى رفــع اجللســة لدراســتها‬\n\n\n‫‪49‬‬\n\f‫وتأملهــا إلــى يــوم الســبت ‪1434/04/13‬ه ـ الســاعة العاشــرة وعليــه‬\n‫جــرى التوقيــع وأقفلــت اجللســة يف متــام الســاعة العاشــرة والنصــف‪ .‬حــرر‬\n‫يف ‪1434/04/09‬ه ـ ويف هــذا اليــوم الســبت املوافق‪1434/04/20‬ه ـ‬\n‫افتتحــت اجللســة الثالثــة يف متــام الســاعة ‪ 08:00‬وفيهــا حضــر املدعــى‬\n‫عليــه هــذا وقــد جــرى االطــاع علــى أوراق املعاملــة فوجــدت مــن بــن‬\n‫طياتهــا التقريــر الكيميائــي الشــرعي رقــم ‪ 559‬م ‪ /‬م س ت املــدون‬\n‫علــى اللفــة العشــرين وباالطــاع عليــه وجدتــه كمــا ذكــر املدعــي‬\n‫العــام يف دعــواه لــذا وبنــاء علــى مــا ســبق مــن الدعــوى واإلجابــة وحيــث‬\n‫صــادق املدعــى عليــه علــى دعــوى املدعــي العــام ومؤاخــذة للمدعــى عليــه‬\n‫بإقــراره وإلــى مــا يــدل عليــه التقريــر الكيميائــي الشــرعي املشــار إليــه‬\n‫آنفــا وحيــث إن فعــل املدعــى عليــه يعــد اســتخفافا بالــدور اإلصالحيــة‬\n‫يف محاولــة إدخالــه احلبــوب احملظــورة إلــى مــن بداخلهــا ولوجــود‬\n‫ســابقة علــى املدعــى عليــه بحيــازة واســتعمال املخــدرات ممــا يــدل علــى‬\n‫عــدم ارتداعــه بالعقوبــة الســابقة وحيــث إن مــن مواطــن التشــديد يف‬\n‫املخــدرات واملؤثــرات العقليــة إذا ارتكــب اجلانــي جرميتــه أو جــزءا منهــا‬\n‫يف املؤسســات اإلصالحيــة وحيــث إن املدعــى عليــه ينطبق بحقه نظامان‬\n‫هــو نظــام مكافحــة املخــدرات واملؤثــرات العقليــة ونظــام الســجن‬\n‫والتوقيــف وحيــث نــص النظامــان أنــه إذا كانــت اجلرميــة معاقــب عليهــا‬\n‫مبوجــب نظامــن فتطبــق العقوبــة األشــد مــن هذيــن النظامــن وحيــث‬\n‫إن املدعــى عليــه تنطبــق بحقــه املادتــان احلاديــة واألربعــون والسادســة‬\n‫واخلمســون مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة واملــادة‬\n‫التاســعة والعشــرون مــن نظــام الســجن والتوقيــف وحيــث إن العقوبــات‬\n‫التعزيريــة تتداخــل لــذا فقــد ثبــت لــدي إدانــة املدعــى عليــه بالشــروع يف‬\n\n\n                                                                                    ‫‪50‬‬\n\f     ‫إهــداء خمــس حبــات مــن احلبــوب احملظــورة ومحاولــة إدخالهــا إلــى داخــل‬\n     ‫التوقيــف وحيــازة أربــع حبــات مــن احلبــوب احملظــورة وجميعهــا بقصــد‬\n     ‫التعاطــي وتعاطيــه للحبــوب احملظــورة وحيــث إن العقوبــة األشــد هــي‬\n     ‫يف نظــام الســجن والتوقيــف يف مثــل هــذه القضيــة لــذا أوال‪ :‬فقــد قــررت‬\n     ‫تعزيــره وذلــك بســجنه ثــاث ســنوات مــن تاريــخ إيقافــه بنــاء علــى املــادة‬\n     ‫التاســعة والعشــرين مــن نظــام الســجن والتوقيــف ثانيــا‪ :‬مينــع املدعى عليه‬\n     ‫مــن الســفر خــارج اململكــة ملــدة ثــاث ســنوات بعــد انتهــاء محكوميتــه‬\n     ‫ثالثــا‪ :‬يجلــد املدعــى عليــه خمســا وســبعني جلــدة دفعــة واحــدة لقــاء‬\n     ‫تعاطيــه للحبــوب احملظــورة رابعــا‪ :‬حكمــت بــرد طلــب املدعــي العــام‬\n     ‫بتطبيــق املــادة الثامنــة والثالثــن يف فقرتهــا األولــى مــن نظــام مكافحــة‬\n     ‫املخــدرات واملؤثــرات العقليــة لعــدم انطباقهــا بهــذه القضيــة خامســا‪:‬‬\n     ‫صرفــت النظــر عــن طلــب املدعــي العــام مبصــادرة الســيارة مــن نــوع ‪.....‬‬\n     ‫لعــدم انطبــاق نظــام مكافحــة املخــدرات عليهــا يف املصــادرة و بجميــع‬\n     ‫مــا ذكــر قضيــت وبعــرض ذلــك علــى املدعــى عليــه واملدعــي العــام قــررا‬\n     ‫عــدم القناعــة وطلبــا االســتئناف فأفهمتهمــا أنــه ســوف يســلم لــكل‬\n     ‫واحــد منهمــا نســخة مــن احلكــم لالعتــراض عليــه وذلــك يــوم االثنــن‬\n     ‫القــادم املوافــق ‪1434/04/22‬ه ـ وأن لــكل واحــد منهمــا مــدة نظاميــة‬\n     ‫وهــي ثالثــون يومــا مــن ذلــك التاريــخ يقــدم كل واحــد منهمــا الئحتــه‬\n     ‫االعتراضيــة ففهمــا ذلــك وعليــه جــرى التوقيــع وأقفلــت اجللســة يف متــام‬\n     ‫الســاعة الثامنــة والنصــف وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n     ‫محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/04/20‬ه ـ احلمــد هلل‬\n     ‫اجلزائيــة بســكاكا ويف هــذا‬  ‫ّ‬       ‫وحــده وبعــد فلــدي أنــا رئيــس احملكمــة‬\n     ‫اليــوم االثنــن املوافــق‪ 1434/05/27‬ه ـ افتتحــت اجللســة الســابعة يف متــام‬\n\n\n‫‪51‬‬\n\f‫الســاعة احلاديــة عشــرة هــذا وقــد انتهــت املــدة النظاميــة للمدعــي العــام‬\n‫ولــم يقــدم الئحتــه االعتراضيــة لــذا فقــد ســقط حقــه يف االعتــراض‬\n‫وألمــرت برفــع كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق‬\n‫احلكــم وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وســلم‪ .‬حــرر يف ‪ 1434/05/27‬ه ـ احلمــد هلل وحــده وبعــد فلــدي‬\n‫اجلزائيــة بســكاكا ويف هــذا اليــوم األحــد املوافــق‬\n                                                   ‫ّ‬      ‫أنــا رئيــس احملكمــة‬\n‫‪1434/07/23‬ه ـ افتتحــت اجللســة الثامنــة يف متــام الســاعة ‪ 00:11‬هــذا‬\n‫وقــد عــادت املعاملــة مــن محكمــة االســتئناف مبنطقــة اجلــوف وبرفقهــا‬\n‫القــرار رقــم ‪ 34241793‬وتاريــخ ‪1434/06/14‬ه ـ واملتضمــن بعــد‬\n‫املقدمــة وبدراســة القــرار وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق‬\n‫املعاملــة لوحــظ باألكثريــة أن مــا حكــم بــه فضيلتــه مــن ســجن كثيــر‬\n‫جــدا نظــرا ملــا أبــداه املدعــى عليــه يف الئحتــه مــن وجود اضطراب نفســي‬\n‫لديــه كمــا أن الكميــة قليلــة وال فائــدة مــن طــول فتــرة ســجنه‪ .‬فعلــى‬\n‫فضيلتــه مالحظــة مــا ذكــر وإجــراء موجبــه انتهــى‪ .‬وجوابــا علــى مــا‬\n‫ذكــره أصحــاب الفضيلــة أقــول إنــه ال يخفــى على شــريف علــم أصحاب‬\n‫الفضيلــة مــا تعانيــه هــذه املنطقــة مــن انتشــار املخــدرات بجميــع أنواعهــا‬\n‫لكونهــا منطقــة حدوديــة وال أدل علــى ذلــك مــا يــرد إلــى محكمــة‬\n‫االســتئناف مــن كثــرة قضايــا تهريــب املخــدرات مــن مدينــة القريــات‬\n‫وغيرهــا وقــد ســببت هــذه املخــدرات أمراضــا مزمنــة علــى مســتعمليها‬\n‫كالعنــف العدوانــي والشــك والهلوســة وانفصــام الشــخصية ومــا يعانيــه‬\n‫املدعــى عليــه مــن قبيــل هــذه األمــراض وحيــث إن القاعــدة الشــرعية يف‬\n‫العقــاب أنــه إذا انتشــرت معصيــة وتســاهل النــاس بهــا وجــب التشــديد‬\n‫يف العقوبــة مــن أجــل الــردع والزجــر كمــا أن مــن أســباب تشــديد‬\n\n\n                                                                                     ‫‪52‬‬\n\f     ‫العقوبــة إدخــال املخــدرات إلــى أماكــن التوقيــف ودور التعليــم وحيــث‬\n     ‫وردت التعليمــات بتشــديد العقوبــة علــى مروجــي ومســتعملي املخــدرات‬\n     ‫حســما ملــادة الفســاد ومحاربــة لهــذا الــداء العضــال الــذي فتــك يف عقــول‬\n     ‫شــبابنا لــذا لــم يظهــر لــي ســوى مــا حكمــت بــه وأمــرت برفــع كامــل‬\n     ‫أوراق املعاملــة ألصحــاب الفضيلــة التخــاذ مــا يــرون وعليــه جــرى التوقيــع‬\n     ‫وأقفلــت اجللســة يف متــام الســاعة احلاديــة عشــرة والربــع وبــاهلل التوفيــق‪،‬‬\n     ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                                    ‫‪1434/07/23‬ه ـ‬\n     ‫احلمــد اهلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضاة الدائــرة األولى لتمييز‬\n     ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة اجلــوف علــى املعاملــة‬\n     ‫الــواردة مــن فضيلتــة رئيــس احملكمــة اجلزائيــة بســكاكا الشــيخ‪...../‬‬\n     ‫برقــم ‪ 341557671‬وتاريــخ ‪1434/07/23‬ه ـ املرفــق بهــا القرار الصادر‬\n     ‫مــن فضيلتــه املســجل برقــم ‪ 34192492‬وتاريخ ‪1434/04/20‬هـ اخلاص‬\n     ‫بدعــوى املدعــي العــام ضــد‪ ..../‬يف قضيــة مخــدرات وقــد تضمــن القــرار‬\n     ‫حكــم علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة‬\n     ‫ضبطــه بنــاء علــى قرارنــا رقــم ‪ 34241793‬يف ‪1434/06/14‬ه ـ قررنــا‬\n     ‫املصادقــة علــى احلكــم بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل‬\n                                    ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪53‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":46,"source_page_end":53,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"deb0588551aafe77111c3d8d4e62eb7c9f637747b25a013caea6fb1ee6dc36ca","normalized_text_hash":"c5123e2e8c491840ec484b47197a233952fa91318ec04a0d6d21f0d89e48f5fe","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p46-34192492"},{"id":"d2df59f5-d64f-518b-9ec6-2e9d6387872d","document_type":"judgment","category":"judicial","subcategory":"general","title":"مخدرات -حيازة أفيون بقصد التعاطي -تعاطي الهيروين -حيازة مخدرات قبل صدور نظام مكافحة املخدرات -عدم قبول الشهادة املكتوبة -تعزير بالقرائن للتهمة القوية -التعزير باجللد.","document_number":"34184868","case_number":"34148702","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف املصادقة على احلكم","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/01","year":"1434","subject":"مخدرات -حيازة أفيون بقصد التعاطي -تعاطي الهيروين -حيازة مخدرات قبل صدور نظام مكافحة املخدرات -عدم قبول الشهادة املكتوبة -تعزير بالقرائن للتهمة القوية -التعزير باجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34184868:‬تاريخه ‪1434/04/01:‬هـ‬\n                    ‫رقم الدعوى‪34148702 :‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 34791605‬تاريخه‪1434/6/26:‬هـ‬\n\n\n  ‫مخــدرات‪ -‬حيــازة أفيــون بقصــد التعاطــي‪ -‬تعاطــي الهيرويــن‪ -‬حيــازة‬\n  ‫مخــدرات قبــل صــدور نظــام مكافحــة املخــدرات‪ -‬عــدم قبــول الشــهادة‬\n           ‫املكتوبــة‪ -‬تعزيــر بالقرائــن للتهمــة القويــة‪ -‬التعزيــر باجللــد‪.‬‬\n\n\n\n\n  ‫‪ -1‬جــاء يف كشــاف القنــاع (‪« :)337/4‬وال يجــوز للقاضــي احلكــم‬\n                                       ‫برؤيــة خــط الشــاهد‪ ..‬إلــخ»‪.‬‬\n                           ‫‪ -2‬املادة (‪ )120‬من نظام املرافعات الشرعية‪.‬‬\n                         ‫‪ -3‬املادة (‪ )169‬من نظام االجراءات اجلزائية‪.‬‬\n\n\n\n\n  ‫ادعــى املدعــي العــام ضــد املدعــى عليــه بإدانتــه بحيــازة األفيــون املخــدر‬\n  ‫وتعاطــي الهيرويــن‪ ،‬واحلكــم عليــه بحــد املســكر وإفهامــه بــأن عقوبتــه‬\n  ‫علــى احليــازة عائــدة لولــي األمــر (الواقعــة قبــل صــدور نظــام مكافحــة‬\n  ‫املخــدرات واملؤثــرات العقليــة)‪ ،‬قبــض علــى املدعــى عليــه أثــر قيامــه‬\n  ‫بإخــراج شــيء مــن جيبــه ورميــه علــى األرض وبتفتيــش املوقــع الــذي‬\n  ‫كان فيــه عثــر علــى قطعــة يشــتبه أن تكــون مــن األفيــون‪ ،‬أثبــت‬\n  ‫التقريــر الكيميائــي الشــرعي إيجابيــة العينــة املرســلة ملــادة األفيــون‬\n  ‫املخــدر واعتــرف املدعــى عليــه أمــام جهــة التحقيــق بتعاطــي الهيرويــن‪،‬‬\n\n                                                                                       ‫‪54‬‬\n\f     ‫أنكــر أمــام احملكمــة مــا أســنده إليــه املدعــي العــام ورجــع عــن إقــراره‬\n     ‫بتعاطــي الهيرويــن‪ -‬طلبــت احملكمــة مــن املدعــي العــام تقــدمي بيناتــه‬\n     ‫وقــررت ســماع شــهادة شــهود محضــر القبــض فعجــز املدعــي العــام عــن‬\n     ‫إحضارهــم‪ ،‬مــن املقــرر شــرع ًا ونظام ـ ًا أن الشــهادة تــؤدى مشــافهة يف‬\n     ‫مجلــس احلكــم‪ ،‬بنــاء علــى مــا تقــدم حكمــت احملكمــة بــرد طلــب‬\n     ‫املدعــي العــام إدانــة املدعــى عليــه بحيــازة األفيــون املخــدر بقصــد‬\n     ‫التعاطــي ووجهــت لــه التهمــة بتعاطــي الهيرويــن وقــررت جلــده ســبعني‬\n     ‫جلــدة دفعــة واحــدة‪ ،‬قنــع املدعــى عليــه باحلكــم وعــارض املدعــي العــام‬\n                 ‫عليــه‪ ،‬قــررت محكمــة االســتئناف املصادقــة علــى احلكــم‪.‬‬\n\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة اجلزائيــة بتبــوك‬\n     ‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة‬\n     ‫بتبوك‪/‬املكلــف برقــم ‪ 34148702‬وتاريــخ ‪ 1434/04/01‬ه ـ املقيــدة‬\n     ‫باحملكمــة برقــم ‪ 34791605‬وتاريــخ ‪ 1434/04/01‬ه ـ ففــي يــوم‬\n     ‫األربعــاء املوافــق‪ 1434/04/10‬ه ـ حضــر املدعي العام ســعودي اجلنســية‬\n     ‫مبوجــب الســجل املدنــي رقــم ‪ .................‬واملعمــد مــن مرجعــه مبوجــب‬\n     ‫اخلطــاب رقــم ‪........‬يف ‪1433/9/5‬ه ـ وادعــى ضــد احلاضــر معــه ســعودي‬\n     ‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .................‬والــذي يبلــغ مــن العمــر‬\n     ‫(‪ )43‬عامــا قائــا يف تقريــر دعــواه إنــه بتاريــخ ‪1425/12/28‬ه ـ شــوهد‬\n     ‫املدعــى عليــه يقــف يف أحــد الزوايــا و معــه املدعــو (لــم يوجــه لــه االتهــام‬\n     ‫وأطلــق صراحــه اســتنادا للمــادة ‪ 124‬مــن نظــام اإلجــراءات اجلزائيــة‬\n     ‫وعنــد اقتــراب فرقــة يف إدارة مكافحــة املخــدرات مــن املذكــور قــام‬\n\n‫‪55‬‬\n\f‫بإخــراج شــيء مــن جيبــه ورميــه علــى األرض وبالقبــض عليــه وتفتيشــه لم‬\n‫يعثــر معــه علــى شــيء ممنــوع وبتفتيــش املوقــع الــذي كانــا فيــه عثــر علــى‬\n‫قطعة ســوداء اللون يشــتبه أن تكون أفيون بلغ وزنها تســعمائة مليجرام‬\n‫فجــرى اصطحــاب املذكوريــن إلــى مقــر اإلدارة وقــد أثبــت التقريــر‬\n‫الكيميائــي الشــرعي املرفــق رقــم (‪ )........‬لعــام ‪1426‬ه ـ إيجابيــة مــا مت‬\n‫ضبطــه لألفيــون املخــدر وبالبحــث عــن ســوابقه عثــر لــه علــى ســابقة‬\n‫مخــدرات وقــد أســفر التحقيــق معــه عــن اتهامــه بحيــازة قطعــة أفيــون‬\n‫بلــغ وزنهــا تســعمائة مليجــرام بقصــد التعاطــي وتعاطيــه للهرويــن املخــدر‬\n‫مــن قبــل وحيــث إن مــا أقــدم عليــه املذكــور فعــل محــرم ومعاقــب عليــه‬\n‫شــرعا ونظامــا لــذا أطلــب أوال‪ :‬إثبــات مــا أســند إليــه ثانيــا‪ :‬احلكــم عليــه‬\n‫بحــد املســكر لقــاء تعاطيــه لــه ثالثــا‪ :‬إفهامــه بــأن عقابــه علــى حيازتــه‬\n‫لتســعمائة ملليجــرام مــن األفيــون املخــدر بقصــد التعاطــي عائــد لولــي‬\n‫األمــر هكــذا ادعــى وبســؤال املدعــى عليــه عــن الدعــوى أجــاب بقولــه‬\n‫مــا جــاء يف دعــوى املدعــي العــام غيــر صحيــح فلــم اتعاطــى الهرويــن ولــم‬\n‫يكــن بحوزتــي أي قطعــة مــن األفيــون أثنــاء القبــض علــي والســابقة‬\n‫املنســوبة إلــي يف الدعــوى صحيحــة وهــي قدميــة هكــذا أجــاب وبطلــب‬\n‫البينــة مــن املدعــي العــام قــال بينتــي مــا جــاء يف الئحــة الدعــوى وأوراق‬\n‫املعاملــة وبالرجــوع ألوراق املعاملــة وجــدت علــى الصفحــة رقــم (‪ )11‬لفــه‬\n‫رقــم(‪ )8‬إقــرارا مؤرخــا بتاريــخ ‪1426/1/3‬ه ـ منســوب للمدعــى عليــه‬\n‫وفيــه أقــر وأعتــرف بأننــي تعاطيــت الهرويــن املخــدر منــذ شــهرين تقريبــا‬\n‫أ‪.‬ه ـ وعليــه توقيــع بالبصمــة منســوب للمدعــى عليــه وبعرضــه عليه أجاب‬\n‫بقولــه صحيــح أننــي قمــت بالتبصيــم علــى هــذا اإلقــرار لكــن مضمونــه‬\n‫غيــر صحيــح فأنــا لــم أذكــر للمحقــق بأننــي اســتعملت الهرويــن هكــذا‬\n\n\n                                                                                        ‫‪56‬‬\n\f     ‫أجــاب وبالرجــوع حملضــر القبــض املــدون علــى الصفحــة األولى مــن اللفة‬\n     ‫رقــم(‪ )6‬جــاء فيــه مــا نصــه إنــه بتاريــخ ‪1425/12/28‬ه ـ وأثنــاء قيامنــا‬\n     ‫مبســح حــي ‪ ........‬بتبــوك شــوهد أحــد األشــخاص املعروفــن لدينــا يف‬\n     ‫مجــال ترويــج املخــدرات وخصوصــا الهرويــن املخــدر يقــف يف أحــد‬\n     ‫الزوايــا و معــه شــخص آخــر وعنــد اقتــراب الدوريــة الرســمية منهمــا قــام‬\n     ‫الشــخص املعــروف والــذي يدعــى بإخــراج شــيء مــن جيبــه ورميــه علــى‬\n     ‫األرض وبالقبــض عليهمــا اتضــح أن الشــخص املعــروف لدينــا يدعــى‬\n     ‫‪ ........‬وهــو مــن مدمنــي ومروجــي املخــدرات وخصوصــا الهرويــن املخــدر‬\n     ‫وبتفتيشــه لــم يعثــر معــه علــى شــيء محظــور أو ممنــوع واتضــح أن األخــر‬\n     ‫يدعــى وبتفتيشــه لــم يعثــر معــه علــى شــيء ممنــوع أو محظــور وبتفتيــش‬\n     ‫املوقــع الــذي كانــا فيــه عثــر علــى قطعــه ســوداء اللــون يشــتبه أن تكــون‬\n     ‫أفيــون بلــغ وزنهــا تســعمائة مليجــرام كمــا عثــر علــى مفاتيــح ســيارة ‪.....‬‬\n     ‫عائــده للمدعــو ‪........‬كمــا أتضــح أن للمدعــو ســيارة مــن نــوع ‪ ....‬رقــم‬\n     ‫اللوحــة (‪ )...‬تقــف علــى اجلانــب اآلخــر مــن الرصيــف وقــد جــرى تفتيشــها‬\n     ‫ولــم يعثــر بهــا علــى ممنوعــات هــذا أ‪.‬ه ـ وحتــت هــذا احملضــر توقيــع‬\n     ‫منســوب ألعضــاء الفرقــة وبعرضــه علــى املدعــى عليــه أجــاب بقولــه مــا‬\n     ‫جــاء يف هــذا احملضــر مــن أننــي رميــت قطعــة األفيــون فغيــر صحيــح وال‬\n     ‫أعلــم عــن هــذه القطعــة شــيئا هكــذا أجــاب وبطلــب إحضــار أعضــاء‬\n     ‫الفرقــة مــن املدعــي العــام قــال ال أســتطيع إحضارهــم ألن القضيــة‬\n     ‫قدميــة وقــد تغيــرت أرقــام األعضــاء وأكتفــي مبــا ورد يف محضرهــم‬\n     ‫هكــذا قــرر كمــا وجــدت علــى اللفــة رقــم (‪ )14‬ســجل بيانــات للمدعــى‬\n     ‫عليــه يتضمــن وجــود ســابقة مخــدرات فنظــرا إلــى مــا دون مــن الدعــوى‬\n     ‫واإلجابــة املتضمنــة إنــكار املدعــى عليــه مــا نســب إليــه وملــا جــاء يف‬\n\n\n‫‪57‬‬\n\f‫إقــرار املدعــى عليــه حتقيقــا مــن أنــه يســتخدم الهرويــن يف الســابق‬\n‫ونظــرا لرجوعــه عــن اإلقــرار ونظــر ًا لعجــز املدعــى العــام عــن إحضــار‬\n‫بينتــه وألن الشــهادة ال بــد أن تــؤدى مشــافهة يف مجلــس احلكــم ملــا نــص‬\n‫عليــه الفقهــاء ومــن ذلــك قولهــم ( وال يجــوز للقاضــي احلكــم برؤيــة خــط‬\n‫الشــاهد احتياطـ ًا للحكــم ) انظــر كشــاف القنــاع (‪ )337/4‬وقــد نــص‬\n‫نظــام املرافعــات الشــرعية مــاده (‪ )120‬علــى أنــه ال يجــوز االســتعانة يف‬\n‫أداء الشــهادة مبذكــرات مكتوبــة بــل يجــب أن تــؤدى شــفوي ًا كمــا‬\n‫نــص نظــام اإلجــراءات اجلزائيــة علــى أن الشــهادة ال بــد أن تــؤدى يف‬\n‫مجلــس القضــاء كمــا يف املــادة (‪ )169‬ونظــر ًا ألن تخلــف الشــاهد عــن‬\n‫ا علــى تراجعــه عــن الشــهادة ومعلــوم أن الشــاهد يف‬        ‫احلضــور يعتبــر دليـ ً‬\n‫حقــوق اهلل تعالــى ال يلــزم باحلضــور وألن الشــاهد واحلالــة هــذه يعتبــر‬\n‫مجهــول وبنــاء علــى جميــع مــا تقــدم لــم يثبــت لــدي إدانــة املدعــى عليــه‬\n‫مبــا نســب إليــه وإمنــا تتوجــه لــه التهمــة بتعاطــي الهرويــن وقــررت بحقــه‬\n‫مــا يلــي أوال تعزيــر املدعــى عليــه بجلــده ســبعني جلــدة دفعــة واحــده ثانيــا‬\n‫رد طلــب املدعــي العــام إفهــام املدعــى عليــه بــأن عقابــه عــن احليــازة عائــد‬\n‫لولــي األمــر لعــدم ثبــوت مــا يدعيــه ومبــا ذكــر حكمــت فقــر احملكــوم‬\n‫عليــه قناعتــه بــه وطلــب املدعــي العــام متييــز احلكــم مكتفيــا بالئحــة‬\n‫الدعــوى عــن الالئحــة االعتراضيــة فأجبتــه لطلبــه وســيتم بعــث كامــل‬\n‫أوراق املعاملــة حلكمــة االســتئناف لتدقيــق احلكــم حســب املتبــع وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                             ‫يف ‪ 1434/04/10‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n‫مبنطقــة تبــوك بقــرار احملكمــة ومضمــون املصادقــة علــى احلكــم‬\n\n\n                                                                                         ‫‪58‬‬\n\f     ‫وصلــى اهلل علــى نبينــا محمــد والــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪59‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"c99e10bc-04e4-545e-ba4d-827d4f791349","source_page_start":54,"source_page_end":59,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ea4e3d70e1d00f86093fefed7e40738ab615d6d7a0b17d00fd4f8cfa54fd4949","normalized_text_hash":"f0247a5c4b4916503eb21d3bd4ec5e578800abb45a13180d3a1c39444d053fe5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v21-p54-34184868"}]$archive_payload$::jsonb) AS x LIMIT 25
